window.__CHRONICLE_CHUNK["cn-04"] = [
  {"id":"cn--589--p01","track":"cn","year":589,"yearApprox":false,"dim":"politics","weight":5,"title":"隋灭陈，天下复归一统","summary":"贺若弼、韩擒虎渡江入建康，陈叔宝降，南北分裂终结。","detail":{"background":"杨坚代周建隋后蓄力七年，置仓库、修新律；陈后主宠张贵妃、不修武备，沿江诸将互不统属。","process":"589年（开皇九年）正月，贺若弼自广陵、韩擒虎自横江渡采石，陈将任忠降，擒虎自朱雀门入；于景阳殿井中得叔宝，杨广为诸军元帅镇江都，二月俘陈氏王公百官入关，江南州郡相继归附，陈亡。","impact":"结束了自西晋末年以来近三百年的分裂局面，江南重入中央编户与流官体系，此后漕运与运河成为帝国的经济命脉。","figures":["杨广","贺若弼","韩擒虎","陈叔宝","高颎"],"place":"建康（今江苏南京）","state":"隋","sources":["《隋书·文帝纪》","《资治通鉴》","《南史·陈后主纪》"],"tags":["隋统一","南北终结","建康"]},"related":[]},
  {"id":"cn--590--m01","track":"cn","year":590,"yearApprox":false,"dim":"military","weight":2,"title":"江南郡县皆反与杨素东征","summary":"高智慧等以惧徙入关为辞起事，杨素造大舰水战平之。","detail":{"background":"隋平陈后征陈氏故将入关，江南士民惧于迁徙，又新颁北方法令，「由是郡县皆反」，各推故陈将领为主。","process":"590年（开皇十年）婺州汪文进、越州沈玄懀、苏州沈悰等互称天子、置百官，高智慧据建安、晋江，舟舰相衔四百余里；杨素率军自永福入山，又造大舰以火攻，连破闽越，高智慧败走被擒。","impact":"陈氏在江南的残余势力与地方豪强被清洗，隋对江南由羁縻转为直接派官，南方财赋始可为中央所用。","figures":["杨素","高智慧","沈玄懀","汪文进"],"place":"吴、会稽、建安（今苏南、浙江、福建）","state":"隋","sources":["《隋书·杨素传》","《隋书·高祖纪》","《资治通鉴》"],"tags":["江南叛乱","水战","隋治江南"]},"related":[]},
  {"id":"cn--590--p01","track":"cn","year":590,"yearApprox":false,"dim":"politics","weight":3,"title":"冼夫人定岭南，授谯国夫人","summary":"开皇十年仲宣之乱，夫人亲巡诸州，岭表遂定；册谯国夫人，开幕府。","detail":{"background":"洗氏世为南越首领，跨据山洞，部落十余万家。夫人幼贤明，多筹略，适高凉太守冯宝，与共参决辞讼，虽是亲族犯法无所舍纵，海南、儋耳归附者千余洞。","process":"开皇十年（590）番禺王仲宣反，诸俚洞响应，隋使南招不得其路。夫人遣孙讨斩其党佛智，进兵至南海，共破仲宣；亲被甲、乘介马，领彀骑卫诏使裴矩巡抚诸州，苍梧、冈州、梁化、藤州、罗州首领皆来参谒，岭表遂定。高祖异之，册夫人为谯国夫人。","impact":"岭南自宋、齐以来，俚洞相攻击之俗一以幕府而帖；隋之岭外诸州除授与诏使巡抚之例皆起于此，唐之岭南治法仍其轨。夫人卒于仁寿初，谥诚敬夫人，则六州兵马之权已随其身而止。","figures":["冼夫人","冯宝","王仲宣","裴矩"],"place":"高凉（今广东阳江、茂名一带）","state":"隋","sources":["《隋书·列女传》","《资治通鉴·隋纪一》"],"tags":["谯国夫人","高凉","岭南","俚獠"]},"related":[],"checks":[{"by":"本站·维基文库比对（《隋书》卷八十·列女传）","at":"2026-11-07","note":"原文「谯国夫人者，高凉洗氏之女也」「册夫人为谯国夫人」「仍开谯国夫人幕府，置长史以下官属，给印章，听发部落六州兵马」「仁寿初，卒，谥为诚敬夫人」；本传记仲宣起事但云「未几，番禺人王仲宣反」，不书年，故年不取本传；又本传与《通鉴》皆作「洗氏」「洗夫人」，今通行作「冼」，本条题、figures 从今作，background 与引文仍其旧，用字不一系有意为之"},{"by":"本站·维基文库比对（《资治通鉴》卷一百七十七）","at":"2026-11-07","note":"该卷「开皇十年（庚戌，公元五九零年）」条作「番禺夷王仲宣反，岭南首领多应之，引兵围广州」「高凉洗夫人遣其孙冯暄将兵救广州……更遣孙盎出讨佛智，斩之」，本条系年五百九十取此；《隋书》本传所记即同一事，唯无年；引文「岭南首领多应之」，该页作「多應多」，涉上下文重出之讹，今从通行本，异文记此"}]},
  {"id":"cn--594--d01","track":"cn","year":594,"yearApprox":false,"dim":"disaster","weight":3,"title":"关内大旱与义仓归官","summary":"关中旱饥，文帝东徙就食；社仓由民备改为官检校。","detail":{"background":"开皇十四年关中旱饥，户口滋盛而本地粮不支；长孙平于开皇五年劝民社仓备荒，积粮乡里。","process":"594年旱饥，文帝「减常馔、省乐器」，率关中饥民东徙洛阳就食，并诏开仓振给；因社仓多有虚耗，遂令「天下社仓并纳当县，官为检校」，长孙平坐此除名。","impact":"备荒粮由民间自治改为官府经手，隋末虽仓廪盈积而不敢擅开赈民，后世史家视此为隋政「有粟无民」的制度远因。","figures":["杨坚","长孙平"],"place":"长安、洛阳（今陕西西安、河南洛阳）","state":"隋","sources":["《隋书·食货志》","《隋书·长孙平传》","《资治通鉴》"],"tags":["旱灾","义仓","备荒制度"]},"related":[]},
  {"id":"cn--598--m01","track":"cn","year":598,"yearApprox":false,"dim":"military","weight":3,"title":"文帝第一次征高丽","summary":"水陆三十万出辽东，会霖雨军疫，师老而还。","detail":{"background":"高丽婴阳王数寇辽西，又不修职贡，潜通突厥；隋欲复汉氏四郡之故地，乃议东征。","process":"598年（开皇十八年）以汉王谅、王世积为行军元帅，实际由高颎、王世积经略，步骑三十万出临渝关，水军由周罗睺自东莱浮海；次辽水会霖雨连月、军中大疫，死者太半，舟军遇风漂失，粮尽而还。","impact":"第一次辽东之役以灾疫失败收场，隋室君臣未引以为戒，大业年间三征高丽终成亡国之由。","figures":["杨谅","高颎","王世积","周罗睺"],"place":"辽西、辽东（今河北秦皇岛至辽宁辽阳）","state":"隋","sources":["《隋书·高丽传》","《资治通鉴》","《隋书·文帝纪》"],"tags":["辽东之役","军疫","隋丽关系"]},"related":[]},
  {"id":"cn--600--p01","track":"cn","year":600,"yearApprox":false,"dim":"politics","weight":3,"title":"废太子勇，晋王广为皇太子","summary":"杨素构谮，独孤后召勇，废为庶人，广遂得储位。","detail":{"background":"太子勇性宽厚、好声色，晋王广外自矫饰、内结杨素与独孤皇后，「不欲王广之有美名于外」。","process":"600年（开皇二十年）仁寿宫大索东宫，得猛丐、木人，文帝以咒诅事怒勇；十月废勇为庶人，幽之，立晋王广为皇太子，旋杀东宫官属、徙柳述等；高颎、贺若弼以争太子事被免。","impact":"储位更替使开皇之治的宽松政治转向急功，炀帝即位后的三征高丽、营东京、凿运河，其工程规模皆可追溯至此一夜之变。","figures":["杨勇","杨广","杨素","独孤皇后","高颎"],"place":"大兴（今陕西西安）","state":"隋","sources":["《隋书·庶人勇传》","《隋书·文帝纪》","《资治通鉴》"],"tags":["储位之争","开皇二十年","宫廷政变"]},"related":[]},
  {"id":"cn--601--i01","track":"cn","year":601,"yearApprox":false,"dim":"institution","weight":2,"title":"隋文帝废天下学校","summary":"仁寿元年罢郡县学，唯留国子学生数十人。","detail":{"background":"开皇中令各州置学，生徒颇盛；文帝晚年以学校空费、生员不课，遂用刘劭「省学」之议。","process":"601年（仁寿元年）诏「废天下学」，国子学止留四十二人，郡县学一律罢撤，「生徒各还本贯」；其选士遂专属州贡与考试一路。","impact":"官学体系遭受第一次制度性裁撤，教育与选官相分，士人进身益趋于文辞与考试，成为唐代科举独盛、学校虚设格局的前奏。","figures":["杨坚","刘劭"],"place":"大兴及各郡县","state":"隋","sources":["《隋书·文帝纪》","《通典·学校典》","《隋书·李谔传》"],"tags":["官学","教育制度","科举前史"]},"related":[]},
  {"id":"cn--604--p01","track":"cn","year":604,"yearApprox":false,"dim":"politics","weight":4,"title":"文帝崩于仁寿宫，炀帝即位","summary":"仁寿四年帝崩于大宝殿，杨广立，旋诛柳述、囚弟谅。","detail":{"background":"文帝晚年多疑，独孤皇后崩后益信方术；晋王广与张衡、杨素在仁寿宫侍疾，朝野嚣言。","process":"604年（仁寿四年）七月文帝崩于仁寿宫大宝殿，太子广即位，秘不发丧者数日；矫诏免柳述、元岩等官，徙之岭南；囚蜀王秀废为庶人；八月汉王谅举兵于并州，杨素擒之；迁都东京之议已起。","impact":"炀帝以急骤方式取得皇位并旋即清洗宗室与顾命，其合法性疑点被后世史家反复书写；《剑桥中国隋唐史》亦谓隋廷之乱自此不可收拾。","figures":["杨坚","杨广","杨素","张衡","汉王杨谅"],"place":"仁寿宫、大兴（今陕西麟游、西安）","state":"隋","sources":["《隋书·文帝纪》","《隋书·炀帝纪》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["皇位更替","仁寿宫变","炀帝即位"]},"related":[]},
  {"id":"cn--605--i01","track":"cn","year":605,"yearApprox":false,"dim":"institution","weight":5,"title":"始建进士科，取人为科目","summary":"大业中废九品、设进士科，士人进身转归考试。","detail":{"background":"九品中正以门第取人，州郡中正在隋初已随「废郡」而失其凭；文帝开皇七年令「诸州岁贡三人」，尚兼荐举。","process":"605年前后（大业元年）炀帝「改周、隋故事，创置此科」，置进士科试策取士，「不必乡国推荐」，与诸科目并行；《通典》谓「至隋炀帝废九品，置进士等科」。","impact":"以考试成绩取代门地作为入官资格，是中国选官制度两千年来最大的一次转向，也是门阀社会终结的制度起点。","figures":["杨广","裴蕴"],"place":"东京洛阳（今河南洛阳）","state":"隋","sources":["《通典·选举典》","《隋书·炀帝纪》","《唐摭言》","《剑桥中国隋唐史》"],"tags":["科举起源","进士科","选官制度"]},"related":[]},
  {"id":"cn--605--e01","track":"cn","year":605,"yearApprox":false,"dim":"economy","weight":4,"title":"营东京，徙天下富商大贾","summary":"杨素、宇文恺营洛阳成，徙豫、冀诸州商贾实之。","detail":{"background":"关中地隘赋狭，漕运西上险阻，汉魏以来洛阳为天下之中；炀帝欲东迁以控关东与江南。","process":"605年（大业元年）命杨素、杨达、宇文恺营东京，「役夫月以二百万计」（《资治通鉴》所载数字，学界以为溢美），北据邙山、南直伊阙，宫城曰紫微；徙豫州郭下之民及贝、赵、苏等诸州「商货致远」者数万家以实之，明年正月迁都。","impact":"洛阳成为帝国新的政治与经济中枢，含嘉、洛口诸仓积粟至千万石；迁天下富商又使其成为全国最大的消费市场。","figures":["杨素","宇文恺","杨达","杨广"],"place":"东京洛阳（今河南洛阳）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","《大业杂记》"],"tags":["迁都","洛阳","商业移民"]},"related":[]},
  {"id":"cn--605--s01","track":"cn","year":605,"yearApprox":false,"dim":"science","weight":5,"title":"开通济渠，中原水路贯通","summary":"自洛阳引谷洛达河，东南入淮通江，号御河。","detail":{"background":"关中粮不支京师，江淮粟帛需北运；旧汴渠淤浅，水道不接。","process":"605年发河南、淮南诸军民百余万开通济渠，自洛阳西苑引谷、洛水入河，又循汴水东南达泗、入淮，「水面阔四十步」，缘渠筑御道，植柳；同年开邗沟，自山阳至江都达于海。","impact":"由此将黄河、淮河、长江三大水系连成一线，此后五百余年北方京师仰食东南，北宋定都开封即以此为前提。","figures":["杨广","麻叔谋","宇文恺"],"place":"通济渠、邗沟（今河南、安徽、江苏）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","全汉昇《唐宋帝国与运河》"],"tags":["大运河","水利","漕运"]},"related":[]},
  {"id":"cn--607--i01","track":"cn","year":607,"yearApprox":false,"dim":"institution","weight":3,"title":"十科举士诏","summary":"大业三年诏十科取人，诸官各举所知，无问年少。","detail":{"background":"炀帝嫌九品流弊与荐举之私，欲「皆由此途出」而以科目课士。","process":"607年（大业三年）十月诏「十科举士」：孝悌有闻、品行端悫、文才美清、学综经术、务于吏理、堪使绝域、武略雄果等十科，令「文武五品以上」各依科目推署，「四科以下，并不隔远」，并岁贡孝弟。","impact":"把荐举改造成按科目定期贡举的常科，唐代科举的「岁举」程序与分科取人体制，实由这条诏文定型。","figures":["杨广","苏威"],"place":"东京洛阳","state":"隋","sources":["《隋书·炀帝纪》","《通典·选举典》","《册府元龟·贡举部》"],"tags":["科举制度","常科","隋代选官"]},"related":[]},
  {"id":"cn--608--s01","track":"cn","year":608,"yearApprox":false,"dim":"science","weight":3,"title":"开永济渠，北通涿郡","summary":"发河北十余万丁引沁南达河、北抵涿郡。","detail":{"background":"炀帝谋讨高丽，须自黄河北运军粮戎器，旧水道不能北达幽燕。","process":"608年（大业四年）诏发河北诸军百余万开永济渠，引沁水南达于河，北通涿郡（今北京西南），「自是衣冠往还、军粮转输由此」；役夫不足，史载「妇女亦预其役」（出后世记载，学界以其数字为溢美）。","impact":"永济渠使河北、幽燕与中原水系连为一体，成为征高丽的后勤干线，也是此后唐代幽州与宋代北方边防的运输动脉。","figures":["杨广"],"place":"永济渠（今河南、山东、河北至北京）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","全汉昇《唐宋帝国与运河》"],"tags":["大运河","军运","河北"]},"related":[]},
  {"id":"cn--609--p01","track":"cn","year":609,"yearApprox":false,"dim":"politics","weight":4,"title":"炀帝西巡河右，置四郡","summary":"大破吐谷浑，登临张掖，二十七国朝会于燕支山。","detail":{"background":"吐谷浑控扼青海道，河西商路为其所扰；隋欲通西域以断其右臂。","process":"609年（大业五年）炀帝亲征，遣段文振、宇文述等分兵四合，伏允败走，尽收其地，置西海、河源、鄯善、且末四郡，徙天下徒隶实之；六月出临津关，至张掖，「高昌伯雅、伊吾吐屯设等二十七国来朝」，于燕支山大会互市。","impact":"隋的西北疆域推至青海与塔里木东缘，丝路南、北道重归国家保护之下，此局面因隋末大乱而一度中断。","figures":["杨广","宇文述","段文振","裴矩","伏允"],"place":"张掖、武威（今甘肃河西走廊）","state":"隋","sources":["《隋书·炀帝纪》","《隋书·西域传》","《资治通鉴》"],"tags":["西巡","吐谷浑","河西四郡"]},"related":[]},
  {"id":"cn--609--e01","track":"cn","year":609,"yearApprox":false,"dim":"economy","weight":3,"title":"裴矩掌互市与《西域图记》","summary":"矩在张掖监诸商胡，访其风俗为记，三道并通。","detail":{"background":"隋初河西贸易为吐谷浑所阻；黄门侍郎裴矩奉敕往张掖「知互市事」，「诱令入朝」以通西域。","process":"609年前后裴矩在敦煌、张掖招致商胡，「购嗢、利诱」使之上路，躬问其国邑、山川、户数、物产，撰《西域图记》三卷，叙自敦煌至西海三道四十八国，「今之所用，唯北、中两道」，并「请通珠环、玉、璧」诸国。","impact":"这是中国最早以官方贸易情报为基础的西域地理专书，也是隋经营丝路、复置四郡的决策依据。","figures":["裴矩","杨广"],"place":"张掖、敦煌（今甘肃河西）","state":"隋","sources":["《隋书·裴矩传》","《西域图记》序","《资治通鉴》"],"tags":["丝路贸易","互市","西域地理"]},"related":[]},
  {"id":"cn--610--s01","track":"cn","year":610,"yearApprox":false,"dim":"science","weight":3,"title":"开江南河，运河北抵涿郡南达余杭","summary":"自京口至余杭八百余里，漕渠全线始通。","detail":{"background":"隋取江南财赋而陆运劳费，六朝以来运河段多已淤浅未连。","process":"610年（大业六年）敕「发吴人开江南河」，自京口（今镇江）至余杭八百余里，「广十余丈」，使可通龙舟，并置驿宫、草驿；于是永济渠、通济渠、邗沟、江南河相接，北抵涿郡、南极余杭。","impact":"全长两千余公里的大运河体系至此成型，杭嘉湖与江淮粮赋得直达中原，此后唐宋的江南经济重心化以此为交通前提。","figures":["杨广"],"place":"江南河（今江苏镇江至浙江杭州）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","《读史方舆纪要》"],"tags":["大运河","江南水利","驿运"]},"related":[]},
  {"id":"cn--610--s02","track":"cn","year":610,"yearApprox":true,"dim":"science","weight":3,"title":"李春造赵州洨河石桥","summary":"单拱跨水三十余米，两肩复开小拱以分泄夏汛。","detail":{"background":"赵州（今河北赵县）居燕赵南北之冲，洨水当其城南，夏则水溢而旧梁辄坏，行旅苦之；隋大业间匠人李春以石为此桥。","process":"主孔作圆弧之单跨石拱，跨度约三十七米、矢高约七米，以二十八道宽狭不等之拱券并列合拢，券与券相维以固其整；两肩各开一敞肩小拱，水溢则可分泄，兼减拱身之重与拱脚之推力。唐·张嘉贞为《安济桥铭》，述之曰「赵郡洨河石桥，隋匠李春之迹也」。","impact":"此式空腹石拱为宋明石桥所沿用，其以拱圈并列、肩腹开孔的结构原则至今为拱桥所本；桥身历一千四百年水患、地震与车马之重，主体拱圈仍存，为研究隋代石作之最直接实物。","figures":["李春"],"place":"赵州洨水（今河北石家庄赵县）","state":"隋","sources":["《安济桥铭》（唐·张嘉贞）","国务院 1961 年第一批全国重点文物保护单位名单（安济桥）"],"tags":["安济桥","赵州桥","石拱桥"]},"related":["cn--1103--s01"]},
  {"id":"cn--611--m01","track":"cn","year":611,"yearApprox":false,"dim":"military","weight":4,"title":"王薄长白山起兵","summary":"作《无向辽东浪死歌》，避辽役者归之数月数万。","detail":{"background":"大业八年辽东丧师后「兵疲于外、民困于内」，河北诸郡重科军资，丁夫转相亡命。","process":"611年（大业七年冬、八年春起事）邹平人王薄于长白山（今山东章丘、邹平交界）聚众，自号「知世郎」，作《无向辽东浪死歌》以相劝，「避辽役者多归之」；刘霸道、孙安祖、窦建德等相继起，山东诸郡县多陷。","impact":"隋末民变由此从逃亡啸聚转为有口号、有地盘的武装割据，此后「大盗蜂起、郡县不能制」，帝国在两年内瓦解。","figures":["王薄","窦建德","刘霸道","孙安祖"],"place":"长白山（今山东章丘、邹平一带）","state":"隋","sources":["《资治通鉴》","《隋书·炀帝纪》","《旧唐书·窦建德传》"],"tags":["隋末民变","长白山","反辽役"]},"related":[]},
  {"id":"cn--612--m01","track":"cn","year":612,"yearApprox":false,"dim":"military","weight":3,"title":"萨水之败：辽东九军覆没","summary":"宇文述等九军三十万济辽，食尽退师，半济被击。","detail":{"background":"612年炀帝亲征高丽，分二十四军、号百万，辽东城久攻不下，另遣宇文述等率腹心九军趋平壤。","process":"612年（大业八年）宇文述等九军三十万五千渡萨水（清川江）西撤，高丽军追及，「一日行五百里」，至鸭渌水半济而击，「一日一夜」大溃，将作大匠、太守死者数十人，「还者二千七百人」，资粮器械委弃如山。","impact":"隋军精锐在辽东一战丧尽，炀帝不得不两次停再举，而「利在关东」的征发与逃户已不可遏，隋亡之局已定。","figures":["宇文述","于仲文","杨义臣","乙弗弘礼"],"place":"萨水、鸭渌水（今朝鲜半岛清川江、鸭绿江）","state":"隋","sources":["《隋书·宇文述传》","《资治通鉴》","《三国史记》"],"tags":["萨水之战","辽东之役","隋末"]},"related":[]},
  {"id":"cn--613--p01","track":"cn","year":613,"yearApprox":false,"dim":"politics","weight":3,"title":"杨玄感起兵围东都","summary":"礼部尚书乘辽东再举，截漕粮，围洛阳三月而败。","detail":{"background":"玄感袭父杨素爵，为炀帝所忌，「常居守」东都；会帝二征高丽，「士民疲病」，乃与蒲山公李密谋起事。","process":"613年（大业九年）六月玄感在黎阳督运，「徙漕船」使不得下，杀御史，众至数万，攻东都不克，西图入关而失利，围洛阳三月；屈突通、来护儿兵至，西入关中不利，奔平原，为其弟所杀，传首行在，「党与死者数万人」。","impact":"关陇统治集团第一次从内部破裂，炀帝此后以「玄感党与」为名对关东士族大加清洗，李密、杜伏威诸势力皆在其乱局中壮大。","figures":["杨玄感","李密","杨素","屈突通"],"place":"黎阳、东都（今河南浚县、洛阳）","state":"隋","sources":["《隋书·杨玄感传》","《资治通鉴》","《旧唐书·李密传》"],"tags":["杨玄感之乱","关陇集团","隋末"]},"related":[]},
  {"id":"cn--615--m01","track":"cn","year":615,"yearApprox":false,"dim":"military","weight":3,"title":"突厥围炀帝于雁门","summary":"始毕可汗忽率骑数十万围城四十余日，援集乃解。","detail":{"background":"炀帝欲以宗女嫁处罗可汗、分突厥之势，计不成，始毕可汗由是不悦；北巡之诏既下，突厥谋袭乘舆。","process":"615年（大业十一年）八月炀帝北幸至雁门（今山西代县），突厥始毕可汗忽率骑数十万「四面围城数十重」，「矢及御前」，十五郡兵救援未集，城中大惧；帝纳萧后之言乃下诏停辽东之役，引援军至，九月围解，「后论功，守雁门者并不叙」，自此不复北巡。","impact":"隋与草原政权的力量对比就此翻转，北边自此由威慑转为守御；炀帝南幸江都、委弃关东，其决策亦以此为转折。","figures":["杨广","始毕可汗","萧皇后","樊子盖"],"place":"雁门（今山西代县）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","《旧唐书·突厥传》"],"tags":["雁门之围","突厥","隋代北疆"]},"related":[]},
  {"id":"cn--617--p01","track":"cn","year":617,"yearApprox":false,"dim":"politics","weight":4,"title":"李渊太原起兵，入长安","summary":"杀副留守、结突厥，自晋阳西行，十一月平关中。","detail":{"background":"炀帝久驻江都，关中兵虚粮乏；李渊为太原留守，与次世民密谋，刘文静劝「结突厥以求马」。","process":"617年（大业十三年）五月李渊斩副留守王威、高君雅，称兵于晋阳；七月自太原西入，克霍邑、临汾，平阳公主军迎，十一月入长安，立代王侑为帝（隋恭帝），渊自为大丞相、封唐王；618年五月受禅。","impact":"取关中而奉隋宗室，是李唐迅速获得合法性与粮兵两便的关键一步；陈寅恪所谓「关中本位政策」之再显，亦指此类地缘抉择。","figures":["李渊","李世民","刘文静","裴寂","李建成"],"place":"晋阳、长安（今山西太原、陕西西安）","state":"隋／唐","sources":["《旧唐书·高祖纪》","《资治通鉴》","陈寅恪《唐代政治史述论稿》"],"tags":["太原起兵","唐开国","关中"]},"related":[]},
  {"id":"cn--618--p01","track":"cn","year":618,"yearApprox":false,"dim":"politics","weight":4,"title":"李渊受禅建唐","summary":"恭帝禅位于太极殿，渊即皇帝位，改元武德，国号唐。","detail":{"background":"李渊入长安后立代王侑、自为大丞相唐王，袭唐国公旧号以为国名；关中未定而隋帝远在江都。","process":"618年（武德元年）五月隋恭帝禅位于太极殿，李渊即皇帝位，改元武德，立建成为皇太子、世民为尚书令；追尊四代，以裴寂为右仆射、刘文静为纳言，一如隋制置三省六部。","impact":"唐以禅代而非异族征服取得皇统，律令、田制、官制尽承隋旧，关陇军事贵族与新朝合流，开了近三百年唐室之局。","figures":["李渊","李建成","李世民","裴寂","刘文静"],"place":"长安太极殿（今陕西西安）","state":"唐","sources":["《旧唐书·高祖纪》","《新唐书·高祖纪》","《资治通鉴》"],"tags":["唐开国","禅代","武德"]},"related":[]},
  {"id":"cn--618--m01","track":"cn","year":618,"yearApprox":false,"dim":"military","weight":3,"title":"江都之变：炀帝见弑","summary":"宇文化及率骁果入宫缢杀炀帝，隋中枢就此崩溃。","detail":{"background":"从幸江都的骁果皆关东人，久客思归、逃亡相继，司马德戡、赵行枢等密谋北返，推许国公宇文化及为首。","process":"618年三月，裴虔通、司马德戡夜启城门入宫，炀帝被缢死，年五十，萧后与诸宫人无主者数百；化及自称大丞相，率骁果十余万西归，为李密所拒于童山，北走魏县，次年称帝，旋为窦建德所杀。","impact":"皇帝死于禁军之手使隋的法统彻底破产，北方诸势力皆得各自称「为隋讨逆」，唐在两年内以较小代价逐个剪除关东群雄。","figures":["杨广","宇文化及","司马德戡","裴虔通"],"place":"江都（今江苏扬州）","state":"隋","sources":["《隋书·炀帝纪》","《资治通鉴》","《北史·隋本纪下》"],"tags":["江都之变","骁果","弑君"]},"related":[]},
  {"id":"cn--621--m01","track":"cn","year":621,"yearApprox":false,"dim":"military","weight":5,"title":"虎牢一战：擒窦建德、降王世充","summary":"李世民以骑据武牢，破夏军于牛口渚，还降郑主。","detail":{"background":"620年唐军攻洛阳，王世充称郑帝；621年春窦建德自河北来救，众十万屯成皋，唐诸将以腹背受敌请班师。","process":"621年（武德四年）四月李世民据武牢之险与相持，建德列阵自辰至午、士卒坐地思食，唐骑将李君羡先突其阵，世民亲率骑纵击其后，夏军大溃，生擒建德于牛口渚；五月世充举洛阳降，河朔郡县传檄而定。","impact":"一战并两强，唐有中原与河北，统一战争胜负已决；此役积累的军功与秦王府人才集团，直接通向五年后的玄武门之变。","figures":["李世民","窦建德","王世充","李君羡","尉迟敬德"],"place":"武牢、洛阳（今河南荥阳汜水、洛阳）","state":"唐","sources":["《旧唐书·太宗纪》","《资治通鉴》","《旧唐书·窦建德传》"],"tags":["虎牢关之战","唐统一","以少击众"]},"related":[]},
  {"id":"cn--621--e01","track":"cn","year":621,"yearApprox":false,"dim":"economy","weight":4,"title":"铸开元通宝，五铢旧钱遂废","summary":"废隋末杂钱，行开元通宝，千钱重六斤四两。","detail":{"background":"隋末币制大坏，五铢轻小、剪凿铅铁并行，货贱物贵，「商贾无所取则」。","process":"621年（武德四年）七月诏废五铢钱、行开元通宝，青铜铸之，每千钱重六斤四两，钱文「开元通宝」传为欧阳询八分书、回环可读，「日用之货，自此而一」。","impact":"中国货币自此脱离以斤两重量为钱名的古制，「某某通宝」的体例沿用至清末一千三百余年，并影响日本和铜钱与朝鲜铸钱。","figures":["李渊","欧阳询"],"place":"长安诸钱监（今陕西西安）","state":"唐","sources":["《旧唐书·食货志》","《唐会要·钱》","《通典·食货典》"],"tags":["货币改革","开元通宝","钱法"]},"related":[]},
  {"id":"cn--624--i01","track":"cn","year":624,"yearApprox":false,"dim":"institution","weight":4,"title":"武德令：均田、租庸调与府兵","summary":"定丁男受田百亩之制，行租庸调，置军府以宿卫。","detail":{"background":"隋末田荒户散，唐初须同时解决兵源、赋役与流民安置三事，「欲使家给人足、兵农合一」。","process":"624年（武德七年）二月颁新令：丁男、中男受田一顷，其中世业（永业）二十亩、口分八十亩，老幼笃疾有差，「狭乡」不予；赋则「有田出租、有身出庸、有户出调」；军制置骠骑、车骑府（后改折冲都尉府），关内置府最多。","impact":"田制、役法、兵制三者互相咬合，使唐初以小农经济供养府兵与低赋率，构成「关中本位」的财政—军事体制，亦为贞观之治的底子。","figures":["李渊","裴寂","长孙无忌"],"place":"长安（令行于全国，军府聚于关中）","state":"唐","sources":["《唐六典·兵部》","《旧唐书·食货志》","《通典·食货典》","陈寅恪《唐代政治史述论稿》"],"tags":["均田制","租庸调","府兵制"]},"related":[]},
  {"id":"cn--626--p01","track":"cn","year":626,"yearApprox":false,"dim":"politics","weight":5,"title":"玄武门之变","summary":"世民伏甲太极宫北掖门，杀建成元吉，旋立为太子。","detail":{"background":"秦王与太子建成、齐王元吉争位已久，626年夏突厥入寇，建成荐元吉代世民督师，并欲夺府中骁将。","process":"626年（武德九年）六月初四世民上变，高祖召三子往质之；建成、元吉入玄武门，伏甲发，建成死于门下、元吉中矢毙，尉迟敬德擐甲持矛宿卫高祖，请「下手诏」；是月上旬立世民为皇太子，八月高祖称太上皇，世民即位于东宫显德殿。","impact":"以流血宫变夺得继承权，开了唐代皇位「非长非幼、唯力是视」的先例；此后玄宗、肃宗直至文宗朝的宫廷政变，皆以玄武门为故事。","figures":["李世民","李建成","李元吉","李渊","尉迟敬德","长孙无忌"],"place":"太极宫玄武门（今陕西西安）","state":"唐","sources":["《旧唐书·太宗纪》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["玄武门之变","皇位继承","贞观"]},"related":[]},
  {"id":"cn--626--m01","track":"cn","year":626,"yearApprox":false,"dim":"military","weight":3,"title":"渭水便桥：刑白马退突厥","summary":"颉利二十万骑至泾阳，帝隔水数盟，便桥而盟退。","detail":{"background":"玄武门之变后两月，突厥颉利、突利二可汗乘唐有内丧，号二十万骑南下，泾阳、武功烽烟相接，诸将请闭壁。","process":"626年八月太宗与高士廉、房玄龄等六骑径至渭水，隔水数颉利负盟之罪，诸军旌甲被野继至；颉利请和，乃临便桥刑白马为盟，唐赐金帛大遣之，突厥引退。","impact":"以一次近乎示弱的谈判换取三年喘息。贞观三年唐即北伐，太宗屡引便桥之事自诫，「未尝一日忘」此辱，成为其灭东突厥的心理动力。","figures":["李世民","颉利可汗","房玄龄","高士廉"],"place":"渭水便桥（今陕西咸阳东）","state":"唐","sources":["《资治通鉴》","《旧唐书·突厥传》","《贞观政要·征伐》"],"tags":["渭水之盟","突厥","北边防务"]},"related":[]},
  {"id":"cn--627--i01","track":"cn","year":627,"yearApprox":false,"dim":"institution","weight":3,"title":"贞观并省州县，分天下为十道","summary":"以山川形便分十道，省官吏，定京官六百四十三员。","detail":{"background":"武德以来「率数州之地为百姓置官」，侨置州县林立，官多民少，赋输不足以奉吏。","process":"627年（贞观元年）省并州县，「大则置府、小则为州」，依山川形便分天下为关内、河南、河东、河北、山南、陇右、淮南、江南、剑南、岭南十道；又裁省内外官，史载留京官六百四十三员。","impact":"唐代州—县二级制与「道」的观察区划由此定型，十道之后为开元十五道、宋代之路，是中国高层政区演化的中间环节。","figures":["李世民","房玄龄","杜如晦"],"place":"长安（政令行于十道）","state":"唐","sources":["《旧唐书·地理志》","《贞观政要·论政体》","《唐会要·州郡》"],"tags":["十道","地方行政","省官"]},"related":[]},
  {"id":"cn--629--x01","track":"cn","year":629,"yearApprox":true,"dim":"explore","weight":3,"title":"玄奘私度西行求法","summary":"冒禁出玉关，越莫贺延碛，历高昌赴那烂陀。","detail":{"background":"隋末乱后关陇饥馑，朝廷禁百姓出塞；玄奘以中土经论互异、旧译多阙，累表请求往印度取本，有司不报。","process":"629年（贞观三年，一说627年）玄奘随商旅私度，至瓜州依胡人石磐陀，越玉关、上莫贺延碛，「四夜五日无一滴水」，西至高昌，王麴文泰结为兄弟、资送西行；历屈支、凌山、碎叶，至那烂陀寺从戒贤受《瑜伽师地论》，凡十七年、行五万余里。","impact":"归国后所译经论与《大唐西域记》（646年撰成）成为中古印度、中亚史地第一手材料，那烂陀之学由此输入，唯识一系赖以建立。","figures":["玄奘","戒贤","麴文泰","石磐陀"],"place":"长安至那烂陀（今印度比哈尔邦巴劳特）","state":"唐","sources":["《大慈恩寺三藏法师传》","《大唐西域记》","《旧唐书·方技传》"],"tags":["西行求法","那烂陀","中印交通"]},"related":[]},
  {"id":"cn--630--m01","track":"cn","year":630,"yearApprox":false,"dim":"military","weight":5,"title":"李靖夜袭阴山，灭东突厥","summary":"三千骑出恶阳岭破定襄，夜袭牙帐，颉利被擒。","detail":{"background":"627年后突厥连年雪灾、畜产多死，又税敛无度，薛延陀、回纥并叛；太宗以颉利再寇代州为辞，分道北伐。","process":"630年（贞观四年）正月李靖率骁骑三千自马邑进屯恶阳岭，夜袭定襄破之，颉利保阴山，托辞请降；靖乘雾进兵，夜至其牙帐，斩首万余级、获部落数万，颉利单骑西北走，将依吐谷浑，为唐将张宝相所擒送京师，漠南之地尽平。","impact":"草原第一汗国覆灭，唐取得东亚与西域的霸权，回纥、室韦诸部内属；「中国既安，四夷自服」自此成为太宗对外政策的自我解释。","figures":["李靖","李世勣","颉利可汗","李世民","张宝相"],"place":"定襄、白道、阴山（今内蒙古呼和浩特北）","state":"唐","sources":["《旧唐书·李靖传》","《资治通鉴》","《隋书·突厥传》","《旧唐书·突厥传》"],"tags":["灭东突厥","夜袭阴山","草原格局"]},"related":[]},
  {"id":"cn--630--p01","track":"cn","year":630,"yearApprox":false,"dim":"politics","weight":4,"title":"西北诸藩上「天可汗」尊号","summary":"四夷君长诣阙请兼可汗之号，唐敕并行于蕃部。","detail":{"background":"东突厥亡后，其部落或北附薛延陀、欲西走西域，「夷人」咸集阙下；唐议处降众，魏征主遣还河北，温彦博主留之。","process":"630年四月西北诸藩请「天可汗」之号，太宗从「爱之如一」之说受之，自是降敕书与蕃君长并称天可汗；用温彦博议，「全其部落、顺其土俗」，自幽州至灵州置羁縻府州处之，「酋长拜将军中郎将者百余人，入居长安者数千家」。","impact":"唐皇以天子与可汗的双重身份统摄农耕与游牧，形成册封—质子—羁縻府州的东亚秩序；粟特、突厥、于阗贵族大量入唐为将相。","figures":["李世民","温彦博","魏征","突利可汗","阿史那社尔"],"place":"长安；灵州至幽州边地","state":"唐","sources":["《资治通鉴》","《旧唐书·突厥传》","《唐会要》","《剑桥中国隋唐史》"],"tags":["天可汗","羁縻府州","华夷一体"]},"related":[]},
  {"id":"cn--636--f01","track":"cn","year":636,"yearApprox":false,"dim":"figure","weight":2,"title":"长孙皇后崩，所撰《女则》传世","summary":"少好读书，未尝预政；撰《女则》以自鉴，崩年三十六。","detail":{"background":"长孙氏为秦王妃时即「造次必于礼法」，既正位中宫，「凡言语及政事，帝问者终不对」，退朝则屡称魏征之直。","process":"636年（贞观十年）六月崩于立政殿，年三十六，遗命「因山为葬，无缮封树，以瓦木之器」，葬昭陵；所撰《女则》三十余卷，录古妇人成败以自警戒，帝览之悲恸，以示百僚而叹其「实可用之朝廷」。","impact":"其「不预政」的自我限定成为唐代后妃政治的正面典范，与武后、韦后、太平公主一路构成对照；《女则》今佚，仅《宋史·艺文志》著录其目。","figures":["长孙皇后","李世民","李承乾"],"place":"长安立政殿；昭陵（今陕西礼泉）","state":"唐","sources":["《旧唐书·后妃传》","《唐会要·皇后》","《宋史·艺文志》"],"tags":["后妃","女性写作","昭陵"]},"related":[]},
  {"id":"cn--637--i01","track":"cn","year":637,"yearApprox":false,"dim":"institution","weight":4,"title":"《贞观律》成，比古死刑除其半","summary":"长孙无忌等定律五百条，宽简于隋，立三复奏。","detail":{"background":"武德律犹多隋代深文，太宗命房玄龄、长孙无忌「勒成一部」，又采魏征「明刑弼教」之议，务在宽简。","process":"637年（贞观十一年）《贞观律》七百二十五条成，「减大辟九十二条、流入徒者七十一条」，凡削繁去蠹不可胜纪；仍五刑、十恶、八议之目，又定死刑「三复奏」、在京「五复奏」，「有司不敢仓猝决杀」。","impact":"此律即《唐律疏议》之本，中国现存最早完整成文法典由此定型，并为日本《大宝律令》、朝鲜高丽与越南立法所承，构成东亚法系。","figures":["长孙无忌","房玄龄","李世民","魏征"],"place":"长安（颁行天下）","state":"唐","sources":["《唐律疏议》序","《旧唐书·刑法志》","《资治通鉴》"],"tags":["唐律","慎刑","东亚法系"]},"related":[]},
  {"id":"cn--641--p01","track":"cn","year":641,"yearApprox":false,"dim":"politics","weight":4,"title":"文成公主入吐蕃","summary":"以宗室女妻松赞干布，命李道宗持节护送。","detail":{"background":"638年后吐蕃陷吐谷浑、攻松州请婚，唐初不许；640年赞普复遣大相禄东赞献金鹅、奉表固请。","process":"641年（贞观十五年）正月唐以宗室女文成公主妻之，命江夏王李道宗持节送之；公主入藏，资以释迦像、谷种、百工、医药与历算，吐蕃「为公主别筑宫室城邑」，赞普自「执子婿之礼」，遣贵臣子弟入国学。","impact":"唐蕃维持约三十年相对和平，佛教与中原技术入藏之路由此洞开；唐亦在河西—青海方向取得牵制吐谷浑、护卫丝路南翼的支点。","figures":["李世民","松赞干布","禄东赞","文成公主","李道宗"],"place":"长安逻些（今陕西西安、西藏拉萨）","state":"唐／吐蕃","sources":["《旧唐书·吐蕃传》","《资治通鉴》","《敦煌吐蕃历史文书》"],"tags":["和亲","唐蕃关系","汉藏交通"]},"related":[]},
  {"id":"cn--643--f01","track":"cn","year":643,"yearApprox":false,"dim":"figure","weight":3,"title":"魏征卒，帝亲为碑文","summary":"谏诤二百余事，帝以「人镜」比之；卒后旋命仆碑。","detail":{"background":"魏征少落魄，初事李密、后为太子洗马，建成深礼重之；玄武门后面折廷争，前后陈谏二百余事，帝每屈己从之。","process":"643年（贞观十七年）正月征疾笃，帝遣太子亲至其第问朝政得失，亲为书疏；二月卒，帝为撰碑文，谓「以铜为镜可正衣冠，以人为镜可明得失，今魏征殁，一镜亡矣」。未几因侯君集案及征录前后谏辞示史官，帝怒，命仆所立碑。","impact":"谏诤制度的效力与脆弱集中于此一身：碑仆而复立，后世君臣皆以「贞观之魏征」为言路理想，也成为史官记事与皇权相争的原型案例。","figures":["魏征","李世民","侯君集","褚遂良"],"place":"长安；昭陵陪葬（今陕西礼泉）","state":"唐","sources":["《旧唐书·魏征传》","《贞观政要·纳谏》","《资治通鉴》"],"tags":["谏诤","史官","贞观名臣"]},"related":[]},
  {"id":"cn--645--m01","track":"cn","year":645,"yearApprox":false,"dim":"military","weight":3,"title":"太宗亲征高丽，顿于安市","summary":"克辽东诸城、破驻跸山，安市不下，以寒早班师。","detail":{"background":"642年泉盖苏文弑其王自立，兼攻新罗；新罗告急，太宗以「讨不臣、为百姓」为议，决计亲征。","process":"645年（贞观十九年）二月帝自将，号十万（诸书所记兵数不一），渡辽；张亮浮海取卑沙城，李世勣克辽东城，驻跸山一战「斩首二万余级」；进围安市城（今辽宁海城）月余不下，会辽左早寒、草枯粮尽，诏班师，途中遣使祭阵亡士卒。","impact":"唐以正面消耗未能破局，而高丽元气已损；此后高宗改用「先取百济、浮江北上」的南北并进方案，正由此役教训而来。","figures":["李世民","李世勣","张亮","泉盖苏文","长孙无忌"],"place":"辽东、驻跸山、安市（今辽宁辽阳、海城）","state":"唐","sources":["《资治通鉴》","《旧唐书·高丽传》","《三国史记》"],"tags":["唐征高丽","驻跸山","安市城"]},"related":[]},
  {"id":"cn--648--a01","track":"cn","year":648,"yearApprox":true,"dim":"art","weight":3,"title":"《兰亭序》真迹入内府","summary":"萧翼计取辩才所藏，太宗命双钩廓填以传。","detail":{"background":"王羲之《兰亭集序》稿本传至七世孙、越州永欣寺僧辩才，太宗访求累年不得，乃「密访其人」。","process":"648年前后（贞观二十二年）御史萧翼以太生服色入寺，与辩才共论书画，出所携梁陈遗迹诱其出内库真迹，遂以诏取之；帝命赵模、韩道政、冯承素、诸葛贞等双钩廓填，赐近臣，真迹随葬昭陵。","impact":"此一传说所代表的内府收书，使王羲之在唐初被定「书圣」之位；今传神龙本摹成为行书第一范本，而其代价是六朝真迹的永久消失。","figures":["李世民","萧翼","辩才","褚遂良","冯承素"],"place":"越州永欣寺、长安内府（今浙江绍兴）","state":"唐","sources":["《法书要录》","《兰亭记》","《旧唐书·褚遂良传》"],"tags":["书法史","兰亭序","内府收藏"]},"related":[]},
  {"id":"cn--649--p01","track":"cn","year":649,"yearApprox":false,"dim":"politics","weight":4,"title":"太宗崩于翠微宫，高宗即位","summary":"疾笃于含风殿，无忌、遂良受顾命，太子治立。","detail":{"background":"太宗晚年服方士金石之药，649年春疾笃于翠微宫含风殿，太子李治侍疾不解带；储位曾几度动摇，帝以无忌、遂良为托。","process":"649年五月太宗崩，年五十二；长孙无忌恐京邑有变，勒兵宫掖而后发丧，与褚遂良奉遗诏辅政，太子即位（高宗），大赦，罢「辽东屯兵」之议，仍守《贞观律令》，史称永徽初政「有贞观遗风」。","impact":"高宗以仁弱承业，实权先落顾命集团、后移武后；655年废王立武、逐无忌于外，即为此一「舅辅甥君」结构被皇后打破的结果。","figures":["李世民","李治","长孙无忌","褚遂良","武曌"],"place":"翠微宫含风殿（今陕西西安蓝田）","state":"唐","sources":["《旧唐书·太宗纪》","《新唐书·高宗纪》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["太宗崩","顾命政治","永徽"]},"related":[]},
  {"id":"cn--652--s01","track":"cn","year":652,"yearApprox":true,"dim":"science","weight":3,"title":"孙思邈《千金要方》撰定","summary":"集唐以前方剂，立大医精诚之论，为临床百科之祖。","detail":{"background":"隋末唐初方书散乱，一药一方之费或至倾产；京兆华原人孙思邈博访古今药方，累年编次。","process":"约652年前后（永徽三年）《千金要方》三十卷成，分方脉、脏腑、妇人、少小、养性、针灸、解毒诸门，收方五千余首，卷首列「大医精诚」「大医习业」以论医者品行；其后又撰《千金翼方》三十卷补之。","impact":"中国第一部体系完整的临床百科性方书由此成立，妇、儿二科单列，针灸与食治并重；其书东传日本、朝鲜，宋林亿等校定本为今通行本。","figures":["孙思邈"],"place":"京兆华原（今陕西铜川耀州区）","state":"唐","sources":["《备急千金要方》序","《旧唐书·孙思邈传》","《新唐书·隐逸传》"],"tags":["医学","方书","医德"]},"related":[]},
  {"id":"cn--655--p01","track":"cn","year":655,"yearApprox":false,"dim":"politics","weight":4,"title":"立武氏为皇后，顾命集团瓦解","summary":"李勣「陛下家事」一言定策，无忌、遂良相继贬死。","detail":{"background":"高宗以王皇后无子、武昭仪有宠，欲立为后而惮顾命大臣；褚遂良以「必欲易之，请不召臣」谏，长孙无忌密谏尤切。","process":"655年（永徽六年）十月，李勣以「此陛下家事，何必更问外人」定策，高宗废王皇后、萧淑妃，立武氏为皇后；遂良累贬爱州刺史，659年无忌坐许敬宗所构「逆谋」削爵、流黔州而被迫自缢，此后政事多出天后。","impact":"关陇顾命集团被摧毁，皇权借后族与新兴官僚重建；武后由此取得参政权，二十年后改唐为周的路径即始于这一「家事」之说。","figures":["李治","武曌","李勣","长孙无忌","褚遂良"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·高宗纪》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["废王立武","外戚","宫廷政治"]},"related":[]},
  {"id":"cn--659--s01","track":"cn","year":659,"yearApprox":false,"dim":"science","weight":4,"title":"《新修本草》成，官修药典之始","summary":"诏苏敬等重定本草，兼图经，颁天下为医学课本。","detail":{"background":"陶弘景《本草经集注》行用既久，虫兽草木「州土不同」；657年（显庆二年）诏右监门府长史苏敬与长孙无忌、李勣等二十余人重定本草，征天下诸郡所出药物图样。","process":"659年（显庆四年）《新修本草》撰成上之，凡本草二十卷、目录一卷、图经二十五卷，载药八百五十余种，较旧本新定一百一十四种，药、图、经三件并行，诏颁诸州，与《甲乙》《难经》同为医生习业之科。","impact":"这是最早由国家编定并颁行的法定药典，比欧洲最早的官修药典（十六世纪纽伦堡本）早近九百年；其图文互证之法为后世本草所宗。","figures":["苏敬","长孙无忌","李勣"],"place":"长安、洛阳（今陕西西安、河南洛阳）","state":"唐","sources":["《新修本草》序","《唐六典·太医署》","《旧唐书·经籍志》"],"tags":["官修药典","本草","医学教育"]},"related":[]},
  {"id":"cn--663--m01","track":"cn","year":663,"yearApprox":false,"dim":"military","weight":3,"title":"白江口：唐倭水战与百济平","summary":"刘仁轨四战皆捷，焚倭船四百艘，海水尽赤。","detail":{"background":"660年苏定方虏百济义慈王后，其旧将福信、浮屠道心拥故王子扶余丰复起，请援于倭国；663年倭国遣使率船百七十余艘、兵二万余入熊津江。","process":"663年（龙朔三年）八月，唐右领军卫将军刘仁轨与孙仁师会军于白江口（今韩国锦江下游），倭船布列两岸，仁轨四战皆克，焚其舟四百艘，烟焰灼天、海水尽赤；扶余丰走投高丽，余众尽降，唐于其地置熊津等五都督府。","impact":"东亚史上第一次有大军渡海作战的战役以唐胜终，百济故地入唐势力圈；倭国自此转向律令内政与遣唐使，半岛形成新罗与唐对峙之局。","figures":["刘仁轨","孙仁师","扶余丰","苏定方"],"place":"白江口、熊津（今韩国扶余、公州一带）","state":"唐","sources":["《旧唐书·刘仁轨传》","《资治通鉴》","《三国史记》","《日本书纪》"],"tags":["白江口之战","渡海作战","东亚国际关系"]},"related":["world--663--m01"]},
  {"id":"cn--668--m01","track":"cn","year":668,"yearApprox":false,"dim":"military","weight":4,"title":"唐灭高丽，置安东都护府","summary":"李勣围平壤，高藏出降，分其地置九州府。","detail":{"background":"666年泉男生、男建兄弟相攻，男生奉表内附；唐数遣薛仁贵、契苾何力出辽东，高丽连年饥馑、人心离析。","process":"668年（总章元年）九月，李勣督诸军进围平壤，高丽拒战之兵大败，男建自杀不遂被擒，藏王高藏出降，送于京师；分其境置九都督府、四十二州、县一百，徙高丽豪杰与民户入淮南、山南、京西，以薛仁贵检校安东都护，将兵二万镇平壤。","impact":"汉魏以来的辽东问题至此暂结，唐疆东至大同江；但新罗北上争三郡之地，唐与新罗交兵数岁，676年安东都护府内徙辽东，半岛统一归于新罗。","figures":["李勣","薛仁贵","高藏","泉男生","泉男建"],"place":"平壤（今朝鲜平壤）","state":"唐","sources":["《旧唐书·高丽传》","《资治通鉴》","《三国史记》"],"tags":["灭高丽","安东都护府","辽东"]},"related":[]},
  {"id":"cn--670--m01","track":"cn","year":670,"yearApprox":false,"dim":"military","weight":3,"title":"大非川之败：吐蕃并吐谷浑","summary":"薛仁贵军失辎重于乌海，大非川举军陷没。","detail":{"background":"吐蕃自大论钦陵专兵，663年后并吐谷浑；670年唐以薛仁贵为大行军总管，将骑五万，护送吐谷浑可汗诺曷钵还故地。","process":"670年（咸亨元年）六月，仁贵进至大非川（今青海玛多、黄河源一带），留辎重命郭待封守之；待封违节度，进至乌海，粮为吐蕃所掠，士马不得食，钦陵以二十万众要击，唐军大溃，只轮不返，前军总管刘审礼没于阵。","impact":"唐在青藏高原方向受挫，吐谷浑汗国就此亡，吐蕃成为与唐长期对峙的西方大国；安西四镇此后数度陷没，为唐代西北边防最重的负担。","figures":["薛仁贵","郭待封","论钦陵","诺曷钵"],"place":"大非川、乌海（今青海青南高原）","state":"唐／吐蕃","sources":["《旧唐书·薛仁贵传》","《新唐书·吐蕃传》","《资治通鉴》","《敦煌吐蕃历史文书》"],"tags":["大非川","吐蕃兴起","西北边防"]},"related":[]},
  {"id":"cn--684--p01","track":"cn","year":684,"yearApprox":false,"dim":"politics","weight":3,"title":"则天废中宗，临朝称制","summary":"惜一侍中而失天下，帝为庐陵王，太后自决大政。","detail":{"background":"683年十二月高宗崩，太子显即位（中宗）；欲以后父韦玄贞为侍中，中书令裴炎执不可，帝怒曰「我让韦玄贞与作天子，何为不可，而惜侍中邪」。","process":"684年（嗣圣元年）二月，裴炎以是言密告皇太后，武氏遂废中宗为庐陵王、幽于内殿，立豫王旦（睿宗），帝唯得坐便殿受小大之政，太后自御大朝决军国之务，九月改元文明；同年诛韩王元嘉、鲁王灵夔等宗室。","impact":"女主以太后之尊连废二帝，唐室宗藩与府兵旧将由此离心；徐敬业之乱与越王贞之乱相继被平，则天乃得从容代唐。","figures":["武曌","李显","李旦","裴炎","韦玄贞"],"place":"洛阳、长安（今河南洛阳、陕西西安）","state":"唐","sources":["《旧唐书·中宗纪》","《资治通鉴》","《新唐书·则天皇后传》"],"tags":["废立","太后临朝","武周前史"]},"related":[]},
  {"id":"cn--684--m01","track":"cn","year":684,"yearApprox":false,"dim":"military","weight":2,"title":"徐敬业扬州起兵","summary":"以匡复庐陵为辞，旬日众十万，淮上三月而败。","detail":{"background":"684年秋，故司空李勣之孙李敬业（本姓徐）以匡复庐陵为旗据扬州，骆宾王为之草《代李敬业传檄天下文》，「一抔之土未干，六尺之孤何托」传入都中。","process":"684年九月敬业起兵，自称匡复府上将、领扬州大都督，旬日众至十万，陷润州；诸将争「径渡江取楚泗」与「保本常润」二策不决，顿兵经月。则天命玉钤卫大将军李孝逸将兵三十万讨之，从魏元忠「先破其精锐」之上策，一战而溃，敬业走海陵，为部下所杀，传首东都。","impact":"江南士人对女主改政最大的一次公开反抗三个月瓦解；则天由此大设铜匦、行告密、任用酷吏，以清洗代替安抚，直趋690年革唐命。","figures":["李敬业","骆宾王","李孝逸","魏元忠","武曌"],"place":"扬州、润州（今江苏扬州、镇江）","state":"唐","sources":["《旧唐书·李敬业传》","《资治通鉴》","《骆丞集》"],"tags":["扬州之乱","讨武曌檄","酷吏政治"]},"related":[]},
  {"id":"cn--689--a01","track":"cn","year":689,"yearApprox":false,"dim":"art","weight":2,"title":"洛阳造明堂、天堂","summary":"毁乾元殿作万象神宫，铁凤金环，与天堂相属。","detail":{"background":"则天欲以《周礼》明堂之制代唐受朝之所，乃毁乾元殿，以其地作明堂，日役万人，自总监其功。","process":"689年（永昌元年）明堂成：基下施铁渠以象四海，中架巨木，上置铁凤、饰以金环，号曰万象神宫，就其中以「享献、受朝、布政」；又于其北造天堂以贮大像，695年天堂火、延及明堂，更造更名通天宫。","impact":"这是中古中国礼制木构最大胆的一次实验，以明堂之名立女主之政；洛阳隋唐城遗址的明堂基槽与柱础发掘，已证实其平面与规模。","figures":["武曌","薛怀义"],"place":"洛阳宫城乾元殿故地（今河南洛阳）","state":"唐／武周","sources":["《旧唐书·礼仪志》","《唐会要·明堂》","《资治通鉴》","洛阳隋唐城明堂遗址考古简报"],"tags":["建筑","礼制","武周"]},"related":[]},
  {"id":"cn--690--p01","track":"cn","year":690,"yearApprox":false,"dim":"politics","weight":5,"title":"革唐命，武周受代","summary":"改国号周，自名曌，亲策贡士于洛成殿。","detail":{"background":"688年洛水出「圣母临人」符石，诸色符命纷进；690年僧徒上《大云经疏》，王庆之率徒八百人诣阙请改唐为周，狄仁杰廷折其议。","process":"690年（天授元年）九月则天御则天楼，赦天下，改国号曰周，自名「曌」，加尊号圣神皇帝，以豫王旦为皇嗣、姓武氏，追尊周文王为始祖，改唐太庙为享德庙；十月亲策应制举人于洛成殿，数日乃罢。","impact":"中国史上唯一一次女主易姓革命告成，唐室宗藩、关陇门第与府兵旧贵在二十年间被系统削弱；「取士不问门地」的官僚化进程因之加速。","figures":["武曌","李旦","薛怀义","王庆之","狄仁杰"],"place":"洛阳（今河南洛阳）","state":"武周","sources":["《旧唐书·则天皇后纪》","《新唐书·则天顺圣皇后纪》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["武周革命","女皇帝","洛阳"]},"related":[]},
  {"id":"cn--690--c01","track":"cn","year":690,"yearApprox":false,"dim":"culture","weight":2,"title":"《大云经神皇授记义疏》颁行","summary":"僧徒以弥勒下生附会后位，诏诸州各置大云寺。","detail":{"background":"《大云经》旧有净光天女以女身得为王、主阎浮提之文，北朝以来屡被指为邪说；则天称制，须经文为证。","process":"690年（天授元年）东魏国寺沙门法明与薛怀义等十人撰《大云经神皇授记义疏》四卷，以则天为弥勒下生、作阎浮提主，诏两京及天下诸州各置大云寺一所，以其疏宣讲于民，法明等皆受封邑。","impact":"国家权力与佛教转轮王话语的结合达于顶点，弥勒信仰与官寺制度因是遍于州县；玄宗以后以僧尼隶有司、严禁符命妖言，正是对此的反动。","figures":["法明","薛怀义","武曌"],"place":"长安、洛阳及天下诸州","state":"武周","sources":["《大云经神皇授记义疏》敦煌残卷","《资治通鉴》","《旧唐书·薛登传》"],"tags":["佛教政治","弥勒信仰","符命"]},"related":[]},
  {"id":"cn--698--p01","track":"cn","year":698,"yearApprox":false,"dim":"politics","weight":3,"title":"复立庐陵王为皇太子","summary":"狄仁杰以姑侄、母子为说，中宗自房州还东都。","detail":{"background":"则天欲以武承嗣或三思为嗣，「神道不歆非类」之论起于廷臣，691年王庆之八百人请立武氏，狄仁杰自692年起反复以宗庙为言。","process":"698年（圣历元年）三月，仁杰进言「立子则千秋万岁后配食太庙，立侄未闻侄为天子而祔姑于庙」，则天感悟，托言庐陵王有疾，遣使迎还东都，闰十月复立为皇太子；武承嗣求为皇太子之议遂止，寻发病死。","impact":"武周向唐的回归以不流血的方式完成安排，神龙政变与唐隆之变所据宗统皆出于此，也见出则天晚年的政治理性。","figures":["武曌","狄仁杰","李显","武承嗣"],"place":"洛阳（今河南洛阳）","state":"武周","sources":["《旧唐书·狄仁杰传》","《新唐书·狄仁杰传》","《资治通鉴》"],"tags":["储位","狄仁杰","武周末政"]},"related":[]},
  {"id":"cn--702--i01","track":"cn","year":702,"yearApprox":false,"dim":"institution","weight":3,"title":"分安西置北庭都护府","summary":"以天山北路诸蕃立北庭于庭州，与安西分统。","detail":{"background":"640年唐置安西都护府于交河，658年徙龟兹，统于阗、疏勒、焉耆、碎叶四镇；突骑施渐盛、吐蕃屡入西域，安西一道难以为守。","process":"702年（长安二年）十二月，分安西都护府置北庭都护府于庭州（今新疆吉木萨尔北破城子），统西突厥十姓与天山北路诸蕃，安西则掌于阗、疏勒以西；两镇镇兵数万，军、守捉、烽戍相望于道。","impact":"唐在西域建立南北两道并立的军政建制，安西、北庭与伊西庭节度成为丝路中段与葱岭交通的骨架；八世纪末吐蕃取北庭，此制遂废。","figures":["武曌","唐休璟","郭元振"],"place":"庭州（今新疆吉木萨尔北）","state":"唐","sources":["《唐会要·安西都护府》","《新唐书·地理志》","《元和郡县图志》","《资治通鉴》"],"tags":["都护府","西域建制","安西四镇"]},"related":[]},
  {"id":"cn--702--f01","track":"cn","year":702,"yearApprox":true,"dim":"figure","weight":2,"title":"陈子昂卒于射洪","summary":"为县令段简所陷，系狱，忧愤而卒，时年四十余。","detail":{"background":"子昂梓州射洪人，家世富豪，独苦节读书。初为《感遇诗》三十首，京兆司功王适见而惊曰「此子必为天下文宗矣」，由是知名。举进士，则天召见，拜麟台正字，再转右拾遗。","process":"武攸宜统军北讨契丹，以子昂为管记，军中文翰皆委之。子昂父在乡为县令段简所辱，子昂闻之遽还乡里，简乃因事收系狱中，忧愤而卒，时年四十余。本传不书卒之年岁，702 从今之通说依「年四十余」上推，故系年约之。","impact":"子昂有集十卷，友人卢藏用为序，盛行于代。唐之诗格自齐、梁绮靡一变而追汉、魏，子昂称首；蜀中之文自是始与中原抗，其后李、苏之伦皆承其目。","figures":["陈子昂","卢藏用","段简"],"place":"射洪（今四川遂宁射洪市）","state":"唐","sources":["《旧唐书·文苑中》"],"tags":["陈子昂","射洪","感遇诗","右拾遗"]},"related":[],"checks":[{"by":"本站·维基文库比对（《旧唐书》卷一百九十中·文苑中）","at":"2026-11-07","note":"原文「梓州射洪人」「初为《感遇诗》三十首」「简乃因事收系狱中，忧愤而卒，时年四十余」；本传无卒年，故 yearApprox 为真，未敢托称确年；系 702 之推据（本传「年四十余」与其人生年之通说）不在本传之内，sources 亦只列旧唐书，读者当以约年视之，不得据本条当作可核之确年"}]},
  {"id":"cn--705--p01","track":"cn","year":705,"yearApprox":false,"dim":"politics","weight":3,"title":"神龙政变，唐复国号","summary":"张柬之等起兵诛张易之兄弟，则天内禅于太子。","detail":{"background":"则天晚年多居禁中，张易之、昌宗出入侍侧，朝士忧惧不知所出；崔玄暐荐张柬之于则天，柬之既相，引桓彦范、敬晖居左右羽林将军。","process":"705年（神龙元年）正月，柬之、玄暐与桓彦范、敬晖、袁恕己率羽林将军李多祚等五百余人夜叩玄武门，迎太子于东宫，斩易之、昌宗于集仙殿，迫则天传位；中宗复位，复国号唐，迁则天于上阳宫，十一月崩，遗制去帝号、称则天大圣皇后。","impact":"武周政体以一役宫廷兵变告终，但五功臣旋为武三思与韦后所逐，政变未及重建稳定中枢，此后韦后、太平公主相继干政，直至713年乃定。","figures":["张柬之","崔玄暐","桓彦范","李显","武曌","张易之"],"place":"洛阳宫（今河南洛阳）","state":"唐／武周","sources":["《旧唐书·中宗纪》","《新唐书·张柬之传》","《资治通鉴》"],"tags":["神龙政变","复唐","禁军"]},"related":[]},
  {"id":"cn--710--p01","track":"cn","year":710,"yearApprox":false,"dim":"politics","weight":3,"title":"唐隆之变，诛韦氏","summary":"李隆基率万骑入两门，韦后、安乐公主皆死。","detail":{"background":"710年六月中宗暴崩，史载韦后与安乐公主进蒸饼，世疑其毒；立温王重茂为帝而后临朝总万机，诸韦居门下、典禁兵，宗室侧目。","process":"710年（唐隆元年）六月庚子，临淄王隆基与太平公主定策，率万骑果毅葛福顺、陈玄礼等斩韦播、高嵩以并其众，昧旦攻玄德、白兽诸门入宫；韦后奔玄武门旗下被斩，安乐公主方临镜自妆亦死，上官婉儿帅宫人执烛出迎，刘幽求谓「不斩婉儿，三军之心不至」，遂斩之。","impact":"一次成功的禁军政变，但权力实归于太平公主与李隆基两人，矛盾两年内即决；唐代「以玄武门定储位」的路径至此已成本朝惯例。","figures":["李隆基","太平公主","韦后","上官婉儿","李重茂"],"place":"长安宫城（今陕西西安）","state":"唐","sources":["《旧唐书·睿宗纪》","《资治通鉴》","《新唐书·后妃传》"],"tags":["唐隆之变","韦后","禁军"]},"related":[]},
  {"id":"cn--712--p01","track":"cn","year":712,"yearApprox":false,"dim":"politics","weight":4,"title":"睿宗传位，玄宗即位","summary":"传德避灾，八月即位于太极殿，太上皇仍决大政。","detail":{"background":"唐隆既定，太平公主恃功与太子隆基相图，宫人近臣半为其耳目；712年术者言帝座有灾、太子当盛，睿宗以为传德可以避灾。","process":"712年（景云三年、延和元年）七月睿宗下诏传位，八月太子隆基即位于太极殿，是为玄宗，尊睿宗为太上皇，三品以上除授与大刑政犹决于太上皇，改元先天。","impact":"新君得位而权未全，713年七月太平公主、窦怀贞之谋即起；玄宗先发诛之，太上皇尽归政，开元之治得以启动的权力条件由此具备。","figures":["李隆基","李旦","太平公主","郭元振","姚崇"],"place":"长安太极殿（今陕西西安）","state":"唐","sources":["《旧唐书·玄宗纪》","《资治通鉴》","《唐会要》"],"tags":["玄宗即位","太上皇","先天"]},"related":[]},
  {"id":"cn--713--p01","track":"cn","year":713,"yearApprox":false,"dim":"politics","weight":4,"title":"先天政变，诛太平公主","summary":"玄宗先发执萧至忠等，公主赐死，太上皇尽归政。","detail":{"background":"睿宗虽传位，犹自决三品以上除授与大刑政；太平公主以定策之功广植党羽，宰相多出其门，与窦怀贞、萧至忠、岑羲结党，谋以羽林兵废立。","process":"713年（先天二年）七月三日，玄宗与郭元振、王毛仲、高力士定议，先执萧至忠、岑羲、李晋于殿庭，窦怀贞投沟死，以羽林兵诛其党数十人；太平公主走山第，赐死于家，籍其家财拟于宫禁。睿宗徙居百福殿，军国之务一归皇帝，改元开元。","impact":"自684年以来延续三十年的后妃、公主与外戚干政期至此结束；玄宗得全权，姚崇、宋璟的开元之治才有推行的政治条件。","figures":["李隆基","太平公主","郭元振","萧至忠","李旦"],"place":"长安太极宫（今陕西西安）","state":"唐","sources":["《旧唐书·玄宗纪》","《新唐书·公主传》","《资治通鉴》"],"tags":["先天政变","禁军","开元"]},"related":[]},
  {"id":"cn--713--a01","track":"cn","year":713,"yearApprox":false,"dim":"art","weight":3,"title":"始凿嘉州凌云大佛","summary":"海通禅师以三江汇险，伐山开龛造弥勒坐像。","detail":{"background":"嘉州凌云山当岷江、大渡河、青衣江汇流，湍急覆舟；僧海通以山河以佛而宁为说，募财凿像以镇水。","process":"713年（开元元年）海通于凌云山凿崖起龛，先造像、次修阁，自顶至足九十余尺，传闻膝宽可坐数十人；海通卒后章仇兼琼、韦皋相继续资，至贞元年间完龛成阁，即今乐山大佛。","impact":"这是中国现存最大的摩崖石刻坐佛，也见出盛唐以后佛教工程由朝廷施舍转向地方官与信众募财的资助方式。","figures":["海通","章仇兼琼","韦皋"],"place":"嘉州凌云山（今四川乐山）","state":"唐","sources":["《乐山县志》","《嘉州凌云寺大弥勒石像记》","韦皋贞元年间碑记"],"tags":["石窟造像","摩崖","佛教艺术"]},"related":[]},
  {"id":"cn--713--c01","track":"cn","year":713,"yearApprox":false,"dim":"culture","weight":3,"title":"慧能卒，《坛经》行世","summary":"曹溪慧能端坐而逝，门人法海集其言为坛经。","detail":{"background":"慧能本岭南樵人，因读《金刚经》有省，往黄梅从弘忍得衣钵，南隐猎人队中十五年；后至广州法性寺，以风动幡动之议为印宗法师所剃落，住韶州曹溪宝林寺说法三十余年。","process":"713年（先天二年）八月三日，慧能于新州国恩寺端坐迁化，临终嘱门人说法不动、举摩诃般若之法；门人法海集其平生语为一卷，世称《六祖坛经》，其肉身归曹溪，塔今存。","impact":"《坛经》是唯一由中国人所说而被尊为经的佛典，把成佛从渐修与读经转向当下心性，为后世禅宗五家与宋明理学的问题意识定调。","figures":["慧能","法海","弘忍","印宗"],"place":"新州国恩寺、曹溪宝林寺（今广东新兴、韶关）","state":"唐","sources":["《六祖大师法宝坛经》","《宋高僧传·慧能传》","印顺《中国禅宗史》"],"tags":["禅宗","坛经","佛教中国化"]},"related":[]},
  {"id":"cn--713--p02","track":"cn","year":713,"yearApprox":false,"dim":"politics","weight":3,"title":"大祚荣受册，号渤海郡王","summary":"先天二年遣郎将崔訢往册，仍以其所统为忽汗州。","detail":{"background":"大祚荣本高丽别种，与乞四比羽各领亡命东奔，保阻以自固，遂率其众东保桂娄之故地，据东牟山，筑城以居之；圣历中自立为振国王，遣使通于突厥。其地在营州之东二千里，地方二千里，编户十余万，胜兵数万人。","process":"睿宗先天二年（713），遣郎将崔訢往册拜祚荣为左骁卫员外大将军、渤海郡王，仍以其所统为忽汗州，加授忽汗州都督；自是每岁遣使朝贡。","impact":"东北一隅自此入于册命，渤海与唐、新罗相往来，其后为契丹所并；本传所记一国之户口兵数，亦以此册为之始，故其兴虽忽，而载于史遂自是始。","figures":["大祚荣","崔訢"],"place":"忽汗州（今黑龙江宁安一带）","state":"唐","sources":["《旧唐书·北狄传》"],"tags":["渤海","渤海靺鞨","忽汗州","先天二年"]},"related":[],"checks":[{"by":"本站·维基文库比对（《旧唐书》卷一百九十九下·北狄传）","at":"2026-11-07","note":"本传「睿宗先天二年，遣郎将崔訢往册拜祚荣为左骁卫员外大将军、渤海郡王，仍以其所统为忽汗州，加授忽汗州都督」，人名从本作崔訢；又本传自记源流「渤海靺鞨大祚荣者，本高丽别种也」「东保桂娄之故地，据东牟山，筑城以居之」「圣历中，自立为振国王」「编户十余万，胜兵数万人」，本条背景皆取此。旧稿作崔欣、粟末靺鞨、震国王、众户数万，或据他书之文或系笔误，与所引本传不合，今正"}]},
  {"id":"cn--716--p01","track":"cn","year":716,"yearApprox":false,"dim":"politics","weight":3,"title":"姚崇拜相，奏十事要说","summary":"以不倖边功、不滥赏、禁苛扰十条当国，号开元名相。","detail":{"background":"先天政变后玄宗择相；姚崇自荆州被召，见帝时以十事试探，谓非陛下不能行，而臣亦愿以十条为约。","process":"716年（开元四年）十二月姚崇同中书门下三品，旋拜紫微令。其十事要说大旨为：行仁恕不求边功、中官不得预政、母后与外戚不居权要、租庸之外无横敛、不妄营寺观、许群臣触龙鳞、以汉晋外戚之祸为鉴；又以蝗不可祷，遣御史分道督捕，与卢怀慎并相而独当决。","impact":"十条实为开元初政的施政纲领；崇为相务责成有司、不亲细务，使中枢行政复归效率，宋璟继其轨，遂有开元之治与姚宋并称。","figures":["姚崇","李隆基","宋璟","卢怀慎"],"place":"东都洛阳（今河南洛阳）","state":"唐","sources":["《旧唐书·姚崇传》","《资治通鉴》","《开元升平源》"],"tags":["姚崇","宰相政治","开元初政"]},"related":[]},
  {"id":"cn--721--e01","track":"cn","year":721,"yearApprox":false,"dim":"economy","weight":3,"title":"宇文融括检天下逃户","summary":"置劝农使按行州县，客户附籍、括得田数万顷。","detail":{"background":"开元以来逃亡既多、籍账不辨，客户为人佃役而赋税不入于官，户口之数与国用不相称。","process":"721年（开元九年）监察御史宇文融请简察郡县逃户，置劝农使十九人分道按行，听客户于所在附籍、复其一年之租庸，隐没之田没官；前后得户八十余万，史又称数十万，得钱数百数百万贯以充边费。","impact":"括户在均田已坏之后为中央财政另辟税源，并在制度上承认客户与租佃的存在；括户、和籴与漕运改革共同支撑了开元后期的支出扩张。","figures":["宇文融","李隆基","张说"],"place":"长安（使分道行于河南、河北、江淮）","state":"唐","sources":["《旧唐书·宇文融传》","《资治通鉴》","《通典·食货典》","《剑桥中国隋唐史》"],"tags":["括户","逃客户","财政"]},"related":[]},
  {"id":"cn--724--s01","track":"cn","year":724,"yearApprox":false,"dim":"science","weight":4,"title":"僧一行主持天下测影，定《大衍历》","summary":"立表测北极高下与日影差，推子午线一度之长。","detail":{"background":"麟德历行用年久、朔蚀多失；一行以为历数须本于实测，请令天下就平原立表测影，以定历本。","process":"724年（开元十二年）玄宗诏一行于河南滑州、汴州、蔡州等地立表测影，又北至铁勒、南至林邑，以表影长短与北极出地高度之差推算子午线一度之里数，其记录见于《旧唐书·历志》；另造黄道游仪与浑图，727年《大衍历》成。","impact":"这是世界天文史上最早由人力组织的大地子午线实测（李约瑟说）；《大衍历》行用一个多世纪并传入日本、朝鲜，是唐代最精密的一部历法。","figures":["一行","梁令瓒","李隆基"],"place":"河南府至长安（今河南洛阳、陕西西安）","state":"唐","sources":["《旧唐书·历志》","《新唐书·天文志》","《大衍历议》","李约瑟《中国科学技术史》"],"tags":["天文观测","历法","子午线测量"]},"related":[]},
  {"id":"cn--732--c01","track":"cn","year":732,"yearApprox":false,"dim":"culture","weight":3,"title":"滑台之会，神会诘北宗","summary":"洛阳滑台大云寺设无遮大会，争禅门六代正统。","detail":{"background":"神秀一系在北宗盛于两京，普寂以「七代师资」自居；慧能一系偏居岭南，「南北两宗、顿渐未定」。","process":"732年（开元二十年）正月，慧能弟子洛阳滑台大云寺设无遮大会，公开难问北宗所立师承，谓达摩至慧能六代相传为正、北宗「师承是傍、法门是渐」；立曹溪为禅门正统，「天下知南宗之名」。","impact":"南宗由地方法系取得正统论述，此后七、八十年间渐成禅门主流；796年唐德宗敕立神会为禅宗第七祖，禅宗史由南宗一手书写。","figures":["神会","普寂","慧能"],"place":"滑台大云寺（今河南滑县）","state":"唐","sources":["《宋高僧传·神会传》","圭峰宗密《圆觉经略疏钞》","《菩提达摩南宗定是非论》"],"tags":["禅宗南北宗","顿渐之争","宗教正统"]},"related":[]},
  {"id":"cn--733--m01","track":"cn","year":733,"yearApprox":false,"dim":"military","weight":4,"title":"缘边定置十节度使","summary":"十镇专征伐，边兵四十九万，内轻外重之势成。","detail":{"background":"吐蕃、突厥、契丹、奚迭为边患，旧都护府与诸军镇分散不相统，边事须有专任之将，节度之名自七世纪初年渐成定制。","process":"733年（开元二十一年）定于缘边置平卢、范阳、河东、朔方、河西、陇右、剑南、岭南及安西、北庭十节度经略使，各专征伐；《通典》载其时边镇之兵四十九万、马八万匹，皆仰给于官。","impact":"边兵集中于少数胡汉将领之手，中央彍骑不满十二万，外重内轻的军事格局由此形成；安禄山一身兼三节度、拥兵十八万，即此制的必然结果。","figures":["李隆基","张守珪","安禄山"],"place":"缘边十镇（今河北至新疆）","state":"唐","sources":["《通典·边防典》","《唐会要·节度使》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["节度使","边镇","内轻外重"]},"related":[]},
  {"id":"cn--736--p01","track":"cn","year":736,"yearApprox":false,"dim":"politics","weight":3,"title":"张九龄罢知政事，林甫专权之始","summary":"诤相去位，口蜜腹剑者独承主意，言路自此壅塞。","detail":{"background":"张九龄以文学进用，开元二十一年拜中书令，居相位以谏诤自任，与李林甫并相后每争论于帝前，林甫阳顺而阴构之。","process":"736年（开元二十四年）十一月，玄宗欲加牛仙客实封、九龄执以为不可，林甫退谓「天子用人何必问外议」；未几九龄坐监察御史周子谅上书事被构，罢知政事，出为荆州大都督府长史。737年太子瑛等并废死，9龄寻卒于韶州。","impact":"开元朝最后一位诤相去位，谏净之门既塞，边功与壅蔽俱起；安史之乱前夜的中枢已丧失自我纠正能力，故后世论唐之治乱者常以九龄进退为界。","figures":["张九龄","李林甫","李隆基","周子谅"],"place":"长安；荆州（今陕西西安、湖北荆州）","state":"唐","sources":["《旧唐书·张九龄传》","《资治通鉴》","《新唐书·奸臣传》"],"tags":["张九龄","李林甫","言路"]},"related":[]},
  {"id":"cn--737--m01","track":"cn","year":737,"yearApprox":false,"dim":"military","weight":3,"title":"募彍骑，府兵番上之制废","summary":"折冲无兵可检，召客户丁匠十二万分隶六军。","detail":{"background":"开元以来逃户日多，卫士贫不能办装，折冲府番上宿卫常不足人数，府兵之名仅存于簿书。","process":"737年（开元二十五年）十月，召募天下客户及丁匠充六军长征宿卫之兵，得十二万人，号曰彍骑，分隶左右羽林、左右龙武、左右神武六军，由将军统其教阅；折冲府官自此不领府兵。","impact":"中央禁军由番上府兵转为召募的常备兵，兵农合一的基础瓦解，国家须以赋税养兵；此后禁军与边镇的兵权皆归于将帅，唐廷遂以宦官监军为补救。","figures":["李隆基"],"place":"长安六军（今陕西西安）","state":"唐","sources":["《旧唐书·兵志》","《唐六典》","《资治通鉴》"],"tags":["彍骑","募兵制","府兵崩坏"]},"related":[]},
  {"id":"cn--738--i01","track":"cn","year":738,"yearApprox":false,"dim":"institution","weight":3,"title":"《唐六典》撰成奏上","summary":"以三省六部为纲，纪百司员额职掌与令格式。","detail":{"background":"玄宗仿周礼六官之意，开元十年命张说、萧嵩、韦述等相继撰述，历二十八年乃成。","process":"738年（开元二十六年）《唐六典》三十卷奏上，以三师三公、三省、六部、九寺五监、十二卫及州县官司为次，叙其官署、员额、品秩与职掌，并载令、格、式与故事。","impact":"这是中国现存最早的一部系统性行政法典汇编，后世《唐会要》与宋、明、清诸会典皆沿其以官统事的体例，是研究唐代官制的第一手依据。","figures":["李隆基","张说","韦述"],"place":"长安（今陕西西安）","state":"唐","sources":["《唐六典》","《旧唐书·张说传》","《直斋书录解题》"],"tags":["行政法典","官制","唐六典"]},"related":[]},
  {"id":"cn--738--p01","track":"cn","year":738,"yearApprox":false,"dim":"politics","weight":3,"title":"皮逻阁并六诏，册云南王","summary":"开元二十六年九月，册蒙归义为云南王，遂徙居大和城。","detail":{"background":"蛮语谓王曰诏，先有六诏，兵力相埒，莫能相壹，历代因之以分其势。蒙舍最在南，故谓之南诏；高宗时蒙舍细奴逻初入朝，传逻盛、盛逻皮至皮逻阁，浸强大而五诏微弱。","process":"皮逻阁渐强，会破渳河蛮之功，赂剑南节度使王昱，求合六诏为一；昱为之奏请，朝廷许之，赐名归义。于是以兵威胁服群蛮，不从者灭之，遂击破吐蕃，徙居大和城。开元二十六年（738）九月戊午，册南诏蒙归义为云南王。其后昱复筑两城于安戎城侧以逼吐蕃，为其所败，死者数千人，贬括州刺史、再贬高要尉而死。","impact":"六诏并而南诏一，剑南之自吐蕃一易为南诏；其后阁罗凤反、成都之扰与云南之殁皆起于此。一诏之并，非唐之本谋，成于赂边臣之手，唐之西南自此多事。","figures":["皮逻阁","蒙归义","王昱"],"place":"大和城（今云南大理）","state":"唐","sources":["《资治通鉴·唐纪三十》","《新唐书·南蛮上》"],"tags":["南诏","六诏","大和城","开元二十六年"]},"related":[],"checks":[{"by":"本站·维基文库比对（《资治通鉴》卷二百一十四）","at":"2026-11-07","note":"原文纪年标记「开元二十六年」并注「西元七三八年」，「戊午，册南诏蒙归义为云南王」，又追叙「会有破渳河蛮之功，乃赂王昱，求合六诏为一……仍赐名归义……徙居大和城」；六诏世系作「细奴逻生逻盛，逻盛生盛逻皮，盛逻皮生皮逻阁」，本条不书「四传」而直列其传"},{"by":"本站·维基文库比对（《新唐书·南蛮上》）","at":"2026-11-07","note":"卷二百二十二上「◎南蛮 上」，「蒙舍诏在诸部南，故称南诏」「乃厚以利啖剑南节度使王昱，求合六诏为一。制可」「于是徙治大和城」；本书次叙为「皮逻阁逐河蛮，取大和城……乃厚以利啖剑南节度使王昱，求合六诏为一。制可。归义已并群蛮，遂破吐蕃……又以破渳蛮功，驰遣中人册为云南王……于是徙治大和城」，赂昱在破吐蕃之前、受册在徙治之先，与《通鉴》追叙合观方有先后；process 旧以王昱安戎城之败贬死列于赂昱之前，系把《通鉴》「初」字追叙误读作编年之序，今正；sources 旧记「南蛮中」系卷次误标，今按页面「南蛮 上」改正"}]},
  {"id":"cn--751--m01","track":"cn","year":751,"yearApprox":false,"dim":"military","weight":3,"title":"怛罗斯之败：唐与大食相遇","summary":"高仙芝围怛罗斯五日，葛逻禄倒戈，安西由是遂弱。","detail":{"background":"唐以安西、北庭控葱岭两道，750年高仙芝以石国（今塔什干）无礼，取其城而虏其王；黑衣大食势力东向，两者在中亚相遇。","process":"751年（天宝十载）七月，高仙芝率步骑二万西出葱岭，围怛罗斯城（今哈萨克斯坦江布尔），与大食援军接战五日；葛逻禄部忽自后击唐军，唐兵大溃，仙芝与数千骑逃归，安西由是遂弱，不能远出。","impact":"这是唐与阿拉伯之间唯一一次正面大战，中亚自此渐入伊斯兰文化圈；后世或谓被俘唐匠将造纸术传至撒马尔罕，但学界多以为纸张早已西传，其说存疑。","figures":["高仙芝","封常清","李嗣业"],"place":"怛罗斯（今哈萨克斯坦江布尔）","state":"唐","sources":["《旧唐书·高仙芝传》","《新唐书·葛逻禄传》","《资治通鉴》"],"tags":["怛罗斯之战","中亚","唐与大食"]},"related":["world--751--m01"]},
  {"id":"cn--754--e01","track":"cn","year":754,"yearApprox":false,"dim":"economy","weight":2,"title":"天宝十三载户口计帐","summary":"户九百六万九千余，口五千二百八十八万，此为唐盛极之数。","detail":{"background":"开元、天宝之际均田渐坏而籍帐不清，客户、逃户与僧道多不入簿；政府所计者乃纳税之户，非实际人口。","process":"754年（天宝十三载）全国计户九百六万九千一百五十四，口五千二百八十八万八千四百八十八，见于《通典·食货典》与《旧唐书·地理志》。","impact":"此数历来被举为唐代极盛之证；今人考之，天宝实际人口或当在六千万以上，安史乱后籍户顿减至二百余万，未必是真实死亡，多为版籍散失。","figures":["李隆基","杨国忠"],"place":"长安（今陕西西安）","state":"唐","sources":["《通典·食货典》","《旧唐书·地理志》","《新唐书·地理志》","葛剑雄主编《中国人口史》"],"tags":["户口统计","唐代经济","籍帐"]},"related":[]},
  {"id":"cn--755--m01","track":"cn","year":755,"yearApprox":false,"dim":"military","weight":5,"title":"安禄山范阳起兵","summary":"十八万兵南下，两月陷东京，河北诸郡望风而降。","detail":{"background":"安禄山以胡人为互市牙郎，恃边功历平卢、范阳、河东三节度，拥兵十八万，天下精骑半在其手；杨国忠数言其必反，玄宗不省。","process":"755年（天宝十四载）十一月，安禄山与史思明等举兵于范阳，以奉密诏讨杨国忠为名，率所部及同罗、奚、契丹、室韦之众南下，十二月陷陈留、荥阳，入东京，河北诸郡望风降。","impact":"承平百三十余年的中原第一次被边兵占领；唐廷此后以藩镇处乱军、以宦官典禁军、以回纥借兵，其制度性后果延续一百五十年至唐亡。","figures":["安禄山","史思明","杨国忠","封常清","李隆基"],"place":"范阳、洛阳（今河北涿州、河南洛阳）","state":"唐","sources":["《资治通鉴》","《旧唐书·安禄山传》","《新唐书·叛臣传》","《剑桥中国隋唐史》"],"tags":["安史之乱","藩镇","范阳"]},"related":[]},
  {"id":"cn--756--p01","track":"cn","year":756,"yearApprox":false,"dim":"politics","weight":4,"title":"马嵬之变与肃宗灵武即位","summary":"六军不发，杨氏死；太子北赴灵武自行即位。","detail":{"background":"潼关一失，长安无险可守，6月玄宗西幸蜀中；随行的龙武军在马嵬驿哗变，乱兵请诛杨氏，太子李亨与父分道。","process":"756年六月十四日马嵬驿兵变，杀杨国忠，赐杨贵妃死；父老遮道请留太子讨贼，亨北走灵武，七月即位，尊玄宗为太上皇，改元至德。","impact":"皇帝废立在乱中由禁军与朔方军决定，开中晚唐宦官定策之渐；肃宗倚回纥兵与朔方、河东诸将，平乱遂成军事联盟之事。","figures":["李亨","李隆基","杨国忠","陈玄礼","郭子仪"],"place":"马嵬驿、灵武（今陕西兴平、宁夏灵武）","state":"唐","sources":["《资治通鉴》","《旧唐书·肃宗纪》","《新唐书·玄宗诸子传》"],"tags":["马嵬驿之变","灵武即位","至德"]},"related":[]},
  {"id":"cn--762--f01","track":"cn","year":762,"yearApprox":false,"dim":"figure","weight":2,"title":"李白卒于当涂","summary":"以歌行名世，依李阳冰于当涂，年六十二。","detail":{"background":"李白自永王璘案长流夜郎，中途遇赦得还，晚年依宣歙观察使李阳冰于当涂，穷困而终。","process":"762年前后（宝应元年）李白卒，年六十有二；其诗文由李阳冰辑为《草堂集序》所述，后世重编为《李太白文集》。","impact":"李、杜并称自此成为诗歌史的基本格局；李白一格兼取游仙、饮酒、乐府与七言歌行，中唐以后直至宋代刻本流传极广。","figures":["李白","李阳冰","郭子仪"],"place":"当涂（今安徽马鞍山）","state":"唐","sources":["《旧唐书·文苑传》","《新唐书·文艺传》","李阳冰《草堂集序》"],"tags":["李白","唐代文学","当涂"]},"related":[]},
  {"id":"cn--763--m01","track":"cn","year":763,"yearApprox":false,"dim":"military","weight":3,"title":"史朝义自缢，河朔授为节度","summary":"乱平而根未拔，李怀仙诸将就地得节钺。","detail":{"background":"史思明为其子朝义所弑，军势已离；唐以回纥兵收东京，仆固怀恩恐乱兵掠东都，请悉降而官之。","process":"763年（广德元年）正月，史朝义走范阳不得入，穷蹙自缢；唐即以其降将李怀仙、田承嗣、薛嵩分领幽州、魏博、昭义，河朔遂成割据之势。","impact":"安史之乱以除名藩镇的方式结束，唐廷用土地与官爵换取停战，此后河北三镇自署官吏、自擅兵赋，成为中晚唐百年问题的总根源。","figures":["史朝义","仆固怀恩","田承嗣","李怀仙","薛嵩"],"place":"范阳、魏博（今河北涿州、河北大名）","state":"唐","sources":["《资治通鉴》","《旧唐书·仆固怀恩传》","《新唐书·藩镇传》"],"tags":["河朔三镇","藩镇割据","安史之乱"]},"related":[]},
  {"id":"cn--763--m02","track":"cn","year":763,"yearApprox":false,"dim":"military","weight":4,"title":"吐蕃入长安，十五日而退","summary":"高陵一战京师失守，郭子仪以疑兵复之。","detail":{"background":"唐以朔方、河西、陇右之兵东平安史，河西、陇右空虚，吐蕃尽陷河西、陇右之地，长驱直至渭北。","process":"763年十月，吐蕃入长安，立广武王承宏为帝，改元；代宗出陕，郭子仪以少数兵张疑兵、昼夜击鼓，吐蕃疑诸军大集，十五日而西去。","impact":"唐都对外族第一次被攻破，京师宫室焚掠几尽；自此唐以凤翔、邠宁、灵武为边镇，回纥岁赐与绢马贸易的负担与吐蕃和战交替压向财政。","figures":["郭子仪","代宗李豫","赤岭","仆固怀恩"],"place":"长安（今陕西西安）","state":"唐","sources":["《资治通鉴》","《旧唐书·吐蕃传》","《新唐书·吐蕃传》"],"tags":["吐蕃","长安之陷","唐蕃关系"]},"related":[]},
  {"id":"cn--764--e01","track":"cn","year":764,"yearApprox":false,"dim":"economy","weight":3,"title":"刘晏掌转运盐铁","summary":"因隋氏旧渠岁漕百万斛，以盐利充漕费。","detail":{"background":"安史乱后汴水堙废，关中乏食，米斗千钱；第五琦始创榷盐法，刘晏接其后而大为之节目。","process":"764年（广德二年）刘晏以户部侍郎领东都、河南、江淮、山南等转运盐铁使，分段堰运，取江淮米岁百万斛以给关中，盐利岁缗钱六百万。","impact":"漕运与盐利自此成为唐廷的两大命脉，关中得食而东南财富东输；其以商税、榷利代赋役的思路，为后世财计制度开其端。","figures":["刘晏","第五琦","元载"],"place":"扬州、长安（今江苏扬州、陕西西安）","state":"唐","sources":["《旧唐书·刘晏传》","《新唐书·食货志》","《资治通鉴》"],"tags":["漕运","榷盐","唐代财政"]},"related":[]},
  {"id":"cn--770--f01","track":"cn","year":770,"yearApprox":false,"dim":"figure","weight":3,"title":"杜甫卒于湘岳舟中","summary":"漂泊剑南荆楚，旅柩暂厝岳阳，诗称诗史。","detail":{"background":"杜甫自秦州入蜀，依严武于成都，严武卒后东下，滞留夔州两年，大历三年出峡，漂泊湖湘。","process":"770年（大历五年）杜甫病卒于岳州、潭州之间，年五十有九；其子杜嗣业旋葬之于偃师，墓志元稹为之。","impact":"杜诗由宋人注本定型为千年之学；其在夔、峡间所作律诗与组诗，被视为近体格律的最高典范，亦为中唐以后士人以诗存史的起点。","figures":["杜甫","严武","元稹","杜嗣业"],"place":"岳州、潭州（今湖南岳阳、长沙）","state":"唐","sources":["《旧唐书·文苑传》","《新唐书·杜甫传》","元稹《唐故工部员外郎杜君墓系铭》"],"tags":["杜甫","夔州诗","诗史"]},"related":[]},
  {"id":"cn--780--i01","track":"cn","year":780,"yearApprox":false,"dim":"institution","weight":5,"title":"杨炎建两税法，行于天下","summary":"量出制入，户无主客，以见居为簿，夏秋两征。","detail":{"background":"安史乱后版籍沦亡，租庸调无以按丁，天下赋税名目百出；杨炎以建中元年正月制变税法，总其目曰两税。","process":"780年（建中元年）行两税法：凡租庸杂徭悉省，以丁壮、贫富为等，户无主客以见居为簿，人无丁中以贫富为等，行商所在州县税三十之一，夏税不过六月、秋税不过十一月，以钱为定而折以实物。","impact":"自租庸调至两税法，是中国赋役史从以身为本向以资、以地为本的分界；其后一条鞭、地丁皆承此途。定税以钱、折纳以物，钱重物轻之弊遂起于元和。","figures":["杨炎","德宗李适","刘晏"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·杨炎传》","《新唐书·食货志》","《唐会要·租税》","《剑桥中国隋唐史》"],"tags":["两税法","赋役制度","建中"]},"related":[]},
  {"id":"cn--782--e01","track":"cn","year":782,"yearApprox":false,"dim":"economy","weight":3,"title":"卢杞荐赵赞，税屋架除陌","summary":"间架税、除陌钱起，市人罢市，京师大怨。","detail":{"background":"讨两河用兵，度支不给；卢杞以聚敛之臣自效，除赵赞为判度支，别税间架、除陌，又有木炭之需。","process":"782年（建中三年）赵赞请税天下间架，屋两架为间，上者税二千；又除陌钱，交易一千取五十；市肆罢譁，长安如堵，德宗旋以是年之令归罪于赵赞而止。","impact":"临时杂税与两税并行之弊自此不可止，唐廷在军费与民怨之间反复折衷；一年后果然爆发泾原之变，德宗出奔。","figures":["卢杞","赵赞","德宗李适"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·食货志》","《新唐书·奸臣传》","《资治通鉴》"],"tags":["间架税","除陌钱","唐代财政"]},"related":[]},
  {"id":"cn--783--m01","track":"cn","year":783,"yearApprox":false,"dim":"military","weight":4,"title":"泾原兵变，德宗出奔奉天","summary":"犒军不及，乱兵犯阙；朱泚称号，踰年乃平。","detail":{"background":"泾原之师东讨蓟、蔡，过长安求犒，所给唯粝食菜羹，士卒怒而反，德宗仓促幸奉天。","process":"783年（建中四年）十月乱兵入宫，朱泚据长安称帝，国号秦；李怀光继叛，德宗自奉天再奔梁州，浑瑊、李晟等苦战经年，784年六月李晟复京师，朱泚为其下所杀。","impact":"唐廷中央财政自此愈不能自主，陆贽代作诏书罪己以结人心；此后德宗不事事而倚禁军于宦官，神策军遂成中晚唐内重外轻的支柱。","figures":["德宗李适","朱泚","李晟","陆贽","浑瑊"],"place":"长安、奉天（今陕西西安、乾县）","state":"唐","sources":["《资治通鉴》","《旧唐书·德宗纪》","《新唐书·朱泚传》"],"tags":["泾原兵变","奉天之难","神策军"]},"related":[]},
  {"id":"cn--785--f01","track":"cn","year":785,"yearApprox":false,"dim":"figure","weight":3,"title":"陆贽在翰林，日下数百言","summary":"奉天行在草诏，罪己动人心，罢琼林大盈二库。","detail":{"background":"德宗出奔，山东未平，朝廷号令出于仓卒；陆贽以谏议大夫随幸奉天，入翰林为学士，最被信重。","process":"785年前后（兴元元年）陆贽上论数十百条，请罢琼林、大盈二库以散聚敛，请两税之外不得别率；代宗制罪己诏，武夫重读为泣。","impact":"兴元大赦几以空文收藩镇之心，而陆贽之论成为中唐以后议论财政与君德的标准文本，苏轼编奏议以传；其两税定货轻钱重之论尤被后世称引。","figures":["陆贽","德宗李适","贽兄弟"],"place":"奉天、梁州（今陕西乾县、汉中）","state":"唐","sources":["《陆宣公奏议》","《旧唐书·陆贽传》","《资治通鉴》"],"tags":["陆贽","兴元诏","翰学士"]},"related":[]},
  {"id":"cn--787--p01","track":"cn","year":787,"yearApprox":false,"dim":"politics","weight":3,"title":"平凉会盟，吐蕃劫盟","summary":"浑瑊待于平凉川，伏发，唐使将吏尽执。","detail":{"background":"尚结赞请盟以纾两河之用兵，张延赏主和议，卢杞荐浑瑊为会盟使，李晟、马燧力争其不可。","process":"787年（贞元三年）闰五月，唐、蕃会于平凉川（今甘肃平凉），吐蕃伏甲劫盟，浑瑊得免，唐将吏陷者六十余人，盟书尽弃。","impact":"唐蕃自此再无盟好，北边自泾、原至灵武常以拒寇为主，安西、北庭与京师音问几绝；主和之张延赏与李晟之论成为宋以后边议的两端。","figures":["尚结赞","浑瑊","李晟","张延赏"],"place":"平凉川（今甘肃平凉）","state":"唐","sources":["《旧唐书·吐蕃传》","《资治通鉴》","《新唐书·浑瑊传》"],"tags":["平凉劫盟","唐蕃会盟","边界"]},"related":[]},
  {"id":"cn--790--x01","track":"cn","year":790,"yearApprox":true,"dim":"explore","weight":3,"title":"贾耽记广州通海夷道","summary":"自广州放洋，历海峡、天竺至拔达，凡三万余里。","detail":{"background":"贾耽贞元中入相，好地理之学，尝使四方，遇使者与商贾即问其山川道里，撰《海内华夷图》并古墨今朱之例。","process":"贞元中（约七九〇年前后）贾耽所绘图说，其叙广州通海夷道一条赖《新唐书·地理志》得存：自广州东南海行，过马六甲、兰里、天竺，至波斯湾与拔达（巴格达），凡三万余里，所历二十余国。","impact":"此为现存最早、最确的一条由中国至西亚之海道记录，唐之海上丝路自此有里程可据；其以夷语记国名、以航日计里之例，为宋《诸蕃志》、元《岛夷志略》所本。","figures":["贾耽","李勉"],"place":"广州、长安（今广东广州、陕西西安）","state":"唐","sources":["《新唐书·地理志》","《旧唐书·贾耽传》","《新唐书·艺文志》"],"tags":["广州通海夷道","海上丝路","贾耽"]},"related":[]},
  {"id":"cn--794--m01","track":"cn","year":794,"yearApprox":false,"dim":"military","weight":3,"title":"韦皋取维州，吐蕃势绌","summary":"围维州而拔之，南诏内附，吐蕃西山失险。","detail":{"background":"韦皋镇西川二十一年，务以离心之术破吐蕃：结南诏、取维州、抚西山诸羌，吐蕃赞普自至德以来之盛渐衰。","process":"794年（贞元十年）韦皋遣将乘吐蕃内乱取维州（今四川理县），其冬吐蕃以大军来争，西山诸城垒相继入唐；同年南诏异牟寻与唐复盟于点苍山。","impact":"吐蕃西南一道被截断，唐得以安西、北庭与蜀中声气复通；维州一隅此后成为牛李党争中守与弃的标本，文宗时以之还蕃，边议遂为之一变。","figures":["韦皋","异牟寻","尚结赞"],"place":"维州、成都（今四川理县、成都）","state":"唐","sources":["《旧唐书·韦皋传》","《新唐书·南诏传》","《资治通鉴》"],"tags":["韦皋","维州","南诏"]},"related":[]},
  {"id":"cn--796--i01","track":"cn","year":796,"yearApprox":false,"dim":"institution","weight":4,"title":"神策两中尉，宦官典禁军","summary":"以窦文场、霍仙鸣为两护军中尉，禁军遂归内臣。","detail":{"background":"德宗自奉天、梁州之难，不复核帅，还京后以禁兵属所厚宦官；贞元十二年遂定两中尉之职。","process":"796年（贞元十二年）以窦文场、霍仙鸣为左右神策军护军中尉，神策军益扩至左右两厢、八镇，中尉自领其籍、自命其将，不复关由台司。","impact":"神策军成为唐廷唯一可用的中央武力，而其统属在内廷，此后顺宗、宪宗、穆宗、文宗之立与废，皆由两中尉定策，北司之权自此不可解。","figures":["窦文场","霍仙鸣","德宗李适"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·窦文场传》","《新唐书·百官志》","《资治通鉴》","《剑桥中国隋唐史》"],"tags":["神策军","宦官","禁军制度"]},"related":[]},
  {"id":"cn--801--c01","track":"cn","year":801,"yearApprox":false,"dim":"culture","weight":3,"title":"杜佑成《通典》二百卷","summary":"自黄帝至天宝，专以九门纪历代建置。","detail":{"background":"刘秩作《政典》未备，杜佑因其类而广之，历仕淮南、剑南，在公馀缀辑，三十年而成书。","process":"801年（贞元十七年）杜佑表进《通典》，凡九门：食货、选举、职官、礼、乐、兵、刑、州郡、边防，二百卷，论议附于本文之后。","impact":"此为中国史第一部以制度分门的通史，与后世《通志》《文献通考》合称三通；其食货居首、以兵农财计相贯的编排，成为制度史的定式。","figures":["杜佑","刘秩"],"place":"长安（今陕西西安）","state":"唐","sources":["《通典》自序","《旧唐书·杜佑传》","《新唐书·艺文志》"],"tags":["通典","杜佑","典制体"]},"related":[]},
  {"id":"cn--805--p01","track":"cn","year":805,"yearApprox":false,"dim":"politics","weight":4,"title":"永贞内禅，二王八司马","summary":"顺宗以风疾即位逾月而禅，王伾、王叔文党逐。","detail":{"background":"德宗崩，顺宗即位已不能言，倚东宫旧人王叔文、王伾，引韦执谊为相，欲夺宦官兵柄。","process":"805年（贞元二十一年、永贞元年）王叔文以杜佑领盐铁、刘闢副之，欲召神策将范希朝以夺兵，不克；内禅于太子纯，八月贬永贞诸人，王伾、王叔文寻死，刘禹锡、柳宗元等八人为远州司马。","impact":"短命的革新以宦官与藩镇的联合反扑告终，而顺宗一朝的用人之案成为宋代以后史论聚讼之端；柳宗元、刘禹锡由此长贬，其文与其政论皆发源于此。","figures":["王叔文","王伾","韦执谊","柳宗元","刘禹锡","顺宗李诵"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·王叔文传》","《新唐书·二王八司马传》","《资治通鉴》"],"tags":["永贞革新","二王八司马","宦官"]},"related":[]},
  {"id":"cn--806--m01","track":"cn","year":806,"yearApprox":false,"dim":"military","weight":3,"title":"高崇文擒刘辟，西川平","summary":"刘辟求兼三川不得，举兵拒命，旬时而枭。","detail":{"background":"顺宗末以刘辟为西川留后，辟自恃蜀险，求并东川、山南西道，宪宗新立，不许。","process":"806年（元和元年）三月，高崇文将东川兵由子午入，七月拔成都，刘辟走保鹿头山，被擒送京师斩之；西川平，朝廷以崇文镇之。","impact":"这是宪宗对藩镇第一次取胜，确立了以神策诸将讨不廷之镇的自信，元和削藩之局由是而开。","figures":["高崇文","刘辟","宪宗李纯"],"place":"成都、鹿头山（今四川成都、德阳）","state":"唐","sources":["《旧唐书·高崇文传》","《资治通鉴》","《新唐书·刘辟传》"],"tags":["刘辟","西川","元和中兴"]},"related":[]},
  {"id":"cn--806--c01","track":"cn","year":806,"yearApprox":false,"dim":"culture","weight":2,"title":"白居易《与元九书》论诗","summary":"文章合为时而著，歌诗合为事而作。","detail":{"background":"白居易与元稹同以讽喻相高，其元和初在周至、下邽间与元稹书往返，自定诗为讽喻、闲适、感伤、杂律四类。","process":"806年（元和元年）白居易作《与元九书》，谓诗者根情、苗言、华声、实义，又谓文章合为时而著、歌诗合为事而作；其《秦中吟》十首、《新乐府》五十篇即此时之制。","impact":"此说与元稹之论并为新乐府运动的纲领，将诗之美刺重新系于政教，中唐以后诗话与宋人论诗多循其途；白集自写自刻，流传于鸡林、日本。","figures":["白居易","元稹","张籍","王建"],"place":"下邽、长安（今陕西渭南、西安）","state":"唐","sources":["《白氏长庆集》","《元氏长庆集》","《旧唐书·白居易传》"],"tags":["新乐府","白居易","诗论"]},"related":[]},
  {"id":"cn--807--m01","track":"cn","year":807,"yearApprox":false,"dim":"military","weight":3,"title":"李锜据润州反，旬日就禽","summary":"镇海留后自备爪牙，事觉举兵，为下所执。","detail":{"background":"李锜以镇海节度使蓄谋拒命，召留后不赴，朝廷以武元衡之议决计征之；其所倚牙兵与使府将佐阴为内应。","process":"807年（元和二年）十月，李锜举兵于润州，围常州；其将庾行周、赵锜等反执锜，斩于阙下，浙西平，朝廷以李元素代镇。","impact":"朝廷以两镇之平示信于藩镇，元和削藩自此立威；浙西财赋不入私门，江淮漕盐两道始复为度支所有。","figures":["李锜","武元衡","李元素"],"place":"润州、浙西（今江苏镇江）","state":"唐","sources":["《旧唐书·李锜传》","《资治通鉴》","《新唐书·藩镇传》"],"tags":["李锜","镇海","浙西"]},"related":[]},
  {"id":"cn--813--c01","track":"cn","year":813,"yearApprox":false,"dim":"culture","weight":4,"title":"李吉甫成《元和郡县图志》","summary":"叙十道疆域、户口、山川与四至里距。","detail":{"background":"吉甫以宰相出镇淮南，因元和十道图修之，凡四十七镇，每镇为图与说，图亡而说存。","process":"813年（元和八年）表进《元和郡县图志》，叙郡县沿革、四至八到、户口多少、山川险易、贡赋与盐铁铸山之事，以京兆为首。","impact":"今存最古且最完整的总志，唐一代政区与里程之制全赖此书；其以户口比较盛衰、以险易论阨塞的写法，为宋《太平寰宇记》以下乐史一路所自出。","figures":["李吉甫"],"place":"长安、扬州（今陕西西安、江苏扬州）","state":"唐","sources":["《元和郡县图志》","《旧唐书·李吉甫传》","《新唐书·艺文志》"],"tags":["地理总志","元和郡县图志","沿革"]},"related":[]},
  {"id":"cn--814--m01","track":"cn","year":814,"yearApprox":false,"dim":"military","weight":3,"title":"吴元济据蔡州拒命","summary":"少阳死而匿丧，元济纵兵掠东都畿。","detail":{"background":"淮西自吴少诚以来结河朔为援，少阳死，其子元济秘不发丧，自立判军务，求旄节不得。","process":"814年（元和九年）闰八月吴元济反，纵兵劫掠叶县、襄州，围唐州，东都畿、汝、洛震骇；朝廷下诏讨之，以诸道兵二十余万分驻申、蔡之境。","impact":"淮西居天下之中而兵寡地狭，然三年不能下，唐廷财政与人心俱困；此役之胜败直接决定元和以后朝廷对河朔能否复振。","figures":["吴元济","吴少阳","宪宗李纯"],"place":"蔡州、申州（今河南汝南、信阳）","state":"唐","sources":["《旧唐书·吴元济传》","《资治通鉴》","《新唐书·藩镇传》"],"tags":["淮西","蔡州","元和中兴"]},"related":[]},
  {"id":"cn--815--p01","track":"cn","year":815,"yearApprox":false,"dim":"politics","weight":2,"title":"武元衡刺于长安，裴度代相","summary":"清晨里中矢杀首相，京师震恐，裴度继督战。","detail":{"background":"成德王承宗、淄青李师道皆请赦淮西，宰相武元衡持之不可；镇海、魏博遣盗入京师为应。","process":"815年（元和十年）六月，武元衡将朝，伏凶于通化里，伤颅而死；裴度中血伤而存，宪宗即以度为相，自将讨贼，不复赦两河。","impact":"当街刺相而朝廷不改其谋，是元和时中央威权最盛之一瞬；白居易以越职言事由此贬江州司马，谏官不得擅言亦为一制。","figures":["武元衡","裴度","白居易","王承宗"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·武元衡传》","《资治通鉴》","《新唐书·裴度传》"],"tags":["武元衡","裴度","元和党议"]},"related":[]},
  {"id":"cn--817--m01","track":"cn","year":817,"yearApprox":false,"dim":"military","weight":5,"title":"李愬雪夜入蔡州","summary":"九旬血战不下，一昼夜悬军入城而擒元济。","detail":{"background":"诸道兵屯蔡境三年无功，李愬以随唐邓节度使至，先取吴房、郎山，收降将丁士良、吴秀诚而用之，专以抚病卒、缓师期自异。","process":"817年（元和十二年）十月，大风雪，李愬率前军冒九泽绝涧而进，夜半至蔡州城下，城坎皆冰，以瓦为声而登，迟明克内城，吴元济束身请降，槛送京师。","impact":"淮西平，成德、魏博相继请质子、输两税，天下藩镇一时震恐，元和中中兴之业至此为极；此役亦为后世言奇兵者所祖。","figures":["李愬","吴元济","裴度","田承嗣"],"place":"蔡州（今河南汝南）","state":"唐","sources":["《资治通鉴》","《旧唐书·李愬传》","韩愈《平淮西碑》","《新唐书·李愬传》"],"tags":["蔡州","李愬","元和中兴"]},"related":[]},
  {"id":"cn--817--m02","track":"cn","year":817,"yearApprox":false,"dim":"military","weight":2,"title":"李师道为下所杀，淄青平","summary":"郓州城中众叛，斩师道传首，河朔暂皆奉法。","detail":{"background":"淄青李师道外结淮西、内遣盗焚河阴漕院，宪宗自平蔡后并力东向，以乌重胤、李听分道逼郓州。","process":"817年（元和十二年）十一月，都知兵马使刘悟倒戈入郓州，斩李师道，传首京师，所领十二州皆正置刺史，输两税如内地。","impact":"自广德以来最盛的一刻：唐廷于河南、河北重设刺史，漕路不复被劫；然长庆初销兵失策，河朔未几而复叛，元和之功不终。","figures":["李师道","刘悟","乌重胤","宪宗李纯"],"place":"郓州（今山东东平）","state":"唐","sources":["《旧唐书·李师道传》","《资治通鉴》","《新唐书·藩镇传》"],"tags":["淄青","郓州","元和削藩"]},"related":[]},
  {"id":"cn--819--c01","track":"cn","year":819,"yearApprox":false,"dim":"culture","weight":4,"title":"韩愈谏迎佛骨，贬潮州","summary":"以《论佛骨表》触怒，夕贬八千里外。","detail":{"background":"凤翔法门寺有护国真身塔，塔内有释迦文佛指骨一节；元和十四年春，中使迎骨入禁中三日，王公士庶奔走施舍。","process":"819年（元和十四年）正月，韩愈上《论佛骨表》，言古无佛、汉明帝以后国运不长，请以骨投诸水火；宪宗大怒欲杀之，裴度、崔群救免，贬潮州刺史。","impact":"此表为儒者辟佛最著之文，与《原道》并读，成后世道统论之先声；其在潮州逐鳄鱼、延赵德为师，岭海文教的自述皆原于此。","figures":["韩愈","宪宗李纯","裴度","孟郊"],"place":"长安、潮州（今陕西西安、广东潮州）","state":"唐","sources":["《旧唐书·韩愈传》","《昌黎先生集·论佛骨表》","《资治通鉴》"],"tags":["谏迎佛骨","韩愈","辟佛"]},"related":[]},
  {"id":"cn--819--f01","track":"cn","year":819,"yearApprox":false,"dim":"figure","weight":2,"title":"柳宗元卒于柳州","summary":"再贬永州十年，出为柳州，四年卒。","detail":{"background":"宗元以永贞党人贬永州司马，著书十余年；元和十年改刺柳州，在郡以钱货奴婢之口者，为立法赎之。","process":"819年（元和十四年）十一月柳宗元卒于柳州任所，年四十七；遗书属刘禹锡编次，韩愈为之志其墓。","impact":"其山水记与寓言为古文一格的极致，《天说》《封建论》则开宋人论势之先；永州、柳州两贬之地因之入于文学地图。","figures":["柳宗元","刘禹锡","韩愈"],"place":"柳州（今广西柳州）","state":"唐","sources":["《柳河东集》","《旧唐书·柳宗元传》","韩愈《柳子厚墓志铭》"],"tags":["柳宗元","古文","永州"]},"related":[]},
  {"id":"cn--820--p01","track":"cn","year":820,"yearApprox":false,"dim":"politics","weight":3,"title":"宪宗暴崩，穆宗立而长庆销兵","summary":"内寺斡旋而新君立，河朔以销兵复叛。","detail":{"background":"宪宗晚年服方士金石之药，性多躁怒，宦官陈弘庆弑之而托为暴疾；穆宗以位得于内，遂务姑息。","process":"820年（元和十五年正月）穆宗即位，长庆元年三月以田弘正移镇成德，卢龙兵乱；朝廷以销兵之诏夺河朔士卒之籍，乱兵因聚为变。","impact":"元和削藩之业一举而堕，长庆、宝历以后朝廷不复言河北，只以漕路为生死；禁军中尉得生杀天子之权，自此成为定制。","figures":["穆宗李恒","陈弘庆","田弘正","裴度"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·穆宗纪》","《资治通鉴》","《新唐书·藩镇传》"],"tags":["长庆销兵","宦官弑立","河朔"]},"related":[]},
  {"id":"cn--821--p01","track":"cn","year":821,"yearApprox":false,"dim":"politics","weight":3,"title":"长庆会盟与唐蕃碑","summary":"盟于长安、拉萨，碑立于今存，载舅甥协好。","detail":{"background":"贞元三劫盟后不复使通；德宗、顺宗两朝尝欲报怨，穆宗以新立求安静，乃修旧好，刘元鼎使拉萨。","process":"821年（长庆元年）十月唐、蕃会盟于长安西郊，明年会盟于逻些；823年立会盟碑于大昭寺前，碑文载两朝舅甥之位、封疆之界，至今存。","impact":"唐蕃二百年的战争由此收束，河西、陇右不复大兵；此碑是汉藏关系最早现存石刻，也是后世论中国边界与甥舅之好常举之据。","figures":["穆宗李恒","赤德祖赞","刘元鼎","大理卿"],"place":"长安、逻些（今陕西西安、拉萨）","state":"唐","sources":["《旧唐书·吐蕃传》","《唐蕃会盟碑》铭文","《资治通鉴》","《全唐文》"],"tags":["长庆会盟","唐蕃","会盟碑"]},"related":[]},
  {"id":"cn--822--c01","track":"cn","year":822,"yearApprox":false,"dim":"culture","weight":2,"title":"白居易除杭州刺史","summary":"筑堤蓄水以溉湖西，在郡日以诗纪事。","detail":{"background":"居易以中书舍人出为杭州刺史，时年五十，求外以避朝议；杭阻海潮，井苦不可食，民以陂泽为命。","process":"822年（长庆二年）秋居易至郡，筑堤防江，蓄水于钱塘湖以溉田千顷；明年罢郡，日与张祜、刘长卿辈游，其诗有「未能抛得杭州去，一半勾留是此湖」。","impact":"地方官以水利与文治为政，宋人治杭常以为则；白集在朝鲜、日本以刻本流布，长庆体的通俗一路由是定名。","figures":["白居易","李渤","张祜"],"place":"杭州（今浙江杭州）","state":"唐","sources":["《白氏长庆集》","《旧唐书·白居易传》","《新唐书·白居易传》"],"tags":["白居易","杭州","水利"]},"related":[]},
  {"id":"cn--827--c01","track":"cn","year":827,"yearApprox":true,"dim":"culture","weight":2,"title":"杜牧作《阿房宫赋》","summary":"借秦之骄以警长庆大起宫室者。","detail":{"background":"宝历间敬宗好治宫室、数出游畋，关辅骚然；杜牧时年二十余，在东都沈传师、牛僧孺幕府读书。","process":"长庆末宝历初（827年前后）杜牧作《阿房宫赋》，以「族秦者秦也，非天下也」结之，自谓因敬宗侈故而上。","impact":"此赋为唐文赋转变之枢纽，以骈四俪六出议论，开宋人文赋之法；牧之论兵、论财与论形势，皆以赋与史论存其意。","figures":["杜牧","敬宗李湛","沈传师"],"place":"洛阳、长安（今河南洛阳、陕西西安）","state":"唐","sources":["《樊川文集》","《旧唐书·文苑传》","《资治通鉴》"],"tags":["阿房宫赋","杜牧","文赋"]},"related":[]},
  {"id":"cn--831--p01","track":"cn","year":831,"yearApprox":false,"dim":"politics","weight":3,"title":"宋申锡之狱","summary":"宰相谋去权宦，反以反谋系狱，贬死。","detail":{"background":"文宗以王守澄典禁军、郑注出入禁中，思自拔于权幸，密谕宰相宋申锡引可仗之士。","process":"831年（大和五年）二月，王守澄之党反告申锡与漳王谋逆，系神策狱；郑澹、李汉等救之，贬申锡为开州司马，是岁卒于贬所，漳王赐死。","impact":"文宗自是益无所作为，遂有甘露之谋，事败而宰相为偶人；唐之亡不亡，自此不复出于外廷之议。","figures":["宋申锡","王守澄","文宗李昂","李汉"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·宋申锡传》","《资治通鉴》","《新唐书·李汉传》"],"tags":["宋申锡","甘露之变之先声","宦官"]},"related":[]},
  {"id":"cn--833--s01","track":"cn","year":833,"yearApprox":false,"dim":"science","weight":3,"title":"它山堰成，鄮县始得水","summary":"太和七年，令王元暐作堰截咸汐，灌溉七乡田数千顷。","detail":{"background":"四明它山之下，溪与海接，潮汐上下，咸卤随之而入，田者仰雨乃得艺，虽旱则无所取。","process":"唐太和七年（833），鄮令王元暐相地之宜，规而作堰于它山，截断咸汐而潴其淡水，灌溉七乡田数千顷。","impact":"明州之田自此不专仰雨，而鄞西水利以堰与它山庙为始；宋魏岘为一书专记其利害，则一堰之功历四百余年犹在，守者之法亦由是而著。","figures":["王元暐"],"place":"鄮县（今浙江宁波海曙区）","state":"唐","sources":["《宝庆四明志》","《四明它山水利备览》"],"tags":["它山堰","明州","水利","太和七年"]},"related":[],"checks":[{"by":"本站·维基文库比对（《四明它山水利备览·卷上》）","at":"2026-11-07","note":"本条两处引文皆出此卷：「唐太和七年邑令王侯元暐相地之宜……规而作堰截断咸汐」与「灌溉七乡田数千顷」。四库本此书只分上、下卷，无数字卷第，故以篇目记之"},{"by":"本站·维基文库比对（《宝庆四明志》卷十二）","at":"2026-11-07","note":"该卷「水」门《东钱湖辩》述它山石堰之文作「自唐大和中县令王元暐为它山石堰横截大江……水始回环汇于七乡以及于城郭」，系年仅云大和中；此语不系于它山堰专条，旧记作「它山堰条」今正；同卷「渠堰碶闸」门「溉田数千顷」一语属仲夏堰（唐太和元年刺史于季友），不可移属此堰"}]},
  {"id":"cn--835--p01","track":"cn","year":835,"yearApprox":false,"dim":"politics","weight":4,"title":"甘露之变，宰相朝士族诛","summary":"谋诛权宦而伏甲露，陈尸于台，二相死。","detail":{"background":"李训、郑注以攻王守澄进，别欲尽去其根；既封守澄，训更以禁中别兵为备，文宗密授其谋。","process":"835年（大和九年）十一月二十一日，金吾院称石榴夜有甘露，文宗御丹凤楼宣示，宰相王涯、舒元舆、贾餗以下尽入；伏甲不发而露，左右神策兵乱射台僚，尸横千步。","impact":"自是「天下事皆决于北司，宰相行文书而已」；文宗自谓受制于家奴，唐之内廷自此只有更立而无夺权，宦官与朝臣相仇之局至昭宗而两亡。","figures":["李训","郑注","王涯","舒元舆","仇士良","文宗李昂"],"place":"长安含元殿、东市（今陕西西安）","state":"唐","sources":["《旧唐书·文宗纪》","《资治通鉴》","《新唐书·李训传》","《剑桥中国隋唐史》"],"tags":["甘露之变","仇士良","北司"]},"related":[]},
  {"id":"cn--838--x01","track":"cn","year":838,"yearApprox":false,"dim":"explore","weight":3,"title":"最后一次的遣唐使入唐","summary":"藤原常嗣等四船来，圆仁随行，其后遂绝。","detail":{"background":"自贞观以来遣唐使前后十余辈，水陆万里，船亡者众；天平、延历以来其费日重，日本国内渐言其不可。","process":"838年（开成三年、承和五年）日本以藤原常嗣为大使、良孝象为判官，四船入扬州；沙门圆仁随行求法，其在唐十年所录为《入唐求法巡礼行记》。894年菅原道真奏请停遣，自是中日官使不复。","impact":"遣唐使一绝，东亚文化交流由官派转入商船与僧侣之途，五代之际明州、泉州海商遂为主脉；圆仁所记扬州、长安、淄青之事，为研究唐末社会最细之外国行记。","figures":["藤原常嗣","圆仁","菅原道真","楚明"],"place":"扬州、长安（今江苏扬州、陕西西安）","state":"唐","sources":["《入唐求法巡礼行记》","《类聚三代格》","《旧唐书·日本国传》","《新唐书·日本传》"],"tags":["遣唐使","中日交通","求法"]},"related":[]},
  {"id":"cn--840--m01","track":"cn","year":840,"yearApprox":false,"dim":"military","weight":4,"title":"回鹘汗国破，部众西奔","summary":"黀戛斯十万骑破都城，嗢没斯南来投唐。","detail":{"background":"回鹘自宝应以来以马市绢自厚，内乱方殷，疫且蝗；北黠戛斯起而乘之。","process":"840年（开成五年）黠戛斯以十万骑破回鹘牙城，焚其都，汗国遂亡；嗢没斯一部南奔天德请降，庞特勤率十五部西奔葛逻禄，其后为高昌、葱西之别。","impact":"漠北权空中，唐北边之患暂熄而代以沙陀；回鹘西迁一支立国于天山南北，其文字、历法与商业网络成为十世纪以后河西、西域的主脉，亦为蒙古高原部族重组之始。","figures":["嗢没斯","庞特勤","李德裕","田牟"],"place":"鄂尔敦河、天德（今蒙古国、内蒙古乌拉特前旗）","state":"唐","sources":["《旧唐书·回鹘传》","《新唐书·回鹘传》","《资治通鉴》"],"tags":["回鹘","黀戛斯","西迁"]},"related":[]},
  {"id":"cn--841--p01","track":"cn","year":841,"yearApprox":false,"dim":"politics","weight":3,"title":"武宗即位，李德裕入相","summary":"仇士良改策而立陈王，会昌一朝专委宰相。","detail":{"background":"文宗崩，宰相李珏、杨嗣复欲立安王，中尉仇士良以矫诏之罪改立颍王陈，是夜禁中定策。","process":"841年（会昌元年）武宗即位，未几，以李德裕同中书门下平章事，自是政事一归中书，三年之间内则平泽潞、外则受回鹘之降，皆德裕主之。","impact":"会昌是晚唐政事最振的一朝，亦为牛李党争的顶点：北司既立其君，宰相近于专政，宣宗立而德裕贬，党议遂不可解。","figures":["武宗李炎","李德裕","仇士良","杨嗣复"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·武宗纪》","《资治通鉴》","《新唐书·李德裕传》"],"tags":["会昌","李德裕","牛李党争"]},"related":[]},
  {"id":"cn--843--m01","track":"cn","year":843,"yearApprox":false,"dim":"military","weight":2,"title":"石雄夜出振武，破可汗牙帐","summary":"以百骑凿垒夜出，乌介中创走，公主得还。","detail":{"background":"回鹘嗢没斯既降，乌介可汗挟太和公主南阻天德、振武，求粮不得，连寇云、朔，边镇无如之何。","process":"843年（会昌三年）正月，石雄以杂职役为先锋，夜率精骑百余自振武城凿垒而出，望见毡车中篝火，直犯牙帐；乌介中创走，杀宰相、跌骨都督以下万级，太和公主得归。","impact":"会昌武功之一端，唐自代宗以来始有一胜；回鹘自此不复为边患，而代北沙陀以戍兵之功渐据河东之重。","figures":["石雄","乌介可汗","李德裕","张仲武","太和公主"],"place":"振武（今内蒙古和林格尔北）","state":"唐","sources":["《旧唐书·回鹘传》","《资治通鉴》","《新唐书·石雄传》"],"tags":["振武","回鹘","会昌武功"]},"related":[]},
  {"id":"cn--845--c01","track":"cn","year":845,"yearApprox":false,"dim":"culture","weight":5,"title":"会昌毁佛","summary":"天下寺两千余所尽废，僧二十六万还俗。","detail":{"background":"武宗好黄金之术，尤恶僧尼，中书门下以天下僧尼占田作役、不输两税为言，会昌二年以来渐为节文。","process":"845年（会昌五年）四月制并省天下寺：大凡寺四千六百余、兰若四万余，其吏勒归两税户者僧尼二十六万五百人，铜像、磬钟以铸钱，铁像以铸农器，天下士庶不得私蓄僧。","impact":"为三武一宗法厄中波及最深者，长安、洛阳之文教、俗讲、变相、壁画与经籍同归灰烬，会昌之籍遂为后世藏经与寺观史之一大断；宣宗虽复，佛教之重心已移于山林与禅门清规。","figures":["武宗李炎","李德裕","赵蕃"],"place":"长安、天下诸州","state":"唐","sources":["《旧唐书·武宗纪》","《资治通鉴》","《唐会要·断食》","《广弘明集》","《剑桥中国隋唐史》"],"tags":["会昌法厄","三武一宗","寺院经济"]},"related":[]},
  {"id":"cn--846--p01","track":"cn","year":846,"yearApprox":false,"dim":"politics","weight":3,"title":"宣宗立，大中之政","summary":"宦官所立而能自振，李德裕由是长贬。","detail":{"background":"武宗崩，太尉、中尉以光王太叔为皇太叔而立之，左右尝以其不慧；既立而接物精慎，朝野自以为得人。","process":"846年（会昌六年、大中元年）宣宗即位，尽反武宗之政：复佛法、省京官而重县令，召还贬臣；李德裕自荆南再贬潮州司马，又贬崖州司户参军。","impact":"宣宗精于吏职、务采虚名，时号小太宗，而于藩镇无策、于北司无根，止收河湟数州而不敢问幽蓟；牛、李更相倾轧，唐之纪纲遂不复振。","figures":["宣宗李忱","李德裕","令狐綯","郑颢"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·宣宗纪》","《资治通鉴》","《新唐书·李德裕传》"],"tags":["大中之治","宣宗","牛李党争"]},"related":[]},
  {"id":"cn--848--p01","track":"cn","year":848,"yearApprox":false,"dim":"politics","weight":4,"title":"张议潮举沙州，归命唐朝","summary":"以州民逐吐蕃守将，遣使间道奉图籍来。","detail":{"background":"自广德二年凉州继陷，河西、陇右戍兵东调，吐蕃以其论、尚分镇诸州，汉人服役为部曲，百年不复通中国。","process":"848年（大中二年）沙州人张议潮率州民起，逐吐蕃节儿，收瓜、伊、西、甘、肃等州，遣兄子惟深奉河陇图籍赴阙，间道历回鹘、白龙之地。","impact":"河湟之地百年之后复归于唐，宣宗于沙州置归义军，以议潮为节度；此军以土人自守，历唐、五代而至宋初，是丝路东段最后一段汉人政权的记录。","figures":["张议潮","曹仁景","安景旻","宣宗李忱"],"place":"沙州、瓜州（今甘肃敦煌、安西）","state":"唐","sources":["《资治通鉴》","《新唐书·吐蕃传》","《张议潮变文》","敦煌写本归义军文书"],"tags":["归义军","张议潮","河湟"]},"related":[]},
  {"id":"cn--850--f01","track":"cn","year":850,"yearApprox":false,"dim":"figure","weight":2,"title":"李德裕卒于崖州","summary":"自相位三贬至海上，会昌之政遂成陈迹。","detail":{"background":"德裕以会昌秉政四年，功在回鹘、泽潞；宣宗立后牛党复用，自尚书左仆射出为荆南，再贬潮州，又贬崖州司户参军。","process":"大中三年十二月（八四九年末至八五〇年初），李德裕卒于崖州（今海口）贬所；其子燿扶柩北归，文集与制诰则传于蜀中。","impact":"晚唐最有作为的宰相死于海上，其《会昌一品集》与论兵、论边诸文为研究会昌一朝最要本文；宋人论唐相，于德裕常致叹焉。","figures":["李德裕","令狐綯","郑颢"],"place":"崖州（今海南海口）","state":"唐","sources":["《会昌一品集》","《旧唐书·李德裕传》","《资治通鉴》"],"tags":["李德裕","崖州","晚唐宰相"]},"related":[]},
  {"id":"cn--851--i01","track":"cn","year":851,"yearApprox":false,"dim":"institution","weight":3,"title":"置归义军，河陇图籍入朝","summary":"以沙州为军治，土人自署将吏而名系于唐。","detail":{"background":"议潮起兵后西收伊、西，东取甘、肃、兰、鄯，河陇诸城次第来附；朝廷方务姑息，未能西顾。","process":"851年（大中五年）以沙州置军，号归义军，张议潮为节度观察处置等使，奉所管十一州图籍来上，宣宗图其形于麟德殿。","impact":"归义军以一方之兵守千里之地，不仰朝廷廪给而自署官吏，是唐代藩镇中唯一以土人自守为命的一型；其文书与莫高窟供养人像为十世纪河西社会唯一的直接史料。","figures":["张议潮","张淮深","曹仁景"],"place":"沙州（今甘肃敦煌）","state":"唐","sources":["《资治通鉴》","《新唐书·地理志》","敦煌莫高窟供养人题记"],"tags":["归义军节度","敦煌","沙州"]},"related":[]},
  {"id":"cn--853--c01","track":"cn","year":853,"yearApprox":true,"dim":"culture","weight":2,"title":"《酉阳杂俎》：晚唐之一部类书","summary":"志怪、考证、名物、边俗，无所不载。","detail":{"background":"段成式以进士历金州、处州，与温庭筠、李商隐唱和，其学博而好异，聚书万余卷。","process":"大中前后（八五〇年代）成《酉阳杂俎》三十卷，前集记忠、孝、博、异、物、草、木、酒、食，续集又七分，所载有西域、南海之方药与术。","impact":"此书为唐末笔记之渊薮：其中影戏、幻术、摩尼、火祆诸条，皆为中外交通史之要录；宋《太平广记》取之甚多。","figures":["段成式","温庭筠","李商隐"],"place":"长安、金陵（今陕西西安、南京）","state":"唐","sources":["《酉阳杂俎》","《新唐书·艺文志》","《唐才子传》"],"tags":["酉阳杂俎","笔记","段成式"]},"related":[]},
  {"id":"cn--859--d01","track":"cn","year":859,"yearApprox":false,"dim":"disaster","weight":3,"title":"浙东大旱与裘甫起事","summary":"会稽、明、台久旱而赋不解，民聚至三万。","detail":{"background":"自大中以来天下多水旱之灾，租庸之外别有宣索；浙右为朝廷财赋之地，而守令以聚敛为功。","process":"859年（大中十三年）十一月，裘甫聚众于象山、宁海，十二月陷鄮县、奉化，号天下都知兵马使，众至三万，浙东大震；860年以王式为观察使，发廪赈贫以散其党，禽裘甫于明州。","impact":"这是唐末民变的第一次成规模者，朝廷始悟财赋之乡亦可为乱；其后庞勋、王郢、黄巢相继而起，皆由戍兵与饥民合流一路。","figures":["裘甫","王式","懿宗李漼"],"place":"明州、越州（今浙江宁波、绍兴）","state":"唐","sources":["《资治通鉴》","《新唐书·食货志》","《唐语林》","《剑桥中国隋唐史》"],"tags":["裘甫","浙东民变","唐末"]},"related":[]},
  {"id":"cn--863--m01","track":"cn","year":863,"yearApprox":false,"dim":"military","weight":4,"title":"南诏三陷交州，安南遂没","summary":"蔡袭死之，自安南至岭表连年被寇。","detail":{"background":"自大中年南诏屡犯安南，唐以安南为边远，兵食不继，李系、蔡袭相继失计；南诏遂并力向东。","process":"863年（咸通四年）正月，南诏以五万之众三攻交州，都护蔡袭力战死之，城中官属三百余人同没，杀戮不可计；朝廷以徐嗣宗、高骈继领镇海、安南之任。","impact":"安南自此不复内属，唐失其一隅财赋与南方商路之口；而安南之兵食又牵动徐、泗、郓州之戍卒，庞勋之乱即由戍桂林、安南者不遣而起。","figures":["蔡袭","世隆","高骈","李系"],"place":"交州（今越南河内）","state":"唐","sources":["《资治通鉴》","《旧唐书·西南蛮传》","《新唐书·南蛮传》"],"tags":["南诏","安南","交州"]},"related":[]},
  {"id":"cn--868--c01","track":"cn","year":868,"yearApprox":false,"dim":"culture","weight":4,"title":"咸通本《金刚经》：现存最早纪年刻本","summary":"王玠为二亲刻施，卷末有咸通九年四月纪年。","detail":{"background":"自贞元以来写经之外已有刻版印本，市井有阴阳书、集字补阙与释氏功德之文，蜀中与江淮并为其地。","process":"868年（咸通九年）四月十五日王玠为二亲敬造普施《金刚般若波罗蜜经》一卷，扉页作说法图，卷末纪年；此卷于敦煌藏经洞复出，今藏伦敦。","impact":"此为现存最早有明确纪年、完整可阅的雕版印本，其刀法与墨色已极纯熟，可知此前刻书之久；由是书籍自写本入于刻本，宋初国子监九经之制实承此一路而来。","figures":["王玠"],"place":"成都、敦煌（今四川成都、甘肃敦煌）","state":"唐","sources":["咸通本《金刚经》卷末题记","李约瑟《中国科学技术史》","《剑桥中国隋唐史》"],"tags":["雕版印刷","金刚经","敦煌遗书"]},"related":[]},
  {"id":"cn--868--m01","track":"cn","year":868,"yearApprox":false,"dim":"military","weight":3,"title":"庞勋据徐州，戍卒北归","summary":"桂州戍者满岁不代，擅归而陷徐、泗。","detail":{"background":"徐泗戍兵备南诏，屯桂林六年不代；朝廷许满三年即与替，观察使李瓒以簿籍上闻而久不行。","process":"868年（咸通九年）七月，庞勋率戍卒北归，度淮而东，陷徐、泗、濠三州，众至二万，开府库募人为兵；朝廷以康承训督沙陀、吐浑之骑进讨，明年二月徐州平。","impact":"乱平而唐之两河已不可制：王仙芝、黄巢皆起于徐、郓之间，其将佐部曲多出此军；朝廷以朱温、时溥、朱瑄分领之，唐亡之局于是划定。","figures":["庞勋","李瓒","康承训","王仙芝"],"place":"徐州、桂林（今江苏徐州、广西桂林）","state":"唐","sources":["《资治通鉴》","《新唐书·康承训传》","《新唐书·庞勋传》"],"tags":["庞勋","桂林戍卒","徐泗"]},"related":[]},
  {"id":"cn--875--p01","track":"cn","year":875,"yearApprox":false,"dim":"politics","weight":3,"title":"王仙芝、黄巢起于濮、曹","summary":"私盐贩与饥民合流，号天补平均大将军。","detail":{"background":"乾符初关东连年水旱，蝗群起曹、濮，租税不减而吏促于上；盐禁既严，贩私者结徒党以自活。","process":"875年（乾符二年）六月，濮阳人王仙芝聚众数千人起于长垣，自称天补平均大将军、兼海内诸豪都统，攻陷曹、濮；六月冤句人黄巢以贩盐聚众应之，众至数千，掠淮南、山东。","impact":"王仙芝之号首以「平均」为义，为后世农民起兵立一名目；朝廷以招讨授官之策饵之，乱遂不可止，唐之亡势自此成。","figures":["王仙芝","黄巢","曾元裕","李郓"],"place":"长垣、冤句（今河南长垣、菏泽西南）","state":"唐","sources":["《资治通鉴》","《旧唐书·黄巢传》","《新唐书·逆臣传》"],"tags":["王仙芝","黄巢","乾符民变"]},"related":[]},
  {"id":"cn--878--m01","track":"cn","year":878,"yearApprox":false,"dim":"military","weight":3,"title":"黄巢渡江而南，转战十余州","summary":"度江入浙闽，逾岭陷漳、泉，众至数十万。","detail":{"background":"王仙芝死后黄巢并其众，北方诸道方聚兵，巢以流动避实：自江西入浙东，由仙霞岭开山七百里以入福建。","process":"878年（乾符五年）黄巢自信州度越山路入闽，陷福州；八年二月自桂州造船三千余艘，顺漓江、湘江而下，攻潭、岳，沿江州县多不能守，众至数十万。","impact":"此一转战十余州之举，暴露了唐以藩镇分守而无统一调度的军政之坏；江南、岭南经此一毁，朝廷财赋全仰江淮，而江淮亦非复承平之旧。","figures":["黄巢","高骈","王鐐","杨师立"],"place":"福州、广州、潭州（今福建福州、广东广州、湖南长沙）","state":"唐","sources":["《资治通鉴》","《新唐书·逆臣传》","《读史方舆纪要》"],"tags":["黄巢南征","流动作战","仙霞岭"]},"related":[]},
  {"id":"cn--879--d01","track":"cn","year":879,"yearApprox":false,"dim":"disaster","weight":3,"title":"黄巢陷广州，城中大疫","summary":"围城累月，城陷后疫作，蕃商死者以万计。","detail":{"background":"广州为市舶之地，蕃坊之内大食、波斯、祆、摩尼之徒杂处，库藏之富为南方之冠；巢军自桂州沿海南下。","process":"879年（乾符六年）十月黄巢陷广州，据之数月，将北归而图闽、浙；城中大疫，死者太半。《通鉴》但言疫，阿拉伯商纪则称被杀蕃客十万乃至二十万，学界多以为其数过当。","impact":"岭南经此一乱，唐末在广州之市舶与留后之政俱坏；此役亦为海上丝路史上第一次大劫，南海商路自此转重泉州、明州，而广州之蕃坊不复其盛。","figures":["黄巢","李迢","高骈"],"place":"广州（今广东广州）","state":"唐","sources":["《资治通鉴》","《旧唐书·黄巢传》","苏莱曼《中国印度见闻录》","《剑桥中国隋唐史》"],"tags":["广州之围","蕃坊","唐末大疫"]},"related":[]},
  {"id":"cn--880--m01","track":"cn","year":880,"yearApprox":false,"dim":"military","weight":5,"title":"黄巢入长安，国号大齐","summary":"汝、洛不守，广明入关；金统建号而唐祚不绝。","detail":{"background":"洛口一战，唐诸将奔；朝廷无兵可用，以张谼代卢携秉政，令诸道兵会猎。","process":"880年（广明元年）十二月，黄巢自灞上入长安，京兆尹薛能在渭桥战败，僖宗夜幸蜀中；巢即皇帝位于含元殿，国号大齐，建元金统，唐官三日而听其上任。","impact":"唐都在农民军之手第一次失守，朝廷以沙陀骑兵与东北藩镇始克收复；关中自此残破不复，而河中、太原、宣武三镇之势成，唐亡之局定于此五年之间。","figures":["黄巢","僖宗李儇","朱温","尚让","李克用"],"place":"长安（今陕西西安）","state":"唐","sources":["《旧唐书·僖宗纪》","《资治通鉴》","《新唐书·逆臣传》","《桂苑笔耕集》"],"tags":["黄巢入长安","金统","广明"]},"related":[]},
  {"id":"cn--882--p01","track":"cn","year":882,"yearApprox":false,"dim":"politics","weight":3,"title":"朱温以同州降唐，赐名全忠","summary":"齐东平王举同州来附，河中之围遂解。","detail":{"background":"朱温从黄巢度淮而北，为齐之同州防御使；河中之役攻王重荣急，齐将孟楷相仇，温遂以州降。","process":"882年（中和二年）九月，朱温以同州附唐，以为河中行营留后，赐名全忠；自是与王重荣并力攻长安，883年四月沙陀兵东入，巢遂弃长安而东。","impact":"黄巢军中骄将之降为唐室所用，是齐政权内部瓦解之关键；全忠由此有汴、宋之基，二十五年而移唐祚。","figures":["朱温","王重荣","李克用","尚让"],"place":"同州、河中（今陕西大荔、山西永济）","state":"唐","sources":["《旧唐书·僖宗纪》","《资治通鉴》","《新五代史·梁本纪》"],"tags":["朱温","同州降唐","中和"]},"related":[]},
  {"id":"cn--907--p01","track":"cn","year":907,"yearApprox":false,"dim":"politics","weight":5,"title":"唐亡，朱全忠建梁","summary":"禅位于汴，国号大梁；三百年的唐祚遂绝。","detail":{"background":"天祐二年白马驿一举，朝士三十余人被杀、投尸于河，唐之衣冠已尽；全忠以魏博、宣武、平卢之众都于汴，代立之具皆备。","process":"907年（天祐四年）四月，哀帝禅位于朱全忠，国号大梁，改元开平，以汴州为开封府；唐封疆镇、岳、渎之祀与长安之宫室皆移于梁。","impact":"唐亡非一姓之替，而是以汴、洛阳为中枢之五代十国开始的标志：藩镇之兵、盐铁之利与牙军之势成为列国通行的政治语法，宋初一切更革皆以是为一面之镜。","figures":["朱全忠","哀帝李柷","柳璨","张全义"],"place":"汴州、洛阳（今河南开封、洛阳）","state":"后梁","sources":["《旧五代史·梁太祖纪》","《资治通鉴》","《新五代史·梁本纪》","《五代会要》"],"tags":["唐亡","后梁","开平"]},"related":[]},
  {"id":"cn--909--p01","track":"cn","year":909,"yearApprox":false,"dim":"politics","weight":3,"title":"王审知封闽王","summary":"开平三年庚子，以王审知为闽王，刘隐为南平王。","detail":{"background":"审知与兄潮自光州入闽，据福州；审知承兄之后，节衣缩食、通商惠工，奉贡于中原而不与邻道争衡，闽人安之。","process":"后梁开平三年（909）夏四月庚子，以王审知为闽王，刘隐为南平王。通鉴此条在「夏，四月，丙申朔」之下，故月从《通鉴》；《新五代史·闽世家》但云梁太祖封闽王，不书年月。","impact":"王氏之有闽自此入于中国之封爵，而闽、广海上之利遂为五代一偏之国；至审知之子称帝改元，而海商、寺塔与三佛齐之舶皆系于是年之封。","figures":["王审知","刘隐"],"place":"福州（今福建福州）","state":"后梁","sources":["《资治通鉴·后梁纪》","《新五代史·闽世家》"],"tags":["闽国","福州","开平三年","王审知"]},"related":[],"checks":[{"by":"本站·维基文库比对（《资治通鉴》卷二百六十七）","at":"2026-11-07","note":"纪年标记「开平三年（己巳，公元九零九年）」，正文「庚子，以王审知为闽王，刘隐为南平王」；《新五代史》卷六十八《闽世家》但云「唐亡，梁太祖加拜审知中书令，封闽王」，不书年，故年独取《通鉴》"}]},
  {"id":"cn--916--p01","track":"cn","year":916,"yearApprox":false,"dim":"politics","weight":4,"title":"耶律阿保机建契丹国","summary":"即皇帝位，定年号神册，南北面官之制渐立。","detail":{"background":"契丹八部旧以三年推立可汗，阿保机以迭剌部之强并兼诸部，养腹心部、创城郭、立仓储，不复行旧选。","process":"916年（神册元年）阿保机即皇帝位，其后定元号、建皇都于滦河之北、孔子庙于上京；神册末命近臣制契丹大字，又取燕南诸州、定渤海，制度日就。","impact":"北方部族第一次以皇帝、年号、城郭、文字与法度立国；其以国制治契丹、以汉制待汉人之南北面官，为辽、金、元三代二元统治之祖。","figures":["耶律阿保机","述律后","韩延徽","耶律突吕不"],"place":"滦河之北、上京（今内蒙古巴林左旗）","state":"契丹","sources":["《辽史·太祖纪》","《新五代史·四夷附录》","《资治通鉴》","《剑桥中国辽西夏金元史》"],"tags":["契丹建国","神册","南北面官"]},"related":[]},
  {"id":"cn--932--c01","track":"cn","year":932,"yearApprox":false,"dim":"culture","weight":4,"title":"国子监始雕印九经","summary":"冯道奏请依石经文字刻九经印板，历三朝乃成。","detail":{"background":"唐末以来士人多蓄写本而讹误百出，蜀中、江淮已有印本行市；宰相冯道以经籍讹谬，请官方校正而镂板。","process":"932年（长兴三年）国子监奏请依石经文字刻《九经》印板，由田敏等校定，历后晋、后汉以至周显德二年（955）始成，号曰九经板。","impact":"这是中国政府第一次以雕版印行正经，儒家经典自此由写本时代入于刻本时代；北宋两浙、福建之胄监本、书坊本皆由此风而开，书籍之普及与科举之扩张同其始终。","figures":["冯道","田敏","李愚"],"place":"洛阳、汴州（今河南洛阳、开封）","state":"后唐","sources":["《旧五代史·冯道传》","《资治通鉴》","《燕翼诒谋录》","《宋会要辑稿·崇儒》"],"tags":["九经雕印","冯道","书籍史"]},"related":[]},
  {"id":"cn--936--m01","track":"cn","year":936,"yearApprox":false,"dim":"military","weight":4,"title":"晋阳起兵与幽蓟十六州","summary":"石敬瑭借兵于契丹，割燕云十六州以报之。","detail":{"background":"潞王从珂以凤翔入立，猜忌河东节度使石敬瑭，移镇之命屡下；敬瑭以子礼事契丹主耶律德光，求其内援。","process":"936年（清泰三年、天显十一年）闰五月，敬瑭举于晋阳，契丹自雁门南下，封敬瑭为晋帝；十一月入洛，唐亡。其后以幽、蓟、瀛、莫、涿、檀、顺、新、妫、儒、武、云、应、寰、朔、蔚十六州图籍输契丹，岁输帛三十万匹。","impact":"燕云既失，华北自河北至河东无险可守，宋立国一百六十余年常以收复为言而终不可得；契丹（辽）由此有汉地、汉赋与汉官，其国势十倍于旧部落。","figures":["石敬瑭","耶律德光","赵德钧","张敬达"],"place":"晋阳、幽州（今山西太原、北京）","state":"后晋","sources":["《旧五代史·晋高祖纪》","《资治通鉴》","《辽史·太宗纪》","《新五代史·晋本纪》"],"tags":["幽云十六州","契丹","石敬瑭"]},"related":[]},
  {"id":"cn--937--p01","track":"cn","year":937,"yearApprox":false,"dim":"politics","weight":3,"title":"段思平起通海，建国大理","summary":"后晋天福二年兴师问罪，改国号曰大理，改元文德。","detail":{"background":"唐亡而南诏之嗣微，郑买嗣、赵善政、杨干贞更相篡夺，最后杨氏立大义宁国，诸部不服，通海节度使段思平以其众起。","process":"后晋天福二年（937），段思平兴师问罪，杨干贞不能御，走死；遂改国号曰大理，改元曰文德。","impact":"自蒙氏之亡至是，云南凡三次易姓；大理氏之立最久，与宋不臣而宋亦不征，其俗、其文字与汉相望至三百余年，元初犹为附国。","figures":["段思平","杨干贞"],"place":"苴咩（今云南大理）","state":"后晋","sources":["《滇载记》"],"tags":["大理国","通海","文德","天福二年"]},"related":[],"checks":[{"by":"本站·维基文库比对（https://zh.wikisource.org/wiki/滇载记，全书作一页）","at":"2026-11-07","note":"原文「通海节度使段思平，兴师问罪，于真不能御，走死」「遂改国号曰大理，改元曰文德。时后晋天福二年也」；正文所称杨干贞即本书之於真（从通称不改名），引文则仍其旧；维基文库此书只作一页，页中无卷第可引，先前记作「卷一」是据著录而非据页，今改正，以页面本身为定位。又本书作「改城…苴咩」并自注「今大理」，又云「都曰苴咩，别都曰善阐」，place 旧作「羊咩城」系从他书之名，今改从本书（惟此二句在本书异牟寻段，段思平受册之文不重出地名，苴咩之为今大理乃本书前文自注，非九三七年本文所记）；今地名「云南大理」未动，叠加层指向如故；background 所历三姓亦本书本文：「其臣郑买嗣夺之……改国号曰大长和」「未几，为东川节度使杨於真所杀」「赵氏名善政……改国号曰大天兴」「於真又夺之……改国号曰大义宁」"}]},
  {"id":"cn--940--c01","track":"cn","year":940,"yearApprox":false,"dim":"culture","weight":3,"title":"《花间集》成于成都","summary":"赵崇祚集十八家词五百首，欧阳炯为序。","detail":{"background":"西蜀承平，王建、孟氏父子以声色自奉，歌辞之制盛于府廷；温庭筠以下诸家所作，倡家传习而无总集。","process":"940年（广政三年）四月，卫尉少卿赵崇祚集温庭筠、韦庄以下十八人词五百首为《花间集》十卷，欧阳炯为序，谓「言言花木，句句绮罗」。","impact":"此为文人词最早之总集，词之一体自此有家数与选本，其绮侧怨深之格直启北宋晏、欧；西蜀、南唐并为宋初词学之源。","figures":["欧阳炯","赵崇祚","温庭筠","韦庄"],"place":"成都（今四川成都）","state":"后蜀","sources":["《花间集》欧阳炯序","《十国春秋·后蜀》","《旧五代史·和凝传》"],"tags":["花间集","文人词","西蜀"]},"related":[]},
  {"id":"cn--950--a01","track":"cn","year":950,"yearApprox":true,"dim":"art","weight":3,"title":"荆浩《笔法记》与北方山水","summary":"以图写真、以笔墨论品，太行之中山水一体。","detail":{"background":"唐末丧乱，士人多隐于太行、洪谷；荆浩自号洪谷子，画山水松石，所撰《笔法记》以气体思韵笔墨六要论画。","process":"五代末（约九十世纪中叶）荆浩作《笔法记》，假与山中叟问答，定皴、染之法，称吴道子有笔而无墨、项容有墨而无笔，欲采二子之所长。","impact":"北方全景式山水至此立其法度，关仝、郭忠恕以至宋之李成、范宽皆出其下；以笔墨分品之论亦为宋以后画学批评之根本语汇。","figures":["荆浩","关仝","吴道子","项容"],"place":"太行、汴州（今河南、山西交界）","state":"后周","sources":["《笔法记》","《图画见闻志》","《林泉高致》","《唐朝名画录》"],"tags":["荆浩","山水画笔墨","五代画史"]},"related":[]},
  {"id":"cn--955--c01","track":"cn","year":955,"yearApprox":false,"dim":"culture","weight":4,"title":"显德毁佛与均定田赋","summary":"禁私度、熔像钱，铜铁入官；均田之使行。","detail":{"background":"会昌之后宣宗复佛，寺额渐增；至周有天下而县数不减、耕夫多入于僧，铜钱益少，世宗以政事与财用并计。","process":"955年（显德二年）四月诏天下 每县留僧寺名额，非敕额者废三万余所，勒还俗者二万余；以其铜像铸钱，私度者死；又命均定河南诸州田赋。","impact":"此为三武一宗之末一宗：佛教之势力自是不复有庄园人口之实，而宋之寺额、度牒遂纯为财政之具；均田之议开宋初方田均税、一条鞭之先路。","figures":["世宗柴荣","禅宇","李谷"],"place":"汴州、天下诸州","state":"后周","sources":["《旧五代史·周世宗纪》","《资治通鉴》","《五代会要·佛骨》","《佛祖统纪》"],"tags":["显德毁佛","三武一宗","度牒"]},"related":[]},
  {"id":"cn--960--p01","track":"cn","year":960,"yearApprox":false,"dim":"politics","weight":5,"title":"陈桥兵变，赵匡胤即皇帝位","summary":"军校拥立，还自国门而禅姓，宋建隆。","detail":{"background":"世宗崩而七岁之主立，契丹入寇之报骤至，殿前都点检赵匡胤将禁军北出；都下已喧言将以出师之日立点检为天子。","process":"960年（建隆元年）正月初四，次陈桥驿，军中以黄袍加身，还自开封北门入，符后与幼主让位，唐、晋、汉、周之五代至此终，宋有天下。","impact":"禁军拥立而一姓易命，此即宋初一切防内之策的原点：杯酒释兵权、更戍法、以文臣知州、枢密与三衙相维，皆自陈桥之例而来。","figures":["赵匡胤","赵普","符太后","韩通","沈义伦"],"place":"陈桥、开封（今河南开封）","state":"宋","sources":["《宋史·太祖纪》","《续资治通鉴长编》","《邵氏闻见录》《东都事略》","《宋会要辑稿》"],"tags":["陈桥兵变","建隆","宋初"]},"related":[]},
  {"id":"cn--961--i01","track":"cn","year":961,"yearApprox":false,"dim":"institution","weight":4,"title":"强干弱枝：罢宿将而制藩镇","summary":"以节级之兵补卫士，易以文臣而天下有兵而无将。","detail":{"background":"帝以五代以来兵骄逐帅、帅强叛上为然，赵普以为惟兵权财赋归之于上，则天下自定。","process":"961年（建隆二年）十月，罢石守信、王审琦等宿卫，出为外镇；又令诸道精兵选送阙下为禁旅，弱枝之意定焉。","impact":"自是唐末以来方镇之祸永不复起，而兵将相离、内外相维之制使宋世用兵常以将从中御、兵不识将，其费与其弱并为后世所议。","figures":["赵匡胤","赵普","石守信","王审琦"],"place":"开封（今河南开封）","state":"宋","sources":["《宋史·职官志》","《续资治通鉴长编》","《丁晋公谈录》《默记》","《宋史·石守信传》"],"tags":["强干弱枝","更戍法","杯酒释兵权"]},"related":[]},
  {"id":"cn--971--x01","track":"cn","year":971,"yearApprox":false,"dim":"explore","weight":3,"title":"岭南平，复置市舶于广州","summary":"南汉既下，即其旧制置吏以征蕃货。","detail":{"background":"南汉一姓以广州为市舶之利，取蕃商珠宝以充国用；潘美等克兴王府后，朝廷因其旧而设官。","process":"971年（开宝四年）二月平南汉，即其地置市舶之司，以知州、通判领之；太祖遣内侍高绍谋等往广州访求宝货，其后淳化中再废再置，真宗时专任转运。","impact":"宋之海外贸易自此由国家征榷，其香药、宝货之入与抽解、博买之法，皆立基于此时；至熙宁以后，市舶岁入为国用之助，东南之富愈移于海上。","figures":["潘美","刘鋹","高绍谋"],"place":"广州（今广东广州）","state":"宋","sources":["《宋会要辑稿·职官》","《宋史·食货志》","《续资治通鉴长编》","《萍洲可谈》"],"tags":["市舶司","广州","海上丝路"]},"related":[]},
  {"id":"cn--978--p01","track":"cn","year":978,"yearApprox":false,"dim":"politics","weight":3,"title":"吴越纳土，两浙入于宋","summary":"钱俶举国十三州献于朝，东南不复有兵。","detail":{"background":"钱氏有兩浙五十余年，自镠以来以事大、通商、缮城为国策；朱刘、南唐既尽，独吴越未下。","process":"978年（太平兴国三年）五月，吴越王钱俶上表尽献所管十三州、一军、八十六县之版图于朝，宋徙其族于汴；南平、武平继之内附，唯余泉、漳未下。","impact":"东南以一兵不血而归于统一，漕渠、海商与两浙之刻书、丝织自此并为宋廷所有；钱氏自保之策成为后世论割据与纳土的两端例证。","figures":["钱俶","赵光义","崔仁佐","孙太真"],"place":"杭州、汴京（今浙江杭州、河南开封）","state":"宋","sources":["《宋史·吴越俶传》","《续资治通鉴长编》","《十国春秋·吴越》","《吴郡志》"],"tags":["吴越纳土","太平兴国","两浙"]},"related":[]},
  {"id":"cn--1005--i01","track":"cn","year":1005,"yearApprox":false,"dim":"institution","weight":5,"title":"澶渊之盟：宋约为兄弟之国","summary":"银十万两、绢二十万匹，界河为界而榷场通。","detail":{"background":"契丹以二十万骑入冀北，直薄澶州；宰相寇准固请真宗北渡登城，辽之统军萧挞览中弩死，两军相持，而宋之将相多有请和之议。","process":"1005年（景德元年十二月、二年正月）宋、辽约为兄弟之国：以白沟、界河为界，各守疆土，无相袭盗；宋岁输辽银十万两、绢二十万匹，使者以贺生辰、即位为常礼，缘边置榷场。","impact":"此后宋、辽更不举兵百二十年，河北之民得耕，边备转为岁币，而京师西向之兵得以南征交趾、蜀中；议者自富弼、司马光以下，常以是盟为得与失两存之大案。","figures":["寇准","真宗赵恒","萧太后","隆绪","曹利用"],"place":"澶州（今河南濮阳）","state":"宋","sources":["《续资治通鉴长编》","《宋史·真宗纪》","《辽史·圣宗纪》","《剑桥中国宋代史》"],"tags":["澶渊之盟","岁币","宋辽关系"]},"related":[]},
  {"id":"cn--1006--a01","track":"cn","year":1006,"yearApprox":false,"dim":"art","weight":2,"title":"《益州名画录》成","summary":"景德三年五月，李畋为之序；五十八人，品以四格。","detail":{"background":"益都多名画，富视他郡。唐二帝播越、诸侯作镇之秋，画艺之杰者游从而来，故其标格楷模无处不有；迨淳化甲午，盗发二川，墙壁之绘、家秘之宝焚劫略尽。江夏黄休复居蜀，心郁久之，乃笔之于书。","process":"景德三年（1006）五月二十日，李畋为之序，序谓是书自李唐乾元初至皇宋乾德岁，取其目所击者五十八人，品以四格，离为三卷。","impact":"逸、神、妙、能四格之目，与《唐朝名画录》并为唐宋画品之存者；蜀画之赖是以传，而一域之艺可自为谱，不俟京师之目。","figures":["黄休复","李畋"],"place":"成都（今四川成都）","state":"北宋","sources":["《益州名画录·序》","《四库全书总目·益州名画录提要》"],"tags":["益州名画录","画品","景德三年","两蜀"]},"related":[],"checks":[{"by":"本站·维基文库比对（《益州名画录·序》）","at":"2026-11-07","note":"序末「时景德三年五月二十日序」，又「自李唐乾元初至皇宋乾德岁……取其目所击者五十八人，品以四格，离为三卷，命曰益州名画录」，background 之「唐二帝播越」「淳化甲午盗发二川」皆序本文；旧稿background作「唐季中原多故，画者西行」系以意为之，与序所记两帝入蜀之因不同，今改从序"},{"by":"本站·维基文库比对（《四库全书总目·益州名画录提要》）","at":"2026-11-07","note":"此提要维基文库无独立卷页可核（《四库全书总目》卷一百十二、一百十三诸目页返回错误页，页面本身亦仅为转引 djvu 的 stub），故不写类名与卷次；本次所核为维基文库「益州名畫錄」本页 header notes 字段所录提要全文，旧记「子部·书画类」系通行分类而非本页所见，今改正为篇目级定位。提要著录为二卷，与序之「离为三卷」异，其异文未强合；又提要云「今本直作畋序，又与宋时本不合」「别本但题李畋之名，不以序文出李畋」，故process之「李畋为之序」从通行本与诸刻本，非宋本之旧；官名、郡望之异亦具见于此条"}]},
  {"id":"cn--1012--e01","track":"cn","year":1012,"yearApprox":false,"dim":"economy","weight":3,"title":"占城稻种给江、淮、两浙","summary":"以福建所蓄种万斛分给三州，仍榜其种法。","detail":{"background":"江、淮、两浙之民常以五月而种，一遇旱暵则失望；占城稻耐旱而六十日熟，闽中先得其种。","process":"1012年（大中祥符五年）五月，真宗以江淮稍后稔，遣使就福建取占城稻种三万斛，分给江、淮、两浙，使民随地而种，仍榜其莳法于路边高表之。","impact":"早熟之稻既行，江南始有再熟之田，田少而谷多，于是圩田、山田尽辟；稻作之加与水利之盛，实为十二世纪以后南方人口数倍于北之本。","figures":["真宗赵恒","陈靖","丁谓"],"place":"福建、江、淮、两浙","state":"宋","sources":["《宋史·食货志》","《续资治通鉴长编》","《玉海·农稼》","《宋会要辑稿·食货》"],"tags":["占城稻","农作制","江南农业"]},"related":[]},
  {"id":"cn--1023--i01","track":"cn","year":1023,"yearApprox":false,"dim":"institution","weight":5,"title":"益州置交子务：官办纸币之始","summary":"私交子既弊，官为收其权而界以本钱。","detail":{"background":"蜀专用铁钱，重而不可致远，商贾以文据互市，号曰交子；后十六户主之，赀贫不能兑付，词讼日作。","process":"1023年（天圣元年）十一月，从薛田、寇瑊之议，废民间私交子，置益州交子务，以三年为一界，每界造百二十五万六千三百四十余缗，以本钱三十六万缗为率，届期以新易旧。","impact":"此为世界上第一种由官家定期发行、有准备金与界分之纸币；其后陕西钱引、东南会子、金之交钞、元之中统宝钞，节目皆本于交子务之旧。学界于其起止、界数与贯文，因史料残缺而有异说。","figures":["薛田","寇瑊","张若谷","仁宗赵祯"],"place":"益州（今四川成都）","state":"宋","sources":["《宋史·食货志》","《续资治通鉴长编》","《文献通考·货币考》","《宋会要辑稿·食货》"],"tags":["交子","纸币","四川铁钱"]},"related":[]},
  {"id":"cn--1038--p02","track":"cn","year":1038,"yearApprox":false,"dim":"politics","weight":4,"title":"元昊称帝，国号大夏","summary":"改元天授礼法延祚，制国字、定百官之制。","detail":{"background":"李氏世有夏州，至德明以契丹、宋两受其封；元昊既立，去唐、宋所赐之姓，以秃发为祖，日与群臣讲法制而谋建国。","process":"1038年（大庆三年、天授礼法延祚元年）十月，元昊即皇帝位，国号大夏，制西夏字（野利仁荣等主之），定百官之制：中书、枢密、三司以次而设，又置十六司、创军额。","impact":"夏之制度并非一王之造：其兼采宋之官制、蕃礼之节文与回鹘、吐蕃之文字而为一国之制，此后与宋、辽（金）鼎立百九十年，为西北通道与海上丝路的陆上一端。","figures":["李元昊","野利仁荣","德明","没藏黑云"],"place":"兴州（今宁夏银川）","state":"西夏","sources":["《宋史·夏国传》","《续资治通鉴长编》","《辽史·西北属国传》","《剑桥中国辽西夏金元史》"],"tags":["西夏建国","元昊","西夏文字"]},"related":[]},
  {"id":"cn--1044--s01","track":"cn","year":1044,"yearApprox":false,"dim":"science","weight":4,"title":"《武经总要》：火药方与指南鱼","summary":"官修兵书四十卷，载火药三法与磁鱼指南。","detail":{"background":"仁宗以边备方殷、诸家兵法散乱，命曾公亮与丁度取军政之要、历代用兵之迹，集群书而修之。","process":"1044年（庆历四年）《武经总要》前集二十卷、后集二十卷成：叙制度、选将、料兵与城攻之具，后载用兵之迹；其「火药法」条有毒药烟球、蒺藜火球、火炮三方， 又记以铁叶鱼磁之而浮于水、以指南之法。","impact":"此为火药配方与军用指南装置现存最早的官书明文记载，火器自是渐由燃烧之具转为攻城、野战之利；其器械图说亦为研究十一世纪军器之唯一系统记录。","figures":["曾公亮","丁度","仁宗赵祯"],"place":"开封（今河南开封）","state":"宋","sources":["《武经总要》","《宋史·曾公亮传》","《续资治通鉴长编》","李约瑟《中国科学技术史》"],"tags":["武经总要","火药","指南鱼"]},"related":[]},
  {"id":"cn--1045--s01","track":"cn","year":1045,"yearApprox":true,"dim":"science","weight":5,"title":"毕昇作活字印版","summary":"以胶泥刻字，火烧令坚，两板更互，日印千数。","detail":{"background":"自五代刻九经以来，雕版既行而费工、费版，一书之成动经岁月，误字则一版皆废。","process":"庆历中（约一〇四一至一〇四八年）布衣毕昇以活板印书：用胶泥刻字薄如钱唇，火烧令坚，先设铁板，以松脂、蜡和纸灰之类冒之，欲印则以铁范置板上，密布字印，一板印刷则一板已自布字，更互用之。其法见沈括《梦溪笔谈》。","impact":"活字之法较之雕版可以重复、可以补缺，为印刷史之大变；其后元之王祯木活字与铜活字、朝鲜与欧洲之铅字，皆在印刷可复制这一观念之下。毕昇之卒里与传习无可考，所依唯沈括一条，学界以为其板之制或至宋末而微。","figures":["毕昇","沈括"],"place":"开封、杭州（今河南开封、浙江杭州）","state":"宋","sources":["《梦溪笔谈》卷十八","《宋史·艺文志》","李约瑟《中国科学技术史》","《剑桥中国宋代史》"],"tags":["活字印刷","毕昇","梦溪笔谈"]},"related":[]},
  {"id":"cn--1046--c01","track":"cn","year":1046,"yearApprox":false,"dim":"culture","weight":3,"title":"范仲淹作《岳阳楼记》","summary":"庆历六年九月十五日，以洞庭之观写忧乐之怀。","detail":{"background":"庆历四年，滕宗谅谪守巴陵郡，政通人和，百废具兴，乃重修岳阳楼，刻唐贤今人诗赋于其上，属仲淹作文以记之。","process":"庆历六年（1046）九月十五日，仲淹为记。其文于楼之状不多着笔，独写洞庭之观，而以「先天下之忧而忧，后天下之乐而乐」归之。","impact":"巴陵、洞庭自此与一篇之文并传；谪守之楼以记行者，后世多本于此，而士之处江湖而忧其君者，遂有一域之名可据。","figures":["范仲淹","滕宗谅"],"place":"巴陵（今湖南岳阳）","state":"北宋","sources":["《范文正公集》"],"tags":["岳阳楼记","巴陵","洞庭","庆历六年"]},"related":[],"checks":[{"by":"本站·维基文库比对（《范文正公集》卷七）","at":"2026-11-07","note":"其文有「庆历四年春，滕子京谪守巴陵郡」「属予作文以记之」，末「时六年九月十五日」；维基文库《岳阳楼记》页头所从来标注「范文正公集/卷07」，故卷七。向曾误记作卷九，此正之"}]},
  {"id":"cn--1048--d01","track":"cn","year":1048,"yearApprox":false,"dim":"disaster","weight":3,"title":"黄河决商胡，河改北流","summary":"大决于澶州之东，自此河不东行。","detail":{"background":"自汉以来河常东北入海，宋初屡决于澶、郓之间，商胡埽当河之冲而岁增完费。","process":"1048年（庆历八年）六月，河大决商胡埽（今河南濮阳东），夺行故道而北，北趋大名之西，至乾宁军（今青县）入海；旧道自是淤为田，六塔、小吴诸役相继。","impact":"此后宋之河患有北流、东流两大议，神宗时回河之役费不可胜计，役夫死者相枕；河改道又使河北塘泺之险可为边备，而漕渠、田赋随之以变，为十一世纪一大政争。","figures":["仁宗赵祯","文彦博","李仲昌"],"place":"商胡埽、乾宁军（今河南濮阳、河北青县）","state":"宋","sources":["《宋史·河渠志》","《续资治通鉴长编》","《梦溪笔谈》","《宋会要辑稿·方域》"],"tags":["黄河改道","商胡决口","回河之议"]},"related":[]},
  {"id":"cn--1057--c01","track":"cn","year":1057,"yearApprox":false,"dim":"culture","weight":3,"title":"欧阳修知贡举，嘉祐二年一榜","summary":"痛抑太学体，一榜得苏、曾、张、程诸人。","detail":{"background":"庆历以来太学诸生号为「太学体」，以怪僻险涩相尚，场屋之文遂不可读；修以文章之道自任。","process":"1057年（嘉祐二年）正月，翰林学士欧阳修知礼部贡举，以平澹典雅取人，凡所黜者皆习为恶者，士至哗于道路；是榜得苏轼、苏辙、曾巩、张载、程颢、吕大防、章惇以下数十百人。","impact":"此榜于文风、道学与政事三途并为宋一代人才之枢；自是古文为场屋之准，洛学、蜀学之人与新党、旧党之界皆自此出。修又定「一场去留」之制，科举之防益密。","figures":["欧阳修","苏轼","曾巩","梅尧臣","韩琦"],"place":"开封（今河南开封）","state":"宋","sources":["《宋史·选举志》","《欧阳修全集》","《诚斋诗话》","《续资治通鉴长编》"],"tags":["嘉祐二年","科举","古文"]},"related":[]},
  {"id":"cn--1069--p01","track":"cn","year":1069,"yearApprox":false,"dim":"politics","weight":5,"title":"王安石秉政，熙宁变法始","summary":"设制置三司条例司，以理财、整兵为一事。","detail":{"background":"仁、英之际，天下以冗官、冗兵、冗费为大病，契丹西夏交以为忧；神宗新立，以文学之臣王安石知江宁府，越次召对。","process":"1069年（熙宁二年）二月，以王安石为参知政事，置制置三司条例司议改官制与财计；其下青苗、均输、农田水利、免役、市易、保甲、保马、方田均税诸法以次举行。","impact":"宋之财用、兵制与科举自此为一新局：免役行而吏得钱、民出钱，市易行而商税入于官，保甲行而民有兵役之实。议者自司马光、苏轼以下至于宋末，皆以新法聚敛、生事为口舌，其得失至今为史家之讼端。","figures":["王安石","神宗赵顼","吕惠卿","司马光","韩维"],"place":"开封、江宁（今河南开封、江苏南京）","state":"宋","sources":["《宋史·王安石传》","《续资治通鉴长编》","《文献通考·国用考》","《剑桥中国宋代史》"],"tags":["熙宁变法","王安石","制置三司条例司"]},"related":[]},
  {"id":"cn--1082--c01","track":"cn","year":1082,"yearApprox":false,"dim":"culture","weight":3,"title":"苏轼于黄州赋赤壁","summary":"以诗下御史狱，责黄州团练副使；元丰五年，前《赤壁赋》成。","detail":{"background":"轼徙知湖州，上表以谢，又以事不便民者不敢言，以诗托讽，庶有补于国。御史李定、舒亶、何正臣摭其表语，并媒孽所为诗以为讪谤，逮赴台狱，欲置之死，锻炼久之不决。","process":"神宗独怜之，以黄州团练副使安置；轼与田父野老相从溪山间，筑室于东坡，自号东坡居士。元丰五年（1082）七月既望与十月之望，前后《赤壁赋》成。","impact":"黄州之谪四年，而轼之文与书始定其格；二赋与《念奴娇》一词为宋文最传者，而赤壁之名自是亦属之黄州，非复建安之战迹。","figures":["苏轼","李定","舒亶"],"place":"黄州（今湖北黄冈）","state":"北宋","sources":["《宋史·苏轼传》","《前赤壁赋》","《后赤壁赋》"],"tags":["苏轼","黄州","赤壁赋","元丰五年"]},"related":[],"checks":[{"by":"本站·维基文库比对（《宋史》卷三百三十八·苏轼传）","at":"2026-11-07","note":"原文「御史李定、舒亶、何正臣摭其表语……逮赴台狱」「神宗独怜之，以黄州团练副使安置。轼与田父野老，相从溪山间，筑室于东坡，自号东坡居士」"},{"by":"本站·维基文库比对（《前赤壁赋》《后赤壁赋》正文，维基文库二页皆自注出《古文观止》卷十一宋文）","at":"2026-11-07","note":"前赋自书「壬戌之秋，七月既望」，壬戌即1082，本条之年取此；后赋作「是岁十月之望」，是岁承壬戌，故process两日并列。旧题作「苏轼谪黄州，赋赤壁」，谪在元丰三年、赋在元丰五年，本条系年仅据赋序，题已改从赋；summary「坐诗」改「以诗」，从本传「以诗托讽」之文"}]},
  {"id":"cn--1084--c01","track":"cn","year":1084,"yearApprox":false,"dim":"culture","weight":3,"title":"《资治通鉴》书成","summary":"十九年而书成，自周威烈王至显德，二百九十四卷。","detail":{"background":"司马光以治平间进《通志》八卷，英宗命续之；熙宁以来退居洛阳十五年，设书局于崇文院之外，以刘攽、刘恕、范祖禹分任汉、魏以降、唐五代之事。","process":"1084年（元丰七年）十二月《资治通鉴》上之，凡二百九十四卷、目录考异各三十卷，起周威烈王二十三年、尽五代显德之末；神宗以其「鉴于往事，有资于治道」赐名。","impact":"编年一体至是复尊，其后袁枢因之为纪事本末，朱熹因之为《通鉴纲目》；其《考异》一门并蓄异同而以意决之，为后世史家考证之法所自出。","figures":["司马光","刘攽","刘恕","范祖禹","神宗赵顼"],"place":"洛阳、开封（今河南洛阳、开封）","state":"宋","sources":["《资治通鉴》","《宋史·司马光传》","《邵氏闻见录》","《剑桥中国宋代史》"],"tags":["资治通鉴","编年体","司马光"]},"related":[]},
  {"id":"cn--1088--s01","track":"cn","year":1088,"yearApprox":true,"dim":"science","weight":3,"title":"沈括记磁针指南与常微偏东","summary":"以磁石磨针锋则能指南，然常微偏东，不全南也。","detail":{"background":"方家以磁石磨针锋使指南，其法世传而未有着于书者；沈括（1031—1095）历典考课、军器，奉使河北、京东，所至以物验之，晚居润州梦溪园笔于书。","process":"《梦溪笔谈》记置针之法：水浮者「多荡摇」，指爪与碗唇上皆可为之，「运转尤速」然「坚滑易坠」，故断之曰「不若缕悬为最善」——以新纩独茧缕沾芥子油缀针于蒂，于无风处悬之；又自验其向，谓针既指南「然常微偏东，不全南也」。","impact":"以明文记下磁针所指与真南之差，是把磁北、真北之别当作可复验之事来写的较早记录；其后舟师「阴晦观指南针」（cn--1119--x01）与宋元针路之制，其器与其法皆承此系。","figures":["沈括"],"place":"润州梦溪园（今江苏镇江）","state":"北宋","sources":["《梦溪笔谈·杂志一》","《萍洲可谈》"],"tags":["磁针","指南针","磁偏角"]},"related":["cn--1044--s01","cn--1119--x01"]},
  {"id":"cn--1089--f01","track":"cn","year":1089,"yearApprox":false,"dim":"figure","weight":3,"title":"苏轼知杭州，浚湖筑堤","summary":"以茭田之议开西湖，横截湖上为长堤。","detail":{"background":"轼自中书舍人出知杭州，时湖为菱苇所塞，水无所受，城中运河且浅；公帑方匮而工役难兴。","process":"1089年（元祐四年）轼至杭州，请开西湖，请以开湖之茭田募民为之，又因故址为长堤以便行者，植菱种鱼以绝再生之葑；明年堤成，人号苏公堤。","impact":"此以工役理财、以水利养城之一例，为南宋以后守土言水利者所本；轼之诗文、书与画由其人格而为一派，宋以后所谓苏学由杭州、黄州、惠州、儋州四地而成其叙事。","figures":["苏轼","吕大防","曾肇"],"place":"杭州（今浙江杭州）","state":"宋","sources":["《苏轼文集》","《宋史·苏轼传》","《咸淳临安志》"],"tags":["苏轼","西湖","苏堤"]},"related":[]},
  {"id":"cn--1103--s01","track":"cn","year":1103,"yearApprox":false,"dim":"science","weight":4,"title":"李诫成《营造法式》","summary":"以材分为等差，功限、料例与看样并行。","detail":{"background":"元祐间敕有司考修营之制，将作监李诫以诸司匠者相传之例多所舛误，公私等级莫相考核，乃取见行之约束、质之于匠而编之。","process":"1103年（崇宁二年）《营造法式》三十六卷刊行：释名、各作制度、功限、料例、图样相次，以「材分」为一切度数之母，凡大木作、石作、彩画作、窑作之属皆有其等。","impact":"此为现存最完整之官定建筑技术书，其以模数控制工料之法，兼为财政之防；宋、金、元木构之遗例多得其印证，且为东亚建筑史上极少数有官定明文可据之本。","figures":["李诫","徽宗赵佶","赫鞏"],"place":"开封（今河南开封）","state":"宋","sources":["《营造法式》","《宋史·艺文志》","梁思成《营造法式注释》","《剑桥中国宋代史》"],"tags":["营造法式","李诫","模数制"]},"related":[]},
  {"id":"cn--1110--a01","track":"cn","year":1110,"yearApprox":true,"dim":"art","weight":3,"title":"张择端图《清明上河图》","summary":"汴河上下五里，市桥船车，纤悉可数。","detail":{"background":"徽宗建翰林图画院，天下艺士以画待诏；张择端以「幼读书、后习画」入院，习界画楼台。","process":"政和、宣和间（约一一一〇年前后）择端作《清明上河图》卷，自虹桥至宣德门，所画舟车、门户、铺卖、医卜、僧道、胥吏、妇人、小儿以数百十计；卷后有金张著跋，始知其里贯。","impact":"此卷为研究汴京城市、漕运、桥梁、舟船、幌与商肆之第一手图像，坊市既坏以后街市之盛尽在其中；其制作年代与「上河」之义，学界至今聚讼不一。","figures":["张择端","赵佶","张著"],"place":"汴京（今河南开封）","state":"宋","sources":["《清明上河图》卷及金人题跋","《宋史·徽宗纪》","《东京梦华录》","《石渠宝笈》"],"tags":["清明上河图","界画","汴京市井"]},"related":[]},
  {"id":"cn--1115--p01","track":"cn","year":1115,"yearApprox":false,"dim":"politics","weight":4,"title":"完颜阿骨打建金","summary":"以抗辽之师即皇帝位，定国号为金。","detail":{"background":"女真完颜部自乌古迺以来并诸部，阿骨打以三千户起兵破辽于出河店、达赉湖，诸部请号。","process":"1115年（收国元年）正月，完颜阿骨打即皇帝位，国号大金，以猛安谋克为军政合一之制：三百户为谋克、十谋克为猛安，其首领世袭，兵农一职；又命完颜希尹即汉字减省而制女真大字。","impact":"女真以一小部三十年而并辽、取宋之半壁，其以猛安谋克处兵、以汉官治民、后又迁都于燕、于汴之二元办法，为北方征服王朝制度之一大样本。","figures":["完颜阿骨打","完颜希尹","斡鲁","辽天祚帝"],"place":"会宁（今黑龙江哈尔滨阿城）","state":"金","sources":["《金史·太祖纪》","《三朝北盟会编》","《续资治通鉴长编》","《剑桥中国辽西夏金元史》"],"tags":["金建国","猛安谋克","女真大字"]},"related":[]},
  {"id":"cn--1119--x01","track":"cn","year":1119,"yearApprox":false,"dim":"explore","weight":3,"title":"《萍洲可谈》：舟师以指南针行海","summary":"阴晦则观指南针，海舶之专任司南始见于此。","detail":{"background":"朱彧父服为广州帅，其少年时亲见海舶之规；自广州放洋，东南诸国皆以针路取道。","process":"1119年（宣和元年）朱彧成《萍洲可谈》，记广州海舶云：舟师识地理，夜则观星、昼则观日、阴晦观指南针，以其为命之所系，故掌针者最为慎事。","impact":"此为指南针用于航海最早、最明白之记载；由是占城、三佛齐、大食诸国之航路可由针经相传，南宋泉州之盛与市舶之入皆以是为本，亦为海上丝路自唐末至元所以大成的技术关键。","figures":["朱彧","朱服","蒲啰辛"],"place":"广州（今广东广州）","state":"宋","sources":["《萍洲可谈》","《宋会要辑稿·职官》","《诸蕃志》","《剑桥中国宋代史》"],"tags":["指南针","航海","广州市舶"]},"related":[]},
  {"id":"cn--1126--d01","track":"cn","year":1126,"yearApprox":false,"dim":"disaster","weight":3,"title":"汴京围城，城中大疫","summary":"内外不通，死者相枕于路，医药俱穷。","detail":{"background":"金人以重兵两度围汴，城中之众号数十万，柴米、医药一切仰外；自闰十一月城陷后，尸骸不得出城。","process":"1126年（靖康元年）冬围城数月，城中疫大作，贫乏者无以自给；城破之后，死者相枕藉于衢路，有司以官为瘗之而不足。《会编》所记日死者以万计，学者多以为其数过当，然疫之烈无可疑。","impact":"汴京一疫与一屠，使北方第一大城及其图籍、百工、财货尽归消耗；宋室南渡以后，太医局之方书、坊巷之工匠皆移于临安，中国都市与医学之重心自此南移。","figures":["钦宗赵桓","王时雍","梅执礼"],"place":"汴京（今河南开封）","state":"宋","sources":["《三朝北盟会编》","《宋史·钦宗纪》","《建炎以来系年要录》","《靖康小雅》"],"tags":["靖康之围","汴京大疫","城市人口"]},"related":[]},
  {"id":"cn--1127--p01","track":"cn","year":1127,"yearApprox":false,"dim":"politics","weight":5,"title":"靖康之变：二帝北行，宋室南渡","summary":"徽、钦二帝并宗室北迁，康王即位于南京。","detail":{"background":"金人以宋纳叛、欠币为辞再举南下，河北、河东诸兵不得集；闰十一月外城陷，钦宗亲至金营，和议之数愈索愈无穷。","process":"1127年（靖康二年、建炎元年）四月，金人取徽宗、钦宗并后妃、宗室、百官三千余人北迁，载图籍、天文仪器、百工与府库以去；五月康王即位于南京应天府，改元建炎，宋之半壁入于南方。","impact":"此为北宋之终：汴京之政治、财政与文化中枢一旦北徙，江南遂有行都、太学与市舶之盛；而和战、淮汉之防与武人之起，皆成南宋一朝不可解之结。","figures":["赵构","徽宗赵佶","钦宗赵桓","粘罕","张邦昌"],"place":"汴京、应天府、临安（今河南开封、商丘、杭州）","state":"宋","sources":["《宋史·高宗纪》","《三朝北盟会编》","《建炎以来系年要录》","《靖康稗史》"],"tags":["靖康之变","宋室南渡","建炎"]},"related":[]},
  {"id":"cn--1135--f01","track":"cn","year":1135,"yearApprox":true,"dim":"figure","weight":3,"title":"李清照成《金石录后序》","summary":"记与明诚校勘金石、南奔失书，一家之聚散。","detail":{"background":"清照归赵明诚，两以校书、录金石为乐，集古器碑刻至二千卷；靖康之变，书在青州者先毁，明诚建康之任又死。","process":"绍兴中（一一三五年前后）清照作《金石录后序》，自叙既嫁之后与明诚共校金石、既奔之后独守残编之事，又叙其在杭州讼离之狱；《金石录》三十卷由是以传。","impact":"其文为一时士族妇女之自述，所记藏書之聚散即北宋文物一次大流失之实录；其词自名一家，《词论》以别材别趣论词，为词学批评之要篇。","figures":["李清照","赵明诚","张汝舟"],"place":"临安、青州（今浙江杭州、山东青州）","state":"宋","sources":["《金石录后序》","《直斋书录解题》","《建炎以来系年要录》","《漱玉词》"],"tags":["李清照","金石学","女性书写"]},"related":[]},
  {"id":"cn--1140--m01","track":"cn","year":1140,"yearApprox":false,"dim":"military","weight":4,"title":"郾城、颍昌之捷与班师","summary":"以背嵬破铁浮图，而金字牌趣还。","detail":{"background":"金人废刘豫而复以陕西予宋为和，完颜宗弼以一路之兵南下；岳飞请以荆襄之众由河北应诸路义军，议不复合。","process":"1140年（绍兴十年）七月，岳飞与金相持于郾城、颍昌，以麻扎刀、提刀大斧断马足，破其铁浮图、拐子马，宗弼收兵还汴京；旋以金字牌趣班师，鄂州之众一日而十二道并至。","impact":"宋军野战始有此胜，故和议之可得亦以此；而班师之诏与后来之狱，使南宋之兵权复归于御前，诸将之兵皆为朝廷之兵，其效与其害并见于百年之间。","figures":["岳飞","完颜宗弼","张宪","岳云","赵构"],"place":"郾城、颍昌（今河南漯河、许昌）","state":"宋","sources":["《宋史·岳飞传》","《鄂国金佗稡编》","《建炎以来系年要录》","《金史·宗弼传》"],"tags":["郾城之战","岳家军","班师之诏"]},"related":[]},
  {"id":"cn--1141--p01","track":"cn","year":1141,"yearApprox":false,"dim":"politics","weight":4,"title":"绍兴和议：划淮而治","summary":"东称臣、岁贡银绢二十五万，以淮水大散关为界。","detail":{"background":"金人以「诏旨取岳飞」为和之条件，秦桧独当国议；诸将兵柄已收，朝廷以岁币换东南之财赋。","process":"1141年（绍兴十一年）十一月和议成：宋帝拜金诏而称臣，岁以银、绢各二十五万匹两输之，东以淮水中流、西以大散关为界，河南之地复归于金；明年正月岳飞死于狱。","impact":"此约以岁币与称臣换得江南百年之基，二浙、福建、广南之财赋与市舶得养一大都；而其内则成秦氏之政，士大夫之议恢复者以讪谤得罪，宋金之界遂定于淮汉。","figures":["秦桧","赵构","完颜兀术","何铸","万俟卨"],"place":"临安、汴京（今浙江杭州、河南开封）","state":"宋","sources":["《宋史·秦桧传》","《建炎以来系年要录》","《大金国志》","《宋会要辑稿·蕃夷》"],"tags":["绍兴和议","岁币","宋金界"]},"related":[]},
  {"id":"cn--1161--m01","track":"cn","year":1161,"yearApprox":false,"dim":"military","weight":3,"title":"采石之胜与完颜亮之死","summary":"允文以儒臣督师，舟师截江，亮为下所弑。","detail":{"background":"金主亮尽徙河北之民、悉诸道之兵南来，和议遂绝；王权弃庐州而南，和州之兵无主，虞允文以督视府参谋军事至采石犒师。","process":"1161年（绍兴三十一年）十一月，允文以溃卒为行列，以艨艟踏车截江，金舟不得渡；金师不得济而哗，亮为其下斡勒氏所弑于瓜洲，金军北还，淮南解严。","impact":"宋以半壁之兵再守淮、汉之约，金之南攻自此一挫；然朝廷以是年为和战之转关，武人之任与言路之议并起，南宋之主和之局因之以定。","figures":["虞允文","完颜亮","王权","叶义问"],"place":"采石、瓜洲（今安徽马鞍山、江苏扬州南）","state":"宋","sources":["《宋史·虞允文传》","《金史·完颜亮传》","《建炎以来系年要录》","《朝野杂记》"],"tags":["采石之战","虞允文","完颜亮之弑"]},"related":[]},
  {"id":"cn--1190--c01","track":"cn","year":1190,"yearApprox":true,"dim":"culture","weight":4,"title":"朱熹刻《四书章句集注》","summary":"以《大学》《中庸》《语》《孟》为一书之序。","detail":{"background":"熹自乾道以来编次《论孟集义》《中庸章句》，以道统相续为意；湖南、福建讲学日盛，而学禁之议亦起于朝。","process":"淳熙、绍熙间（约一一九〇年前后）熹定《四书章句集注》，以《大学》为先入之序、以格物致知为补传，刻于漳州；其《诗集传》《通鉴纲目》与《楚辞集注》并出。","impact":"自是《四书》代《五经》而为举业之本，理气、心性之学有课本可循；嘉定以后由禁而用，理宗朝以熹配享，元代遂以朱《注》取士，其后明清科举之文八百年不易。","figures":["朱熹","吕祖谦","陆九龄","陈亮"],"place":"建阳、漳州（今福建建瓯、漳州）","state":"宋","sources":["《四书章句集注》","《朱子语类》","《宋史·道学传》","钱穆《朱子新学案》"],"tags":["四书集注","朱熹","道学"]},"related":[]},
  {"id":"cn--1200--s01","track":"cn","year":1200,"yearApprox":true,"dim":"science","weight":3,"title":"泉州海船以横隔板分若干舱","summary":"船腹横板为隔，一舱破漏而水不得遍及其余。","detail":{"background":"宋元自泉州、庆元放洋之船，大者载货以万计，须分舱以理压载、以御漏，又便于按舱分货与抽验；其制不着于文典，而见于出土船体。","process":"1974 年泉州湾后渚港出土一艘宋代之船，残存船体以横向隔板分为十余舱位，隔舱板与船壳板钉联，缝中以竹绒、桐油、石灰之类艌之使水密；两舷以多重板叠砌，先布壳而后架骨架，与地中海、北欧以整木刳凿为体者自为二途。","impact":"分舱之后一处破漏不致全船进水，兼得分货、压载与查漏之便；此原则为近代铁船与今日船舶水密分舱、载重线规程所沿用。隔舱与多重船壳是宋元海船得以远泛的技术前提之一，泉州湾之出土为其最完整之实证。","figures":["泉州湾宋船发掘队"],"place":"泉州湾后渚港（今福建泉州丰泽）","state":"南宋—元","sources":["1974 年泉州湾后渚港宋代海船发掘报告","福建省泉州海外交通史博物馆藏船实物"],"tags":["水密隔舱","海船","泉州"]},"related":["cn--1119--x01","cn--1277--e01"]},
  {"id":"cn--1225--x01","track":"cn","year":1225,"yearApprox":false,"dim":"explore","weight":2,"title":"赵汝适《诸蕃志》成","summary":"宝庆元年，以朝散大夫提举福建路市舶，询诸贾胡而成书。","detail":{"background":"泉州为海舶之聚，诸国之人至者众，而官其地者多不辨其国名、风土与道里。汝适以朝散大夫提举福建路市舶。","process":"宝庆元年（1225）九月，赵汝适序其书：迺询诸贾胡，俾列其国名，道其风土，名曰《诸蕃志》。","impact":"自贾耽《古今郡国县道四夷述》而后，宋人所纪海外诸国最备者是也；后之考南海贸易与市舶之目者皆取焉。其书不自经验来，一国之目、一道之里皆询诸贾胡而书之，故所长在胪列名物，所短在传闻多误。","figures":["赵汝适"],"place":"泉州（今福建泉州）","state":"南宋","sources":["《诸蕃志·序》","《旧唐书·贾耽传》"],"tags":["诸蕃志","泉州市舶","宝庆元年","海外诸国"]},"related":[],"checks":[{"by":"本站·维基文库比对（《诸蕃志·赵汝适序》）","at":"2026-11-07","note":"序末「宝庆元年九月日，朝散大夫提举福建路市舶赵汝适序」，又「迺询诸贾胡，俾列其国名，道其风土……名曰诸蕃志」；官名从序作「福建路市舶」，提要之「泉州市舶」系后之通称，summary 今正从序；引文「名曰诸蕃志」，该页作「名日」，形近之讹，今从通行本，异文记此"},{"by":"本站·维基文库比对（《旧唐书》卷一百三十八·贾耽传）","at":"2026-11-07","note":"原文「至十七年，又撰成《海内华夷图》及《古今郡国县道四夷述》四十卷，表献之」；impact 旧记作「县国」系误字，今据传改正，并补此书为出处"}]},
  {"id":"cn--1227--p01","track":"cn","year":1227,"yearApprox":false,"dim":"politics","weight":3,"title":"西夏亡于大蒙古国","summary":"中兴府以地震、兵饥而降，末主死之。","detail":{"background":"夏自仁孝以后国势渐削，神宗遵顼数以空国之兵犯金、附蒙；蒙人六入其境，田畴荒芜而兴、灵地震连岁。","process":"1227年（宝义二年、正大四年）六月，夏末主李睍出降，寻被杀，夏自景宗显宁改号以来百九十年而亡；其宫室、典籍多毁于兵，七月太祖崩于清水。","impact":"西北一角自此空虚，蒙人遂得由西夏之故道绕金之南，并得回鹘、西域之道；夏之文字、法典由是久成绝学，其文献多存于黑水城之出土，今为西夏学之本。","figures":["李睍","遵顼","神宗李纯祐","成吉思汗"],"place":"中兴府（今宁夏银川）","state":"西夏","sources":["《宋史·夏国传》","《金史·哀宗纪》","《元史·太祖纪》","《剑桥中国辽西夏金元史》"],"tags":["西夏亡","中兴府","黑水城文书"]},"related":["world--1227--f01"]},
  {"id":"cn--1234--m01","track":"cn","year":1234,"yearApprox":false,"dim":"military","weight":3,"title":"蔡州城破金亡，端平入洛","summary":"宋、蒙合攻蔡而金灭，旋有汴、洛之败。","detail":{"background":"金自汴京南奔，以完颜陈和尚、合达之死而诸军皆尽；宋以宿仇，输米以助蒙人之攻。","process":"1234年（端平元年、天兴三年）正月，蒙、宋合围蔡州，城破，金主自尽，完颜承麟死之，金亡；六月宋军以复三京为名入汴、进而至洛，粮道不继，为蒙人所覆于卫州之南。","impact":"唇齿既亡而宋之边直接于蒙古，端平一败既失汴、洛之粟与兵，又启蒙人南牧之名；此后四十五年，宋以淮、江、蜀三口受敌而终不可支。","figures":["完颜承麟","金哀宗","赵范","全子才","孟珙"],"place":"蔡州、洛阳（今河南汝南、洛阳）","state":"宋","sources":["《金史·哀宗纪》","《宋史·理宗纪》","《续资治通鉴》","《元史·太宗纪》"],"tags":["金亡","端平入洛","宋蒙联盟"]},"related":[]},
  {"id":"cn--1247--s01","track":"cn","year":1247,"yearApprox":false,"dim":"science","weight":3,"title":"《洗冤集录》与《数书九章》并成","summary":"验尸有书，大衍求一有术，淳祐七年两册。","detail":{"background":"宋慈以累任刑狱，见提点官不亲至尸所、胥吏因缘为奸，乃荟萃累朝条格与亲验所得；秦九韶则以蜀中军政之需，集数学之大成。","process":"1247年（淳祐七年）宋慈成《洗冤集录》五卷，自验伤、辨溺、别缢以及救急诸法，皆出目见；同年秦九韶成《数书九章》九卷，列大衍求一术、正负开方术以究历数与田、税、军食之算。","impact":"前者为世界最早之系统法医学专书，元、明之刑狱皆本其目，并东传日、西传欧西而有译本；后者之大衍求一术即一次同余式之一般解法，为正负开方即高次方程数值解之先声，为中国算学之最精者。","figures":["宋慈","秦九韶"],"place":"湖南、杭州（今湖南、浙江杭州）","state":"宋","sources":["《洗冤集录》","《数书九章》","《宋史·理宗纪》","李约瑟《中国科学技术史》"],"tags":["法医学","大衍求一术","淳祐"]},"related":[]},
  {"id":"cn--1259--m01","track":"cn","year":1259,"yearApprox":false,"dim":"military","weight":3,"title":"蒙哥崩于钓鱼城下","summary":"合州九十天而城不下，宪宗以是殂于军。","detail":{"background":"蒙人以绕西南之策由吐蕃、大理包宋之背，宪宗亲率入蜀，连陷苦竹隘、大获；王坚以余玠所筑山城之守，独当合州。","process":"1259年（开庆元年、己未）二月至七月，蒙军攻钓鱼山（今重庆合川东）之城，王坚、张珏乘城拒守九十余日，久不能下；七月宪宗崩于军前，诸道蒙军遂北归。","impact":"蒙哥之死使忽必烈与阿里不哥争位，西亚之旭烈兀亦东还，蒙古之东西两路攻势同时中止；宋延二十年之命实基于此，而四川山城之制自此为东南所效。其死因或言中创、或言疫，载籍异辞。","figures":["蒙哥","王坚","张珏","余玠","忽必烈"],"place":"钓鱼山、合州（今重庆合川）","state":"宋","sources":["《宋史·理宗纪》","《元史·宪宗纪》","《续资治通鉴》","《剑桥中国辽西夏金元史》"],"tags":["钓鱼城","蒙哥之死","山城防御"]},"related":[]},
  {"id":"cn--1260--p01","track":"cn","year":1260,"yearApprox":false,"dim":"politics","weight":3,"title":"世祖尊八思巴为国师","summary":"中统元年即位，尊为国师，授以玉印，命制蒙古新字。","detail":{"background":"帝师八思巴者，土番萨斯迦人，族款氏；自其祖朵栗赤以其法佐国主霸西海者十余世。生七岁，诵经数十万言，国人号之圣童。岁癸丑，年十有五，谒世祖于潜邸，与语大悦，日见亲礼。","process":"中统元年（1260），世祖即位，尊八思巴为国师，授以玉印，命制蒙古新字，字成上之；至元六年（1269）诏颁行于天下。","impact":"元以僧主土番之政自此始：郡县其地，设官分职而领之于帝师，宣政院之置由此，于是帝师之命与诏敕并行于西土；而蒙古新字一代之制亦系于是一印之授。","figures":["八思巴","忽必烈"],"place":"萨迦（今西藏日喀则萨迦）","state":"南宋—元","sources":["《元史·释老传》"],"tags":["八思巴","帝师","蒙古新字","中统元年"]},"related":["world--1260--p01"],"checks":[{"by":"本站·维基文库比对（《元史》卷二百二·释老传）","at":"2026-11-07","note":"原文「中统元年，世祖即位，尊为国师，授以玉印。命制蒙古新字，字成上之」「至元六年，诏颁行于天下」，本条系年直取「中统元年」即1260，非以即位数年推系（旧记作「以即位数年系1260」今正）；又本传「帝师八思巴者，土番萨斯迦人，族款氏也。相传自其祖朵栗赤，以其法佐国主霸西海者十余世」「岁癸丑，年十有五，谒世祖于潜邸，与语大悦，日见亲礼」「乃郡县土番之地，设官分职，而领之于帝师。乃立宣政院」「于是帝师之命，与诏敕并行于西土」，背景与影响皆取此。旧稿所云「萨班随阔端东来，其法已行于王邸」本传无其文，今删；「释教总制」一名也非本传所有，同时删"}]},
  {"id":"cn--1267--m01","track":"cn","year":1267,"yearApprox":false,"dim":"military","weight":3,"title":"襄樊之围：五年而城陷","summary":"蒙人以长围锁汉，回回炮至而樊先破。","detail":{"background":"吕文焕以襄阳守五年，蒙人以张嘉努之策筑堡连营、置万山长围于汉水之上，又造舟练兵以断江面。","process":"1267年（咸淳三年）蒙军围襄阳，浸及樊城；宋之援师屡为所却，张顺、张贵以死战不得达。咸淳九年（1273）以回回炮击樊，一日而城破，襄阳孤而遂降。","impact":"襄、樊既失，宋之长江上游之锁与汉沔之险尽去，元军自此顺流东下，建康、临安皆不可守；此围亦示以攻城之炮、水陆之围与长期之供给结合之新形态。","figures":["吕文焕","阿术","刘整","张顺","亦思马因"],"place":"襄阳、樊城（今湖北襄阳、樊城）","state":"宋","sources":["《宋史·吕文焕传》","《元史·阿术传》","《续资治通鉴》","《心史》"],"tags":["襄樊之战","回回炮","刘整"]},"related":[]},
  {"id":"cn--1276--p01","track":"cn","year":1276,"yearApprox":false,"dim":"politics","weight":3,"title":"临安降，二王南走","summary":"谢太后以玺与版图降，益、广二王南奔。","detail":{"background":"贾似道既败于丁家洲，三镇皆空；谢太后以幼主当国，使使请称侄、请削号而不得，宗室之议两歧。","process":"1276年（德祐二年、景炎元年）正月，临安城降，伯颜入据之，索图籍、府库；二月迁宋主及全太后于大都，益王昰、广王昺南走，五月即位于福州，改元景炎。","impact":"江南自钱氏纳土以来三百年不复兵革之地，一降而府库、图籍、百工、宗室尽北；而闽、广之海上行朝犹立两年，文天祥、陆秀夫之起兵皆系于此时。","figures":["谢太后","赵㬎","伯颜","赵昰","陆秀夫"],"place":"临安、福州（今浙江杭州、福建福州）","state":"宋","sources":["《宋史·瀛国公纪》","《元史·世祖纪》","《钱塘遗事》","《昭忠录》"],"tags":["德祐之降","临安","二王南走"]},"related":[]},
  {"id":"cn--1278--x01","track":"cn","year":1278,"yearApprox":false,"dim":"explore","weight":3,"title":"蒲氏以泉州降，市舶归于北","summary":"泉州以海商之众附元，海上之利自此易主。","detail":{"background":"泉州自唐末以来为海舶之聚，蒲寿庚兄弟以香药之利三十年，累官至福建安抚；朝廷之军资、行朝之舟师皆有所赖。","process":"1278年（景炎三年、至元十五年）冬，蒲寿庚以泉州降于元，杀南来之宗室与淮兵，海商之众不复为宋；明年元立泉州市舶司，招海中商贾，依旧例而抽解其货。","impact":"南宋最后之财赋与舟师之根自是而绝，而行朝不得沿海之助；泉州由是代广州为海上丝路之首口，元之市舶与海外之征伐皆由此发，其利病直至明初海禁。","figures":["蒲寿庚","蒲寿宬","唆都","赵昺"],"place":"泉州（今福建泉州）","state":"宋","sources":["《元史·世祖纪》","《宋史·瀛国公纪》","《闽书》","《岛夷志略》"],"tags":["泉州市舶","蒲寿庚","海上丝路"]},"related":[]},
  {"id":"cn--1278--f01","track":"cn","year":1278,"yearApprox":false,"dim":"figure","weight":4,"title":"文天祥被执于五坡岭","summary":"空坑之败后收兵再战，粮尽被执。","detail":{"background":"天祥自德祐奉使留军，间道走永嘉，以故官开府于南剑，复汀、赣州之邑，而兵皆乌合；部将先遁，空坑一败，妻子尽没。","process":"1278年（景炎三年、至元十五年）十二月，元兵袭潮阳五坡岭，天祥仓卒被执，咽冰而不得死，遂以所著《过零丁洋》之诗与《正气歌》之志自明；明年正月过零丁洋，二月至崖山。","impact":"文、陆之死为宋之终局立其人格之据，其《指南录后序》以一身所历写一国之亡，为宋末纪事最切之文；其被执与死事，元、明之史臣与后世之祠祭皆奉为忠之极。","figures":["文天祥","张弘范","陆秀夫","邓剡"],"place":"潮阳、五坡岭（今广东海丰、潮阳）","state":"宋","sources":["《文山先生全集》","《宋史·文天祥传》","《昭忠录》","《续资治通鉴》"],"tags":["文天祥","五坡岭","宋末忠节"]},"related":[]},
];
